      tx.user.findUnique({
        where: { email: dto.email },
      }),
    );
    if (existing)
      throw new ConflictException(
        `User with email ${dto.email} already exists`,
      );

    const tempPassword = crypto.randomBytes(16).toString('hex');
    const hashedPassword = await bcrypt.hash(tempPassword, 10);

    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.create({
        data: {
          companyId,
          email: dto.email,
          firstName: dto.firstName,
          lastName: dto.lastName,
          password: hashedPassword,
          status: 'INVITED',
          roleId: dto.roleId,
          departmentId: dto.departmentId,
          teamId: dto.teamId,
          costCenterId: dto.costCenterId,
          preferences: {
            invitationToken: crypto.randomBytes(32).toString('hex'),
            invitedBy: adminUserId,
          },
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:user:invite',
      entity: 'User',
      entityId: user.id,
      userId: adminUserId,
      companyId,
      details: { email: dto.email, roleId: dto.roleId },
    });

    return {
      id: user.id,
      email: user.email,
      status: user.status,
      invitationSent: true,
    };
  }

  async bulkImportUsers(
    companyId: string,
    dto: BulkUserImportDto,
    adminUserId: string,
  ) {
    const results = {
      imported: 0,
      failed: 0,
      errors: [] as { email: string; reason: string }[],
    };

    for (const u of dto.users) {
      try {
        await this.inviteUser(companyId, u, adminUserId);
        results.imported++;
      } catch (e: any) {
        results.failed++;
        results.errors.push({
          email: u.email,
          reason: e.message || 'Import error',
        });
      }
    }

    await this.audit.logEvent({
      action: 'admin:user:bulk_import',
      entity: 'User',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: { imported: results.imported, failed: results.failed },
    });

    return results;
  }

  async exportUsers(companyId: string) {
    const users = await this.getUsers(companyId);
    return {
      exportedAt: new Date().toISOString(),
      total: users.length,
      users,
    };
  }

  async suspendUser(
    companyId: string,
    targetUserId: string,
    dto: UserStatusActionDto,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    const updated = await this.prisma.runAsSystem(async (tx) =>
      tx.user.update({
        where: { id: targetUserId },
        data: { status: 'SUSPENDED' },
      }),
    );

    await this.forceLogout(companyId, targetUserId, adminUserId);

    await this.audit.logEvent({
      action: 'admin:user:suspend',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { reason: dto.reason || 'Admin suspension' },
    });

    return updated;
  }

  async activateUser(
    companyId: string,
    targetUserId: string,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    const updated = await this.prisma.runAsSystem(async (tx) =>
      tx.user.update({
        where: { id: targetUserId },
        data: { status: 'ACTIVE' },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:user:activate',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { previousStatus: user.status },
    });

    return updated;
  }

  async lockUser(
    companyId: string,
    targetUserId: string,
    dto: UserStatusActionDto,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    const updated = await this.prisma.runAsSystem(async (tx) =>
      tx.user.update({
        where: { id: targetUserId },
        data: { status: 'LOCKED' },
      }),
    );

    await this.forceLogout(companyId, targetUserId, adminUserId);

    await this.audit.logEvent({
      action: 'admin:user:lock',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { reason: dto.reason || 'Admin lock' },
    });

    return updated;
  }

  async unlockUser(
    companyId: string,
    targetUserId: string,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    const updated = await this.prisma.runAsSystem(async (tx) =>
      tx.user.update({
        where: { id: targetUserId },
        data: { status: 'ACTIVE' },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:user:unlock',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { previousStatus: user.status },
    });

    return updated;
  }

  async forceLogout(
    companyId: string,
    targetUserId: string,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    await Promise.all([
      this.prisma.runAsSystem(async (tx) =>
        tx.refreshToken.deleteMany({ where: { userId: targetUserId } }),
      ),
      this.prisma.runAsSystem(async (tx) =>
        tx.trustedDevice.deleteMany({ where: { userId: targetUserId } }),
      ),
    ]);

    await this.audit.logEvent({
      action: 'admin:user:force_logout',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { revokedAllTokensAndSessions: true },
    });

    return {
      success: true,
      message: `All sessions revoked for user ${targetUserId}`,
    };
  }

  async forcePasswordReset(
    companyId: string,
    targetUserId: string,
    adminUserId: string,
  ) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    const currentPrefs = (user.preferences || {}) as Record<string, any>;
    const updatedPrefs = {
      ...currentPrefs,
      passwordResetRequired: true,
      forceResetAt: new Date().toISOString(),
    };

    await this.prisma.runAsSystem(async (tx) =>
      tx.user.update({
        where: { id: targetUserId },
        data: { preferences: updatedPrefs },
      }),
    );

    await this.forceLogout(companyId, targetUserId, adminUserId);

    await this.audit.logEvent({
      action: 'admin:user:force_password_reset',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { passwordResetRequired: true },
    });

    return {
      success: true,
      message: `Password reset enforced for user ${targetUserId}`,
    };
  }

  async resetMfa(companyId: string, targetUserId: string, adminUserId: string) {
    const user = await this.prisma.runAsSystem(async (tx) =>
      tx.user.findFirst({
        where: { id: targetUserId, companyId },
      }),
    );
    if (!user) throw new NotFoundException(`User ${targetUserId} not found`);

    await Promise.all([
      this.prisma.runAsSystem(async (tx) =>
        tx.backupCode.deleteMany({ where: { userId: targetUserId } }),
      ),
      this.prisma.runAsSystem(async (tx) =>
        tx.webAuthnCredential.deleteMany({ where: { userId: targetUserId } }),
      ),
      this.prisma.runAsSystem(async (tx) =>
        tx.user.update({
          where: { id: targetUserId },
          data: { mfaEnabled: false, totpSecret: null },
        }),
      ),
    ]);

    await this.audit.logEvent({
      action: 'admin:user:reset_mfa',
      entity: 'User',
      entityId: targetUserId,
      userId: adminUserId,
      companyId,
      details: { mfaReset: true },
    });

    return { success: true, message: `MFA reset for user ${targetUserId}` };
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { LlmManagerService } from '../platform/llm-manager.service';
import { ContextEngineService } from '../context/context-engine.service';
import { PromptProtectionService } from '../platform/prompt-protection.service';
import { AiGovernanceService } from '../governance/governance.service';
import { AiObservabilityService } from '../observability/observability.service';
import { EnterpriseMemoryService } from '../memory/memory.service';
import { EnterpriseRagService } from '../rag/rag.service';
import { BaseAgent } from './base.agent';
import { DispatcherAgent } from './specialized/dispatcher.agent';
import { FleetManagerAgent } from './specialized/fleet-manager.agent';
import { IntegrationAgent } from './specialized/integration.agent';
import { WarehouseAgent } from './specialized/warehouse.agent';
import { FinanceAgent } from './specialized/finance.agent';
import { ComplianceAgent } from './specialized/compliance.agent';
import { SupportAgent } from './specialized/support.agent';
import { DeveloperAgent } from './specialized/developer.agent';
import { AnalyticsAgent } from './specialized/analytics.agent';
import { MarketplaceAgent } from './specialized/marketplace.agent';
import { OperationsAgent } from './specialized/operations.agent';

@Injectable()
export class AgentOrchestratorService implements OnModuleInit {
  private readonly logger = new Logger(AgentOrchestratorService.name);
  private agents: Map<string, BaseAgent> = new Map();

  constructor(
    private readonly prisma: PrismaService,
    private readonly llmManager: LlmManagerService,
    private readonly contextEngine: ContextEngineService,
    private readonly promptProtection: PromptProtectionService,
    private readonly governance: AiGovernanceService,
    private readonly observability: AiObservabilityService,
    private readonly memory: EnterpriseMemoryService,
    private readonly rag: EnterpriseRagService,
    // ─── Specialized Agents ────────────────────────────────────────
    private readonly dispatcherAgent: DispatcherAgent,
    private readonly fleetAgent: FleetManagerAgent,
    private readonly integrationAgent: IntegrationAgent,
    private readonly warehouseAgent: WarehouseAgent,
    private readonly financeAgent: FinanceAgent,
    private readonly complianceAgent: ComplianceAgent,
    private readonly supportAgent: SupportAgent,
    private readonly developerAgent: DeveloperAgent,
    private readonly analyticsAgent: AnalyticsAgent,
    private readonly marketplaceAgent: MarketplaceAgent,
    private readonly operationsAgent: OperationsAgent,
  ) {}

  onModuleInit() {
    // Register all 11 specialized agents
    const allAgents: BaseAgent[] = [
      this.dispatcherAgent,
      this.fleetAgent,
      this.integrationAgent,
      this.warehouseAgent,
      this.financeAgent,
      this.complianceAgent,
      this.supportAgent,
      this.developerAgent,
      this.analyticsAgent,
      this.marketplaceAgent,
      this.operationsAgent,
    ];

    for (const agent of allAgents) {
      this.registerAgent(agent);
    }
    this.logger.log(
      `Agent Orchestrator initialized with ${this.agents.size} agents: [${Array.from(this.agents.keys()).join(', ')}]`,
    );
  }

  registerAgent(agent: BaseAgent) {
    this.agents.set(agent.agentName, agent);
    this.logger.log(`Registered agent: ${agent.agentName}`);
  }

  /**
   * Routes an intent to the most appropriate specialized agent.
   * Applies full governance pipeline: PII redaction → injection protection → routing → execution → output validation → audit.
   */
  async routeIntent(
    companyId: string,
    intent: string,
    domainEntity: string,
    entityId: string,
    userId?: string,
  ): Promise<{ response: string; agentName: string; citations?: any[] }> {
    this.logger.log(
      `Routing intent [${domainEntity}]: "${intent.substring(0, 80)}"`,
    );

    // 1. PII redaction
    const { redacted: redactedIntent } = this.governance.redactPii(intent);

    // 2. Prompt injection protection
    const safeIntent = this.governance.sanitizeInput(redactedIntent);

    // 3. Build entity context
    const context = await this.contextEngine.buildAiContext(
      companyId,
      domainEntity,
      entityId,
    );

    // 4. Retrieve conversation memory for continuity
    const conversationContext = entityId
      ? await this.memory.getConversationContext(entityId)
      : '';

    // 5. Retrieve workspace memory for org-level preferences
    const workspaceContext = await this.memory.getWorkspaceContext(companyId);

    // 6. RAG context from Knowledge Base (tenant-isolated)
    let ragContext = '';
    let citations: any[] = [];
    try {
      const ragResult = await this.rag.retrieveContext(safeIntent, {
        companyId,
        limit: 3,
      });
      ragContext = ragResult.context;
      citations = ragResult.citations;
    } catch {
      // RAG failure is non-blocking
    }

    // 7. Intelligent agent routing — LLM selects best agent based on intent
    const agentNames = Array.from(this.agents.keys()).join(', ');
    const routingPrompt = `You are an Agent Router for PariLink enterprise platform.
Available Agents: ${agentNames}
User Intent: ${safeIntent}
Domain Entity: ${domainEntity}

Select the SINGLE best agent name from the available agents list. 
Respond ONLY with the exact agent name, nothing else.`;

    let agentName: string;
    try {
      const routingResponse = await this.llmManager.generateResponse(
        routingPrompt,
        safeIntent,
      );
      agentName = routingResponse.trim().split('\n')[0].trim();
    } catch {
      // Fallback based on domain entity keyword matching
      agentName = this.keywordRoute(domainEntity, safeIntent);
    }

    // Validate the routed agent exists
    if (!this.agents.has(agentName)) {
      this.logger.warn(
        `Agent "${agentName}" not found — using keyword routing fallback`,
      );
      agentName = this.keywordRoute(domainEntity, safeIntent);
    }

    const agent = this.agents.get(agentName)!;

    // 8. Build enriched context for the agent
    const enrichedContext = {
      ...(typeof context === 'object' && context !== null ? context : {}),
      knowledgeBase: ragContext,
      conversationHistory: conversationContext,
      workspacePreferences: workspaceContext,
    };

    // 9. Execute via selected agent
    const response = await agent.process(safeIntent, enrichedContext);

    // 10. Output validation
    const { valid, violations } = this.governance.validateOutput(response);
    let finalResponse = response;
    if (!valid) {
      this.logger.warn(
        `Output policy violations: ${violations.map((v) => v.label).join(', ')}`,
      );
      finalResponse = `[Output filtered by AI Governance policy. Please rephrase your request.]`;
    }

    // 11. Audit log the interaction
    try {
      const agentRecord = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.aiAgent.findFirst(),
      );
      if (agentRecord) {
        await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.aiInteractionLog.create({
            data: {
              agentId: agentRecord.id,
              prompt: safeIntent,
              response: finalResponse,
              userId,
              companyId,
              sessionId: entityId,
            },
          }),
        );
      }
    } catch {
      // Non-blocking
    }

    return { response: finalResponse, agentName, citations };
  }

  /**
   * Keyword-based fallback routing when LLM routing fails.
   */
  private keywordRoute(domain: string, intent: string): string {
    const combined = `${domain} ${intent}`.toLowerCase();
    if (combined.match(/warehouse|inventory|dock|pick|put.?away|scan/))
      return 'WarehouseAgent';
    if (combined.match(/invoice|billing|payment|factoring|revenue|p&l|cost/))
      return 'FinanceAgent';
    if (
      combined.match(/compliance|hos|hours.of.service|dot|fmcsa|inspection|reg/)
    )
      return 'ComplianceAgent';
    if (combined.match(/support|ticket|help|issue|problem|escalat/))
      return 'SupportAgent';
    if (combined.match(/developer|api|sdk|code|endpoint|webhook|plugin/))
      return 'DeveloperAgent';
    if (combined.match(/analytic|trend|kpi|metric|report|insight/))
      return 'AnalyticsAgent';
    if (combined.match(/marketplace|app|install|integration/))
      return 'MarketplaceAgent';
    if (combined.match(/fleet|vehicle|truck|trailer|maintenance/))
      return 'FleetManagerAgent';
    if (combined.match(/dispatch|load|route|driver|assign|trip/))
      return 'DispatcherAgent';
    if (combined.match(/operation|exception|delay|approval|health/))
      return 'OperationsAgent';
    return 'DispatcherAgent'; // Ultimate fallback
  }

  /**
   * List all registered agents with their capabilities
   */
  getAgentRegistry(): Array<{
    name: string;
    description: string;
    toolCount: number;
  }> {
    return Array.from(this.agents.values()).map((a) => ({
      name: a.agentName,
      description: a.roleDescription,
      toolCount: a.tools.length,
    }));
  }
}

import { Logger } from '@nestjs/common';
import { LlmManagerService } from '../platform/llm-manager.service';
import { DynamicTool, DynamicStructuredTool } from '@langchain/core/tools';

export abstract class BaseAgent {
  abstract readonly agentName: string;
  abstract readonly roleDescription: string;
  abstract readonly tools: (DynamicTool | DynamicStructuredTool)[];

  protected readonly logger = new Logger(BaseAgent.name);

  constructor(protected readonly llmManager: LlmManagerService) {}

  /**
   * Processes a structured message or user query with Tool Support (Phase 5)
   */
  async process(message: string, context: any = {}): Promise<string> {
    this.logger.log(`[${this.agentName}] Processing Message`);

    // Inject tool descriptions into prompt
    const toolDescriptions = this.tools
      .map((t) => `- ${t.name}: ${t.description}`)
      .join('\n');

    const systemPrompt = `
      Role: ${this.roleDescription}
      You are an autonomous enterprise AI agent in PariLink.

      Available Tools (Phase 5):
      ${toolDescriptions || 'No tools available for this agent.'}

      If you need to use a tool, format your response as:
      [TOOL_CALL: tool_name, {"arg": "value"}]
    `;

    const initialResponse = await this.llmManager.generateResponse(
      systemPrompt,
      message,
      context,
    );

    // Naive Tool Execution loop for MVP (Phase 6 Automation)
    if (initialResponse.includes('[TOOL_CALL:')) {
      const match = initialResponse.match(/\[TOOL_CALL:\s*([^,]+),\s*(.+?)\]/);
      if (match) {
        const toolName = match[1].trim();
        const toolInput = match[2].trim();
        this.logger.log(`[${this.agentName}] Executing Tool: ${toolName}`);

        const tool = this.tools.find((t) => t.name === toolName);
        if (tool) {
          try {
            const result = await (tool as any).invoke(JSON.parse(toolInput));
            // Send result back to LLM for final answer
            return this.llmManager.generateResponse(
              systemPrompt,
              `Tool ${toolName} returned: ${result}\nProvide final answer.`,
            );
          } catch (e) {
            const errorMessage = e instanceof Error ? e.message : String(e);
            this.logger.error(`Tool execution failed: ${errorMessage}`);
          }
        }
      }
    }

    return initialResponse;
  }
}

import { Injectable } from '@nestjs/common';
import { BaseAgent } from '../base.agent';
import { PrismaService } from '../../../prisma/prisma.service';
import { LlmManagerService } from '../../platform/llm-manager.service';
import { DynamicTool } from '@langchain/core/tools';

@Injectable()
export class IntegrationAgent extends BaseAgent {
  readonly agentName = 'IntegrationAgent';
  readonly roleDescription =
    'Diagnoses integration errors, checks sync status, and manages 3rd party connections.';

  readonly tools = [
    new DynamicTool({
      name: 'get_recent_sync_errors',
      description:
        'Fetch the most recent synchronization errors. Input should be {"limit": number}',
      func: async (input: string) => {
        const args = JSON.parse(input);
        const errors = await this.prisma.runAsSystem(async (tx) =>
          tx.syncError.findMany({
            orderBy: { createdAt: 'desc' },
            take: args.limit || 5,
            include: { connection: { include: { connector: true } } },
          }),
        );
        return JSON.stringify(
          errors.map((e: any) => ({
            id: e.id,
            provider: e.connection.connector.provider,
            errorMessage: e.errorMessage,
            date: e.createdAt,
          })),
        );
      },
    }),
    new DynamicTool({
      name: 'retry_failed_sync',
      description:
        'Queue a manual retry for a specific failed connection. Input should be {"connectionId": "string"}',
      func: async (input: string) => {
        const args = JSON.parse(input);
        return `Retry queued for connection ${args.connectionId}`;
      },
    }),
  ];

  constructor(
    llmManager: LlmManagerService,
    private prisma: PrismaService,
  ) {
    super(llmManager);
  }
}

