@Injectable()
export class LlmManagerService {
  private readonly logger = new Logger(LlmManagerService.name);

  constructor(
    private readonly modelRouter: ModelRouterService,
    private readonly observabilityService: AiObservabilityService,
    private readonly governance: AiGovernanceService,
  ) {}

  /**
   * Standard text generation — awaits full response
   */
  async generateResponse(
    systemPrompt: string,
    userQuery: string,
    context: any = {},
    preferredProvider?: string,
    templateKey?: string,
  ): Promise<string> {
    const startTime = Date.now();
    const resolvedSystem = templateKey
      ? (PROMPT_TEMPLATES[templateKey] || PROMPT_TEMPLATES.default) +
        '\n\n' +
        systemPrompt
      : systemPrompt;

    // Security: Sanitize input for Prompt Injection
    const sanitizedQuery = this.governance.sanitizeInput(userQuery);

    try {
      const model = await this.modelRouter.getBestModel(preferredProvider);
      const entry = this.modelRouter.getModelEntry(preferredProvider);

      const messages: BaseMessage[] = [
        new SystemMessage(
          resolvedSystem +
            (Object.keys(context).length
              ? `\n\nContext:\n${JSON.stringify(context, null, 2)}`
              : ''),
        ),
        new HumanMessage(sanitizedQuery),
      ];

      const response = await model.invoke(messages);
      const duration = Date.now() - startTime;

      const responseText =
        typeof response.content === 'string'
          ? response.content
          : JSON.stringify(response.content);

      // Security: Validate output
      const validation = this.governance.validateOutput(responseText);
      if (!validation.valid) {
        this.logger.warn('LLM generated output violating policies.');
      }

      // Estimate cost from token approximation (chars / 4 ≈ tokens)
      const approxInputTokens = Math.ceil(
        messages
          .map((m) =>
            typeof m.content === 'string'
              ? m.content.length
              : JSON.stringify(m.content).length,
          )
          .reduce((a, b) => a + b, 0) / 4,
      );
      const approxOutputTokens = Math.ceil(responseText.length / 4);
      const inputCost = entry
        ? (approxInputTokens / 1000) * entry.costPerInputToken
        : 0;
      const outputCost = entry
        ? (approxOutputTokens / 1000) * entry.costPerOutputToken
        : 0;

      await this.observabilityService.logMetrics({
        modelProvider: entry?.provider || 'Fallback',
        latencyMs: duration,
        promptTokens: approxInputTokens,
        completionTokens: approxOutputTokens,
        cost: inputCost + outputCost,
        success: true,
      });

      return validation.valid
        ? responseText
        : 'Output blocked by Security Policy.';
    } catch (error: any) {
      const duration = Date.now() - startTime;
      await this.observabilityService.logMetrics({
        modelProvider: preferredProvider || 'Fallback',
        latencyMs: duration,
        promptTokens: 0,
        completionTokens: 0,
        cost: 0,
        success: false,
      });
      this.logger.error(`LLM Generation Failed: ${error.message}`);
      throw error;
    }
  }

  /**
   * Streaming generation — yields text chunks as they arrive
   */
  async *generateStreamResponse(
    systemPrompt: string,
    userQuery: string,
    context: any = {},
    preferredProvider?: string,
  ): AsyncIterable<string> {
    const model = await this.modelRouter.getBestModel(preferredProvider);

    const messages: BaseMessage[] = [
      new SystemMessage(
        systemPrompt +
          (Object.keys(context).length
            ? `\n\nContext:\n${JSON.stringify(context, null, 2)}`
            : ''),
      ),
      new HumanMessage(userQuery),
    ];

    const stream = await model.stream(messages);

    for await (const chunk of stream) {
      const text =
        typeof chunk.content === 'string'
          ? chunk.content
          : JSON.stringify(chunk.content);
      if (text) yield text;
    }
  }

  /**
   * Returns all registered prompt templates
   */
  getPromptTemplates(): Record<string, string> {
    return { ...PROMPT_TEMPLATES };
  }

  /**
   * Returns the model registry summary
   */
  getModelRegistry() {
    return this.modelRouter.getModelRegistry();
  }

  /**
   * Retrieves the raw BaseChatModel instance (for Agent Executors)
   */
  async getModel(preferredProvider?: string) {
    return this.modelRouter.getBestModel(preferredProvider);
  }
}

// @ts-nocheck
import {
  ServiceUnavailableException,
  Injectable,
  Logger,
  OnModuleInit,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { ChatOpenAI, AzureChatOpenAI } from '@langchain/openai';
import { ChatAnthropic } from '@langchain/anthropic';
import {
  BaseChatModel,
  SimpleChatModel,
} from '@langchain/core/language_models/chat_models';
import { BaseMessage } from '@langchain/core/messages';

class MockChatModel extends SimpleChatModel {
  constructor() {
    super({});
  }

  _llmType() {
    return 'mock-chat-model';
  }

  async _call(messages: BaseMessage[]): Promise<string> {
    const text = messages
      .map((m) =>
        typeof m.content === 'string' ? m.content : JSON.stringify(m.content),
      )
      .join(' ');
    if (text.includes('ping')) return 'pong';
    return `[Mock AI Response] Simulated response for testing without API keys. You said: "${text.substring(0, 50)}..."`;
  }
}

// Provider enum matching Prisma schema
export type AiProvider =
  | 'OPENAI'
  | 'ANTHROPIC'
  | 'GEMINI'
  | 'OLLAMA'
  | 'AZURE_OPENAI'
  | 'BEDROCK'
  | 'MOCK';

interface ModelEntry {
  model: BaseChatModel;
  provider: AiProvider;
  modelName: string;
  priority: number;
  costPerInputToken: number;
  costPerOutputToken: number;
}

@Injectable()
export class ModelRouterService implements OnModuleInit {
  private readonly logger = new Logger(ModelRouterService.name);

  // Ordered by priority (highest first)
  private activeModels: ModelEntry[] = [];

  // Pricing table (USD per 1K tokens) — updated manually or via config
  private static readonly PRICING: Record<
    string,
    { input: number; output: number }
  > = {
    'gpt-4o': { input: 0.005, output: 0.015 },
    'gpt-4o-mini': { input: 0.00015, output: 0.0006 },
    'gpt-3.5-turbo': { input: 0.0005, output: 0.0015 },
    'claude-3-5-sonnet-20241022': { input: 0.003, output: 0.015 },
    'claude-3-haiku-20240307': { input: 0.00025, output: 0.00125 },
    'gemini-1.5-pro': { input: 0.00125, output: 0.005 },
    'gemini-1.5-flash': { input: 0.000075, output: 0.0003 },
    default: { input: 0.001, output: 0.002 },
  };

  constructor(private prisma: PrismaService) {}

  async onModuleInit() {
    await this.refreshModels();
  }

  async refreshModels() {
    this.activeModels = [];

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let configs: any[] = [];
    try {
      configs = await this.prisma.runAsSystem(async (tx) =>
        tx.aiModelConfig.findMany({
          where: { isActive: true },
          orderBy: { priority: 'desc' },
        }),
      );
    } catch {
      this.logger.warn(
        'Could not load AI model configs from DB — using fallback mock model.',
      );
    }

    for (const config of configs) {
      try {
        const details = config.config || {};
        let model: BaseChatModel | null = null;

        switch (config.provider as AiProvider) {
          case 'OPENAI':
            model = new ChatOpenAI({
              modelName: config.modelName,
              apiKey: details.apiKey || process.env.OPENAI_API_KEY,
              temperature: details.temperature ?? 0,
              maxTokens: details.maxTokens,
              streaming: false,
            });
            break;

          case 'ANTHROPIC':
            model = new ChatAnthropic({
              modelName: config.modelName,
              apiKey: details.apiKey || process.env.ANTHROPIC_API_KEY,
              temperature: details.temperature ?? 0,
              maxTokens: details.maxTokens,
            });
            break;

          case 'GEMINI':
            // Dynamic import to avoid crashing if package not installed
            try {
              const { ChatGoogleGenerativeAI } =
                await import('@langchain/google-genai');
              model = new ChatGoogleGenerativeAI({
                model: config.modelName,
                apiKey: details.apiKey || process.env.GOOGLE_AI_API_KEY,
                temperature: details.temperature ?? 0,
                maxOutputTokens: details.maxTokens,
              });
            } catch {
              this.logger.warn(
                'Gemini provider: @langchain/google-genai not installed. Skipping.',
              );
            }
            break;

          case 'OLLAMA':
            try {
              // @ts-expect-error - Dynamic import for optional provider
              const { ChatOllama } = await import('@langchain/ollama');
              model = new ChatOllama({
                model: config.modelName,
                baseUrl:
                  details.baseUrl ||
                  process.env.OLLAMA_BASE_URL ||
                  'http://localhost:11434',
                temperature: details.temperature ?? 0,
              });
            } catch {
              this.logger.warn(
                'Ollama provider: @langchain/ollama not installed. Skipping.',
              );
            }
            break;

          case 'AZURE_OPENAI':
            model = new AzureChatOpenAI({
              azureOpenAIApiKey:
                details.apiKey || process.env.AZURE_OPENAI_API_KEY,
              azureOpenAIApiInstanceName:
                details.instanceName ||
                process.env.AZURE_OPENAI_INSTANCE_NAME ||
                'parilink',
              azureOpenAIApiDeploymentName:
                details.deploymentName || config.modelName,
              azureOpenAIApiVersion: details.apiVersion || '2024-02-01',
              temperature: details.temperature ?? 0,
              maxTokens: details.maxTokens,
            });
            break;

          default:
            this.logger.warn(`Unknown provider: ${config.provider}. Skipping.`);
        }

        if (model) {
          const pricing =
            ModelRouterService.PRICING[config.modelName] ||
            ModelRouterService.PRICING.default;
          this.activeModels.push({
            model,
            provider: config.provider as AiProvider,
            modelName: config.modelName,
            priority: config.priority,
            costPerInputToken: pricing.input,
            costPerOutputToken: pricing.output,
          });
          this.logger.log(
            `Registered model: ${config.provider}/${config.modelName} (priority=${config.priority})`,
          );
        }
      } catch (error: unknown) {
        this.logger.error(
          `Failed to initialize model ${config.provider}: ${(error as Error).message}`,
        );
      }
    }

    if (this.activeModels.length === 0) {
      this.logger.warn(
        'No active AI models found in DB or environment. Injecting Mock Chat Model fallback.',
      );
      this.activeModels.push({
        model: new MockChatModel(),
        provider: 'MOCK',
        modelName: 'mock-chat-model',
        priority: -1,
        costPerInputToken: 0,
        costPerOutputToken: 0,
      });
    }

    this.logger.log(`Active AI models: ${this.activeModels.length}`);
  }

  /**
   * Returns the highest-priority healthy model, with automatic failover.
   * If preferredProvider is given, tries that first before falling back.
   */
  async getBestModel(preferredProvider?: string): Promise<BaseChatModel> {
    if (this.activeModels.length === 0) {
      this.logger.error(
        'No active AI models configured or credentials missing',
      );
      throw new ServiceUnavailableException(
        'AI platform is not configured. Please add an AI provider API key.',
      );
    }

    if (preferredProvider) {
      const preferred = this.activeModels.find(
        (m) => m.provider === preferredProvider,
      );
      if (preferred) return preferred.model;
    }

    // Primary model with failover cascade
    for (const entry of this.activeModels) {
      const healthy = await this.isModelHealthy(entry);
      if (healthy) return entry.model;
      this.logger.warn(
        `Model ${entry.provider}/${entry.modelName} failed health check — trying next`,
      );
    }

    // All models unhealthy — return first anyway (last resort)
    return this.activeModels[0].model;
  }

  /**
   * Get pricing info for a given model entry (used by LlmManager for cost estimation)
   */
  getModelEntry(preferredProvider?: string): ModelEntry | null {
    if (this.activeModels.length === 0) return null;
    if (preferredProvider) {
      return (
        this.activeModels.find((m) => m.provider === preferredProvider) || null
      );
    }
    return this.activeModels[0];
  }

  /**
   * Health check: invoke with a tiny prompt to verify the model is responsive.
   * Returns true if healthy, false on error or timeout.
   */
  private async isModelHealthy(entry: ModelEntry): Promise<boolean> {
    try {
      const { HumanMessage } = await import('@langchain/core/messages');
      const timeoutPromise = new Promise<null>((_, reject) =>
        setTimeout(() => reject(new Error('Health check timeout')), 3000),
      );
      const pingPromise = entry.model.invoke([new HumanMessage('ping')]);
      await Promise.race([pingPromise, timeoutPromise]);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Returns a summary of all registered models and their status
   */
  getModelRegistry() {
    return this.activeModels.map((m) => ({
      provider: m.provider,
      modelName: m.modelName,
      priority: m.priority,
      costPerInputTokenUsd: m.costPerInputToken,
      costPerOutputTokenUsd: m.costPerOutputToken,
    }));
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { MockAIProvider } from '../providers/mock-ai.provider';

@Injectable()
export class PredictionEngineService {
  private readonly logger = new Logger(PredictionEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly aiProvider: MockAIProvider,
  ) {}

  /**
   * Generates a prediction (e.g. ETA) and tracks its accuracy over time
   */
  async generatePrediction(
    companyId: string,
    targetEntity: string,
    entityId: string,
    features: any,
  ) {
    this.logger.log(`Generating Prediction for ${targetEntity}`);

    const context = JSON.stringify(features);
    const schema = {
      properties: {
        predictedValue: { type: 'object' },
        confidence: { type: 'number' },
        factors: { type: 'array', items: { type: 'string' } },
      },
    };

    const output = await this.aiProvider.structuredGenerate<any>(
      'Predict future state',
      context,
      schema,
    );

    const prediction = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.aiPrediction.create({
        data: {
          companyId,
          targetEntity,
          entityId,
          predictedValue: output.predictedValue,
          confidence: output.confidence,
          factors: output.factors,
        },
      }),
    );

    return prediction;
  }
}

import {
  InternalServerErrorException,
  Injectable,
  Logger,
} from '@nestjs/common';
import { LlmManagerService } from '../platform/llm-manager.service';

export interface IAIProvider {
  chat(prompt: string, context: string): Promise<string>;
  structuredGenerate<T>(
    prompt: string,
    context: string,
    schema: any,
  ): Promise<T>;
}

/**
 * Mock Provider for V1 to ensure we don't block on real LLM credentials.
 * It simulates an AI analyzing the context and returning structured JSON.
 */
@Injectable()
export class MockAIProvider implements IAIProvider {
  private readonly logger = new Logger(MockAIProvider.name);

  constructor(private readonly llmManager: LlmManagerService) {}

  async chat(prompt: string, context: string): Promise<string> {
    this.logger.debug(`Calling AI Chat Generation...`);
    return this.llmManager.generateResponse(
      'You are an AI assistant.',
      prompt,
      { context },
    );
  }

  async structuredGenerate<T>(
    prompt: string,
    context: string,
    schema: any,
  ): Promise<T> {
    this.logger.debug(`Calling Structured AI Generation...`);

    const schemaStr = JSON.stringify(schema);
    const systemPrompt = `You must return ONLY a raw JSON object (no markdown, no backticks) that matches this schema: ${schemaStr}`;

    const responseText = await this.llmManager.generateResponse(
      systemPrompt,
      prompt,
      { context },
    );

    try {
      // Strip markdown code block if the LLM adds it
      const cleanedText = responseText
        .replace(/^```json\\n/, '')
        .replace(/\\n```$/, '');
      const parsed = JSON.parse(cleanedText);
      return parsed as T;
    } catch (e) {
      this.logger.error(
        `Failed to parse structured AI output: ${e.message}`,
        responseText,
      );
      throw new InternalServerErrorException(
        'AI returned malformed structured data',
      );
    }
  }
}

import {
  ServiceUnavailableException,
  Injectable,
  Logger,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { OpenAIEmbeddings } from '@langchain/openai';

@Injectable()
export class EmbeddingPipelineService {
  private readonly logger = new Logger(EmbeddingPipelineService.name);
  private embeddings = new OpenAIEmbeddings({
    apiKey: process.env.OPENAI_API_KEY,
    modelName: 'text-embedding-3-small',
  });

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Mocks embedding generation if no API key is provided,
   * otherwise uses OpenAI Embeddings.
   */
  private async getEmbedding(text: string): Promise<number[]> {
    if (!process.env.OPENAI_API_KEY) {
      throw new ServiceUnavailableException(
        'OpenAI API Key is required for generating embeddings.',
      );
    }
    return this.embeddings.embedQuery(text);
  }

  async indexDocument(
    title: string,
    content: string,
    sourceType: string,
    metadata: any = {},
  ) {
    this.logger.log(`Indexing document: ${title}`);

    // 1. Create Document Record
    const doc = await this.prisma.runAsSystem(async (tx) =>
      tx.knowledgeDocument.create({
        data: { title, content, sourceType, metadata },
      }),
    );

    // 2. Chunking (Naive text splitter for MVP)
    const chunkSize = 1000;
    const chunks = [];
    for (let i = 0; i < content.length; i += chunkSize) {
      chunks.push(content.substring(i, i + chunkSize));
    }

    // 3. Generate Embeddings & Store Chunks
    for (const chunkText of chunks) {
      const vector = await this.getEmbedding(chunkText);
      await this.prisma.runAsSystem(async (tx) =>
        tx.knowledgeChunk.create({
          data: {
            documentId: doc.id,
            content: chunkText,
            embedding: vector,
            metadata: {},
          },
        }),
      );
    }

    this.logger.log(`Indexed ${chunks.length} chunks for document: ${title}`);
    return doc;
  }
}

import {
  ServiceUnavailableException,
  Injectable,
  Logger,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { OpenAIEmbeddings } from '@langchain/openai';

export interface RagCitation {
  documentId: string;
  documentTitle: string;
  chunkIndex: number;
  relevanceScore: number;
  snippet: string;
}

export interface RagResult {
  context: string;
  citations: RagCitation[];
}

@Injectable()
export class EnterpriseRagService {
  private readonly logger = new Logger(EnterpriseRagService.name);

  private embeddings = new OpenAIEmbeddings({
    apiKey: process.env.OPENAI_API_KEY,
    modelName: 'text-embedding-3-small',
  });

  constructor(private readonly prisma: PrismaService) {}

  private async getEmbedding(text: string): Promise<number[]> {
    if (!process.env.OPENAI_API_KEY) {
      throw new ServiceUnavailableException(
        'OpenAI API Key is required for RAG context retrieval.',
      );
    }
    return this.embeddings.embedQuery(text);
  }

  private cosineSimilarity(a: number[], b: number[]): number {
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }
    if (normA === 0 || normB === 0) return 0;
    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  /**
   * BM25-style keyword scoring (simple term frequency approach)
   */
  private keywordScore(query: string, text: string): number {
    const queryTerms = query.toLowerCase().split(/\s+/).filter(Boolean);
    const textLower = text.toLowerCase();
    let score = 0;
    for (const term of queryTerms) {
      const occurrences = (textLower.match(new RegExp(term, 'g')) || []).length;
      // Normalized TF
      score += occurrences / (occurrences + 1.5);
    }
    return score / Math.max(queryTerms.length, 1);
  }

  /**
   * Tenant-isolated, permission-aware hybrid search (semantic + keyword).
   * Returns context string + citations for the calling agent/copilot.
   */
  async retrieveContext(
    query: string,
    options: {
      companyId?: string;
      limit?: number;
      permissionTags?: string[];
      semanticWeight?: number; // 0–1, defaults to 0.7
    } = {},
  ): Promise<RagResult> {
    const {
      companyId,
      limit = 5,
      permissionTags = [],
      semanticWeight = 0.7,
    } = options;

    this.logger.log(
      `RAG retrieval — query: "${query.substring(0, 80)}", company: ${companyId || 'global'}`,
    );

    const queryVector = await this.getEmbedding(query);

    // Tenant-isolated fetch
    const whereClause: any = {};
    if (companyId) {
      whereClause.document = { companyId };
    }
    if (permissionTags.length > 0) {
      // Only return chunks whose document does NOT have restricted tags
      // that the caller doesn't possess
      whereClause.document = {
        ...whereClause.document,
        // permissionTag must be in caller's permissionTags OR be null/empty
        OR: [
          { permissionTag: null },
          { permissionTag: '' },
          { permissionTag: { in: permissionTags } },
        ],
      };
    }

    let chunks: any[] = [];
    try {
      chunks = await this.prisma.runAsSystem(async (tx) =>
        tx.knowledgeChunk.findMany({
          where: whereClause,
          include: { document: true },
          take: 200, // Fetch candidates, rank in memory
        }),
      );
    } catch {
      this.logger.warn(
        'KnowledgeChunk table not available — returning empty context',
      );
      return {
        context: '[System: No knowledge base configured yet.]',
        citations: [],
      };
    }

    if (chunks.length === 0) {
      return {
        context: `[System: No documents found in the knowledge base${companyId ? ' for this organization' : ''}.]`,
        citations: [],
      };
    }

    // Hybrid scoring: weighted combination of semantic + keyword scores
    const keywordWeight = 1 - semanticWeight;
    const scoredChunks = chunks
      .map((chunk) => {
        const semantic = this.cosineSimilarity(
          queryVector,
          chunk.embedding as number[],
        );
        const keyword = this.keywordScore(query, chunk.content);
        const hybridScore = semantic * semanticWeight + keyword * keywordWeight;
        return { chunk, score: hybridScore };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    const citations: RagCitation[] = scoredChunks.map(
      ({ chunk, score }, idx) => ({
        documentId: chunk.documentId,
        documentTitle: chunk.document?.title || 'Unknown Document',
        chunkIndex: chunk.chunkIndex ?? idx,
        relevanceScore: Math.round(score * 1000) / 1000,
        snippet:
          chunk.content.substring(0, 150) +
          (chunk.content.length > 150 ? '...' : ''),
      }),
    );

    const contextParts = scoredChunks.map(
      ({ chunk, score }) =>
        `[Source: "${chunk.document?.title || 'Unknown'}" | Relevance: ${(score * 100).toFixed(1)}%]\n${chunk.content}`,
    );

    return {
      context: contextParts.join('\n\n---\n\n'),
      citations,
    };
  }

  /**
   * Legacy compatibility shim — returns just the context string
   */
  async retrieveContextLegacy(query: string, limit = 3): Promise<string> {
    const result = await this.retrieveContext(query, { limit });
    return result.context;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { ContextEngineService } from '../context/context-engine.service';
import { MockAIProvider } from '../providers/mock-ai.provider';

@Injectable()
export class RecommendationEngineService {
  private readonly logger = new Logger(RecommendationEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly contextEngine: ContextEngineService,
    private readonly aiProvider: MockAIProvider, // Abstract in Prod
  ) {}

  /**
   * Evaluates context and generates an explainable recommendation.
   * AI recommends. Humans decide.
   */
  async generateRecommendation(
    companyId: string,
    domainEntity: string,
    entityId: string,
    promptGoal: string,
  ) {
    this.logger.log(
      `Generating Recommendation for ${domainEntity} [${entityId}]`,
    );

    // 1. Build immutable context
    const context = await this.contextEngine.buildAiContext(
      companyId,
      domainEntity,
      entityId,
    );

    // 2. Generate structured recommendation
    const schema = {
      properties: {
        recommendation: { type: 'string' },
        reasoning: { type: 'string' },
        confidence: { type: 'number' },
        evidence: { type: 'array', items: { type: 'string' } },
        alternatives: { type: 'array', items: { type: 'string' } },
      },
    };

    const output = await this.aiProvider.structuredGenerate<any>(
      promptGoal,
      context,
      schema,
    );

    // 3. Save to Governance layer for review
    const recommendation = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.aiRecommendation.create({
          data: {
            companyId,
            domainEntity,
            entityId,
            recommendation: output.recommendation,
            reasoning: output.reasoning,
            confidence: output.confidence,
            evidence: output.evidence,
            alternatives: output.alternatives,
            status: 'PENDING',
          },
        }),
    );

    // 4. Log Observability Metrics
    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.aiMetricsLog.create({
        data: {
          companyId,
          interactionId: recommendation.id,
          modelProvider: 'MockAI',
          modelVersion: '1.0',
          latencyMs: 150,
          promptTokens: context.length / 4, // estimate
          completionTokens: 50,
        },
      }),
    );

    return recommendation;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MockAIProvider } from './providers/mock-ai.provider';

@Injectable()
export class WorkflowGeneratorService {
  private readonly logger = new Logger(WorkflowGeneratorService.name);

  constructor(private readonly gemini: MockAIProvider) {}

  async generateWorkflowGraph(prompt: string) {
    this.logger.log(`Generating AI Workflow for prompt: ${prompt}`);

    const systemInstruction = `
      You are an Enterprise Workflow Automation expert.
      Generate a JSON Directed Acyclic Graph (DAG) for a workflow based on the user's prompt.
      The output must be EXACTLY a valid JSON object with 'nodes' and 'edges' arrays.
      Nodes must have id, type ('TRIGGER', 'CONDITION', 'ACTION', 'DELAY'), position {x,y}, and data object.
      Edges must have id, source, target.
      Only return JSON, nothing else.
    `;

    try {
      const response = await this.gemini.chat(prompt, systemInstruction);

      // Extract JSON from markdown if needed
      const jsonStr = response
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      return JSON.parse(jsonStr);
    } catch (e: any) {
      this.logger.error(`AI Workflow generation failed: ${e.message}`);
      // Fallback to a basic graph if AI fails
      return {
        nodes: [
          {
            id: '1',
            type: 'TRIGGER',
            position: { x: 250, y: 50 },
            data: { label: 'Generated Trigger' },
          },
          {
            id: '2',
            type: 'ACTION',
            position: { x: 250, y: 150 },
