import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class ApiAnalyticsInterceptor implements NestInterceptor {
  constructor(private readonly prisma: PrismaService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const ctx = context.switchToHttp();
    const req = ctx.getRequest();
    const res = ctx.getResponse();

    const start = Date.now();

    return next.handle().pipe(
      tap(() => {
        this.logApiCall(req, res, Date.now() - start);
      }),
      catchError((error) => {
        this.logApiCall(req, res, Date.now() - start, error);
        throw error;
      }),
    );
  }

  private logApiCall(req: any, res: any, latencyMs: number, error?: any) {
    // Fire and forget, don't block request
    process.nextTick(async () => {
      try {
        const statusCode = error ? error.status || 500 : res.statusCode;
        const user = req.user;

        await this.prisma.runAsSystem(async (tx) =>
          tx.apiAnalyticsLog.create({
            data: {
              companyId: user?.companyId,
              appId: user?.appId, // For future OAuth integration
              apiKeyId: user?.apiKeyId, // For Api Key integration
              endpoint: req.originalUrl || req.url,
              method: req.method,
              statusCode,
              latencyMs,
              errorMessage: error?.message,
              userAgent: req.headers['user-agent'],
              ipAddress: req.ip || req.connection?.remoteAddress,
            },
          }),
        );
      } catch (err) {
        // Silently fail logging in case of DB issues so we don't crash the server
        console.error('Failed to log API analytics', err);
      }
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../../prisma/prisma.service';
import { OnEvent } from '@nestjs/event-emitter';
import * as crypto from 'crypto';
import { AuditService } from '../../platform/audit/audit.service';

const SUPPORTED_EVENTS = [
  'load.created',
  'load.updated',
  'load.completed',
  'trip.created',
  'trip.started',
  'trip.completed',
  'driver.created',
  'driver.updated',
  'invoice.created',
  'invoice.paid',
  'workflow.rule.passed',
  'workflow.rule.failed',
  'dispatch.created',
  'dispatch.updated',
];

@Injectable()
export class WebhookService {
  private readonly logger = new Logger(WebhookService.name);

  constructor(
    @InjectQueue('webhooks_v2') private readonly webhookQueue: Queue,
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  @OnEvent('**')
  async handleDomainEvent(event: string, payload: any) {
    if (!SUPPORTED_EVENTS.includes(event)) {
      return;
    }

    const companyId = payload?.companyId || payload?.data?.companyId;
    if (!companyId) {
      this.logger.warn(
        `Event ${event} missing companyId, cannot dispatch webhooks.`,
      );
      return;
    }

    this.logger.log(`Dispatching event ${event} for company ${companyId}`);

    const endpoints = await this.prisma.runAsSystem(async (tx) =>
      tx.webhookEndpoint.findMany({
        where: {
          companyId,
          isActive: true,
        },
      }),
    );

    const jobs = [];

    for (const endpoint of endpoints) {
      const subscribedEvents = endpoint.events as string[];
      if (subscribedEvents.includes('*') || subscribedEvents.includes(event)) {
        // Construct the Payload
        const webhookPayload = {
          eventId: crypto.randomUUID(),
          eventType: event,
          timestamp: new Date().toISOString(),
          companyId,
          data: payload,
        };

        jobs.push({
          name: 'deliver_webhook',
          data: {
            endpointId: endpoint.id,
            url: endpoint.url,
            secret: endpoint.secret,
            payload: webhookPayload,
            companyId,
          },
          opts: {
            attempts: endpoint.retryCount > 0 ? endpoint.retryCount : 5,
            backoff: { type: 'exponential', delay: 2000 },
          },
        });
      }
    }

    if (jobs.length > 0) {
      await this.webhookQueue.addBulk(jobs);
      this.logger.log(
        `Queued ${jobs.length} webhook deliveries for event ${event}`,
      );
    }
  }

  // --- CRUD Operations ---

  async createWebhook(
    companyId: string,
    userId: string,
    data: { url: string; events: string[] },
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const secret = `whsec_${crypto.randomBytes(24).toString('hex')}`;

      const endpoint = await tx.webhookEndpoint.create({
        data: {
          companyId,
          url: data.url,
          secret,
          events: data.events,
        },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'WebhookEndpoint',
        entityId: endpoint.id,
        action: 'CREATE',
        afterValue: endpoint,
      });

      return endpoint;
    });
  }

  async getWebhooks(companyId: string) {
    return this.prisma.runAsSystem(async (tx) =>
      tx.webhookEndpoint.findMany({
        where: { companyId },
      }),
    );
  }

  async deleteWebhook(companyId: string, userId: string, endpointId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const endpoint = await tx.webhookEndpoint.update({
        where: { id: endpointId },
        data: { isActive: false },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'WebhookEndpoint',
        entityId: endpoint.id,
        action: 'DELETE',
        afterValue: { isActive: false },
      });

      return endpoint;
    });
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { MfaService } from './mfa.service';
import { PrismaService } from '../prisma/prisma.service';
import { SecurityContextService } from '../platform/security/security.service';
import { AuditService } from '../platform/audit/audit.service';
import { authenticator } from 'otplib';

describe('MfaService', () => {
  let service: MfaService;
  let prismaService: PrismaService;
  let securityService: SecurityContextService;
  let auditService: AuditService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        MfaService,
        {
          provide: PrismaService,
          useValue: {
            runAsSystem: jest.fn().mockImplementation(async function (cb) {
              return await cb(this);
            }),
            runAsTenant: jest.fn().mockImplementation(async function (t, cb) {
              return await cb(this);
            }),
            user: {
              findUnique: jest.fn(),
              update: jest.fn(),
            },
            backupCode: {
              create: jest.fn(),
              findMany: jest.fn(),
              update: jest.fn(),
            },
          },
        },
        {
          provide: SecurityContextService,
          useValue: {
            encryptSecret: jest
              .fn()
              .mockImplementation((val) => `encrypted_${val}`),
            decryptSecret: jest
              .fn()
              .mockImplementation((val) => val.replace('encrypted_', '')),
          },
        },
        {
          provide: AuditService,
          useValue: {
            logEvent: jest.fn(),
          },
        },
      ],
    }).compile();

    service = module.get<MfaService>(MfaService);
    prismaService = module.get<PrismaService>(PrismaService);
    securityService = module.get<SecurityContextService>(
      SecurityContextService,
    );
    auditService = module.get<AuditService>(AuditService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('generateTotpSecret', () => {
    it('should generate a secret and qr code', async () => {
      jest
        .spyOn(prismaService.user, 'findUnique')
        .mockResolvedValue({ id: 'user1', mfaEnabled: false } as any);
      const result = await service.generateTotpSecret('user1', 'test@test.com');

      expect(result).toHaveProperty('secret');
      expect(result).toHaveProperty('qrCodeDataUrl');
      // eslint-disable-next-line @typescript-eslint/unbound-method
      expect(prismaService.user.update).toHaveBeenCalled();
    });

    it('should throw if MFA is already enabled', async () => {
      jest
        .spyOn(prismaService.user, 'findUnique')
        .mockResolvedValue({ id: 'user1', mfaEnabled: true } as any);
      await expect(
        service.generateTotpSecret('user1', 'test@test.com'),
      ).rejects.toThrow('MFA is already enabled');
    });
  });

  describe('verifyTotp', () => {
    it('should return true for valid token', async () => {
      const secret = authenticator.generateSecret();
      jest.spyOn(prismaService.user, 'findUnique').mockResolvedValue({
        id: 'user1',
        totpSecret: `encrypted_${secret}`,
      } as any);

      const token = authenticator.generate(secret);
      const result = await service.verifyTotp('user1', token);
      expect(result).toBe(true);
    });

    it('should throw for invalid token', async () => {
      const secret = authenticator.generateSecret();
      jest.spyOn(prismaService.user, 'findUnique').mockResolvedValue({
        id: 'user1',
        totpSecret: `encrypted_${secret}`,
      } as any);

      await expect(service.verifyTotp('user1', '000000')).rejects.toThrow(
        'Invalid TOTP token',
      );
    });
  });
});

