import { Injectable, BadRequestException } from '@nestjs/common';
import { Issuer, Client, TokenSet } from 'openid-client';
import type { Request } from 'express';

@Injectable()
export class OidcService {
  async getClient(idp: any): Promise<Client> {
    if (!idp.issuer || !idp.clientId || !idp.clientSecret) {
      throw new BadRequestException('OIDC configuration incomplete');
    }

    const issuer = await Issuer.discover(idp.issuer).catch(() => {
      // Fallback if discovery fails but endpoints are provided manually
      return new Issuer({
        issuer: idp.issuer,
        authorization_endpoint: idp.authorizationEndpoint,
        token_endpoint: idp.tokenEndpoint,
        userinfo_endpoint: idp.userinfoEndpoint,
        jwks_uri: idp.jwksUri,
      });
    });

    return new issuer.Client({
      client_id: idp.clientId,
      client_secret: idp.clientSecret,
      redirect_uris: [
        `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/oidc/${idp.id}`,
      ],
      response_types: ['code'],
    });
  }

  async generateLoginUrl(idp: any, req: Request): Promise<string> {
    const client = await this.getClient(idp);

    const url = client.authorizationUrl({
      scope: 'openid email profile',
      state: (req.query.state as string) || undefined,
      nonce: 'static-nonce', // In production, generate securely and store in session
    });

    return url;
  }

  async validateCallback(idp: any, input: any, req: Request) {
    const client = await this.getClient(idp);
    const params = client.callbackParams(req);

    // In production, validate state and nonce against stored session values
    const tokenSet: TokenSet = await client.callback(
      `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/oidc/${idp.id}`,
      params,
      { nonce: 'static-nonce' }, // Use dynamic nonce stored in session
    );

    const claims = tokenSet.claims();

    return {
      id: claims.sub,
      email: claims.email,
      firstName: claims.given_name || claims.name?.split(' ')[0],
      lastName: claims.family_name || claims.name?.split(' ')[1],
      sessionId: claims.sid || tokenSet.session_state,
      groups: claims.groups || claims.roles, // Entra ID/Okta usually puts this in roles or groups claim
    };
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { SAML } from 'passport-saml/lib/node-saml';
import type { Request } from 'express';

@Injectable()
export class SamlService {
  getSamlStrategy(idp: any): SAML {
    if (!idp.entryPoint || !idp.cert) {
      throw new BadRequestException('SAML configuration incomplete');
    }

    return new SAML({
      callbackUrl: `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/saml/${idp.id}`,
      entryPoint: idp.entryPoint,
      issuer: process.env.APP_URL || 'http://localhost:3000',
      cert: idp.cert, // The IdP public certificate
      identifierFormat:
        idp.identifierFormat ||
        'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress',
      authnContext: idp.authnContext
        ? [idp.authnContext]
        : ['urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport'],
    });
  }

  async generateLoginUrl(idp: any, req: Request): Promise<string> {
    const saml = this.getSamlStrategy(idp);
    try {
      return await saml.getAuthorizeUrlAsync(
        (req.query.state as string) || '',
        undefined,
        {},
      );
    } catch (err: any) {
      throw err instanceof Error
        ? err
        : new Error(err?.message || 'Failed to generate SAML authorize URL');
    }
  }

  async validateResponse(idp: any, samlResponse: string, req: Request) {
    const saml = this.getSamlStrategy(idp);
    const proxyReq = {
      body: { SAMLResponse: samlResponse },
    };

    try {
      const { profile } = await saml.validatePostResponseAsync(proxyReq.body);
      if (!profile) {
        throw new Error('No profile in SAML response');
      }
      return {
        id: profile.nameID || profile.nameIDFormat,
        email: profile.email || profile.nameID,
        firstName: profile.firstName || profile.givenName,
        lastName: profile.lastName || profile.surname,
        sessionId: profile.sessionIndex,
        groups: profile.groups || profile.role,
      };
    } catch (err: any) {
      throw err instanceof Error
        ? err
        : new Error(err?.message || 'SAML Validation Failed');
    }
  }
}

import {
  Controller,
  Get,
  Post,
  Req,
  Res,
  Param,
  UseGuards,
  Query,
  Body,
} from '@nestjs/common';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { SsoService } from './sso.service';
import type { Request, Response } from 'express';

@ApiTags('auth/sso')
@Controller('auth/sso')
export class SsoController {
  constructor(private readonly ssoService: SsoService) {}

  @Get('login/:idpId')
  @ApiOperation({ summary: 'Initiate SSO Login' })
  async initiateLogin(
    @Param('idpId') idpId: string,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const redirectUrl = await this.ssoService.generateLoginUrl(idpId, req);
    return res.redirect(redirectUrl);
  }

  @Post('callback/saml/:idpId')
  @ApiOperation({ summary: 'SAML Callback URL' })
  async samlCallback(
    @Param('idpId') idpId: string,
    @Body() body: Record<string, unknown>,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleSamlCallback(idpId, body, req);
    return this.handleAuthResult(result, res);
  }

  @Get('callback/oidc/:idpId')
  @ApiOperation({ summary: 'OIDC Callback URL' })
  async oidcCallback(
    @Param('idpId') idpId: string,
    @Query() query: any,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleOidcCallback(idpId, query, req);
    return this.handleAuthResult(result, res);
  }

  @Post('callback/oidc/:idpId')
  @ApiOperation({ summary: 'OIDC Callback URL (POST)' })
  async oidcCallbackPost(
    @Param('idpId') idpId: string,
    @Body() body: Record<string, unknown>,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleOidcCallback(idpId, body, req);
    return this.handleAuthResult(result, res);
  }

  private handleAuthResult(result: any, res: Response) {
    if (result.error) {
      return res.redirect(`/login?error=${encodeURIComponent(result.error)}`);
    }

    if (result.requiresMfa) {
      // Need a way to pass the partial token to frontend. Usually URL params or cookie.
      res.cookie('mfa_token', result.mfaToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        maxAge: 15 * 60 * 1000,
      });
      return res.redirect(`/login/mfa?userId=${result.user.id}`);
    }

    // Set refresh token
    res.cookie('refresh_token', result.refresh_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Pass access token in URL fragment or a secure cookie. Standard is returning to a success page.
    return res.redirect(`/sso-success?token=${result.access_token}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

/**
 * Interface representing a Digital Worker capable of executing a graph node.
 */
export interface IDigitalWorker {
  name: string; // e.g. 'Dispatcher_AI', 'Finance_AI'
  executeTask(taskId: string, inputs: any): Promise<any>;
  rollbackTask(taskId: string, context: any): Promise<void>;
}

@Injectable()
export class DigitalWorkerRegistry {
  private readonly logger = new Logger(DigitalWorkerRegistry.name);
  private workers: Map<string, IDigitalWorker> = new Map();

  registerWorker(worker: IDigitalWorker) {
    if (this.workers.has(worker.name)) {
      this.logger.warn(`Worker ${worker.name} is already registered.`);
      return;
    }
    this.workers.set(worker.name, worker);
    this.logger.log(`Registered Digital Worker: ${worker.name}`);
  }

  getWorker(name: string): IDigitalWorker {
    const worker = this.workers.get(name);
    if (!worker) {
      throw new Error(`Digital Worker '${name}' not found in registry.`);
    }
    return worker;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { DigitalWorkerRegistry } from './digital-worker.registry';
import { EventService } from '../../platform/events/event.service';

@Injectable()
export class ExecutionService {
  private readonly logger = new Logger(ExecutionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly registry: DigitalWorkerRegistry,
    private readonly eventService: EventService,
  ) {}

  /**
   * Initializes the execution of a Graph-based Workflow (AI Decision converted to Action)
   */
  async startExecution(executionId: string) {
    this.logger.log(`Starting WorkflowExecution: ${executionId}`);

    // In a real DAG, we would identify root nodes and execute them.
    // For MVP, we fetch PENDING steps and execute them sequentially or in parallel based on graph dependencies.
    const steps = await this.prisma.runAsSystem(async (tx) =>
      tx.workflowExecutionStep.findMany({
        where: { executionId, status: 'PENDING' },
        orderBy: { executedAt: 'asc' }, // Simplified execution order
      }),
    );

    for (const step of steps) {
      await this.executeStep(step.id);
    }
  }

  /**
   * Executes a single step using the assigned Digital Worker
   */
  private async executeStep(stepId: string) {
    const step = await this.prisma.runAsSystem(async (tx) =>
      tx.workflowExecutionStep.findUnique({
        where: { id: stepId },
        include: { execution: true },
      }),
    );

    if (!step) return;

    this.logger.log(`Executing step ${step.nodeId} for worker ${step.owner}`);

    try {
      // Find the specific AI Worker responsible for this node
      const worker = this.registry.getWorker(step.owner || 'System_Default');

      const outputs = await worker.executeTask(step.nodeId, step.inputs);

      await this.prisma.runAsSystem(async (tx) =>
        tx.workflowExecutionStep.update({
          where: { id: stepId },
          data: { status: 'SUCCESS', outputs },
        }),
      );

      // Realtime Progress Tracking update
      this.eventService.publish('Execution.StepUpdated', {
        tenantId: step.execution.companyId,
        payload: { stepId, status: 'SUCCESS', executionId: step.executionId },
      });
    } catch (error) {
      this.logger.error(
        `Execution failed for step ${step.nodeId}: ${error.message}`,
      );
      await this.handleStepFailure(step, error.message);
    }
  }

  /**
   * Handles failure through Retry limits, then cascades to Rollback Compensation
   */
  private async handleStepFailure(step: any, errorMessage: string) {
    // 1. Retry Strategy
    const maxRetries = 3;
    if (step.retryCount < maxRetries) {
      this.logger.warn(
        `Retrying step ${step.nodeId} (Attempt ${step.retryCount + 1})`,
      );
      await this.prisma.runAsSystem(async (tx) =>
        tx.workflowExecutionStep.update({
          where: { id: step.id },
          data: { retryCount: step.retryCount + 1, error: errorMessage },
        }),
      );
      // Exponential Backoff in real implementation, here we re-execute immediately
      return this.executeStep(step.id);
    }

    // 2. Rollback Strategy (Compensation)
    this.logger.error(
      `Max retries reached for step ${step.nodeId}. Initiating Rollback.`,
    );
    await this.prisma.runAsSystem(async (tx) =>
      tx.workflowExecutionStep.update({
        where: { id: step.id },
        data: { status: 'FAILED', error: errorMessage },
      }),
    );

    if (step.rollbackAction) {
      try {
        const worker = this.registry.getWorker(step.owner || 'System_Default');
        await worker.rollbackTask(step.nodeId, step.inputs);
        this.logger.log(`Successfully rolled back step ${step.nodeId}`);
      } catch (rollbackError) {
        this.logger.error(
          `CRITICAL: Rollback failed for ${step.nodeId}: ${rollbackError.message}`,
        );
      }
    }

    // Fail the entire execution
    await this.prisma.runAsSystem(async (tx) =>
      tx.workflowExecution.update({
        where: { id: step.executionId },
        data: { status: 'FAILED', error: errorMessage },
      }),
    );

    this.eventService.publish('Execution.StepUpdated', {
      tenantId: step.execution.companyId,
      payload: {
        stepId: step.id,
        status: 'FAILED',
        executionId: step.executionId,
      },
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class BackgroundJobsService {
  private readonly logger = new Logger(BackgroundJobsService.name);

  constructor(private prisma: PrismaService) {}

  async createJob(
    companyId: string,
    userId: string,
    type: string,
    metadata: any = {},
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.create({
        data: {
          companyId,
          userId,
          type,
          status: 'PENDING',
          progress: 0,
          metadata,
        },
      }),
    );
  }

  async getJobs(companyId: string, userId: string, limit: number = 20) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.findMany({
        where: { companyId, userId },
        orderBy: { createdAt: 'desc' },
        take: limit,
      }),
    );
  }

  async getActiveJobs(companyId: string, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.findMany({
        where: {
          companyId,
          userId,
          status: { in: ['PENDING', 'PROCESSING'] },
        },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }

  async updateJobProgress(
    jobId: string,
    progress: number,
    status: string = 'PROCESSING',
  ) {
    return this.prisma.runAsSystem(async (tx) =>
      tx.backgroundJob.update({
        where: { id: jobId },
        data: {
          progress,
          status,
          ...(status === 'PROCESSING' && progress === 0
            ? { startedAt: new Date() }
            : {}),
        },
      }),
    );
  }

  async completeJob(jobId: string, result: any = {}) {
    return this.prisma.runAsSystem(async (tx) =>
      tx.backgroundJob.update({
        where: { id: jobId },
        data: {
          status: 'COMPLETED',
          progress: 100,
          completedAt: new Date(),
          result,
        },
      }),
    );
  }

  async failJob(jobId: string, error: string) {
    return this.prisma.runAsSystem(async (tx) =>
      tx.backgroundJob.update({
        where: { id: jobId },
        data: {
          status: 'FAILED',
          completedAt: new Date(),
          error,
        },
      }),
    );
  }

  async cancelJob(jobId: string) {
    return this.prisma.runAsSystem(async (tx) =>
      tx.backgroundJob.update({
        where: { id: jobId },
        data: {
          status: 'CANCELLED',
          completedAt: new Date(),
        },
      }),
    );
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { BillingService } from './billing.service';
import { PrismaService } from '../prisma/prisma.service';
import { WorkflowService } from '../workflow/workflow.service';
import { NotFoundException, BadRequestException } from '@nestjs/common';
import { AuditService } from '../platform/audit/audit.service';

describe('BillingService', () => {
  let service: BillingService;
  let prisma: jest.Mocked<PrismaService>;

  const mockTx = {
    load: { findFirst: jest.fn() },
    invoice: { findFirst: jest.fn(), create: jest.fn(), updateMany: jest.fn() },
    rateCard: { findFirst: jest.fn(), create: jest.fn(), findMany: jest.fn() },
    account: { upsert: jest.fn() },
    journalEntry: { create: jest.fn() },
  };

  const mockPrisma = {
    runAsSystem: jest.fn().mockImplementation(async (cb) => cb(mockPrisma)),
    runAsTenant: jest.fn((companyId: string, cb: (tx: any) => any) =>
      cb(mockTx),
    ),
  };

  beforeEach(async () => {
    jest.clearAllMocks();

    const mockWorkflowService = {
      evaluateRules: jest.fn().mockResolvedValue({ triggeredActions: [] }),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        BillingService,
        { provide: PrismaService, useValue: mockPrisma },
        { provide: WorkflowService, useValue: mockWorkflowService },
        { provide: EventEmitter2, useValue: { emit: jest.fn() } },
        { provide: AuditService, useValue: { logEvent: jest.fn() } },
      ],
    }).compile();
    service = module.get<BillingService>(BillingService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('generateInvoice', () => {
    it('should throw NotFoundException when load does not exist', async () => {
      mockTx.load.findFirst.mockResolvedValue(null);
      await expect(
        service.generateInvoice('company-1', { loadId: 'load-999' }),
      ).rejects.toThrow(NotFoundException);
    });

    it('should throw BadRequestException when load is not DELIVERED', async () => {
      mockTx.load.findFirst.mockResolvedValue({
        id: 'load-1',
        status: 'IN_TRANSIT',
        customerId: 'customer-1',
        customer: { name: 'Test Customer' },
        rate: 1000,
      });
      await expect(
        service.generateInvoice('company-1', { loadId: 'load-1' }),
      ).rejects.toThrow(BadRequestException);
    });

    it('should throw BadRequestException when invoice already exists', async () => {
      mockTx.load.findFirst.mockResolvedValue({
        id: 'load-1',
        status: 'DELIVERED',
        customerId: 'customer-1',
        customer: { name: 'Test Customer' },
        referenceNumber: 'REF-001',
        rate: 1000,
      });
      mockTx.invoice.findFirst.mockResolvedValue({ id: 'existing-invoice' });
      await expect(
        service.generateInvoice('company-1', { loadId: 'load-1' }),
      ).rejects.toThrow(BadRequestException);
    });

    it('should create invoice with load rate when no manual amount or rate card', async () => {
      const mockLoad = {
        id: 'load-1',
        status: 'DELIVERED',
        customerId: 'customer-1',
        customer: { name: 'Test Customer' },
        referenceNumber: 'REF-001',
        rate: 1500,
      };
      mockTx.load.findFirst.mockResolvedValue(mockLoad);
      mockTx.invoice.findFirst.mockResolvedValue(null);
      mockTx.invoice.create.mockResolvedValue({
        id: 'new-invoice',
        amount: 1500,
        lineItems: [],
      });

      const result = await service.generateInvoice('company-1', {
        loadId: 'load-1',
      });

      expect(result).toBeDefined();
      expect(mockTx.invoice.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({
            amount: 1500,
            status: 'DRAFT',
            companyId: 'company-1',
          }),
        }),
      );
    });

    it('should use manual amount when provided', async () => {
      const mockLoad = {
        id: 'load-1',
        status: 'DELIVERED',
        customerId: 'customer-1',
        customer: { name: 'Test Customer' },
        referenceNumber: 'REF-001',
        rate: 1500,
      };
      mockTx.load.findFirst.mockResolvedValue(mockLoad);
      mockTx.invoice.findFirst.mockResolvedValue(null);
      mockTx.invoice.create.mockResolvedValue({
        id: 'new-invoice',
        amount: 2500,
        lineItems: [],
      });

      await service.generateInvoice('company-1', {
        loadId: 'load-1',
        manualAmount: 2500,
      });

      expect(mockTx.invoice.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({ amount: 2500 }),
        }),
      );
    });
  });

  describe('approveInvoice', () => {
    it('should throw NotFoundException when invoice does not exist', async () => {
      mockTx.invoice.findFirst.mockResolvedValue(null);
      await expect(
        service.approveInvoice('company-1', 'invoice-999'),
      ).rejects.toThrow(NotFoundException);
    });

    it('should throw BadRequestException when invoice is not DRAFT', async () => {
      mockTx.invoice.findFirst.mockResolvedValue({
        id: 'invoice-1',
        status: 'SENT',
        companyId: 'company-1',
        customer: { name: 'Test' },
        amount: 1000,
        invoiceNumber: 'INV-001',
      });
      await expect(
        service.approveInvoice('company-1', 'invoice-1'),
      ).rejects.toThrow(BadRequestException);
    });

    it('should approve a DRAFT invoice and post a journal entry', async () => {
      const mockInvoice = {
        id: 'invoice-1',
        status: 'DRAFT',
        companyId: 'company-1',
        customer: { name: 'Test Customer' },
        amount: 1000,
        invoiceNumber: 'INV-001',
      };
      mockTx.invoice.findFirst.mockResolvedValue(mockInvoice);
      mockTx.invoice.updateMany.mockResolvedValue({ count: 1 });
      mockTx.account.upsert.mockResolvedValue({ id: 'account-1' });
      mockTx.journalEntry.create.mockResolvedValue({ id: 'je-1' });

      const result = await service.approveInvoice('company-1', 'invoice-1');

      expect(result.status).toBe('SENT');
      expect(mockTx.journalEntry.create).toHaveBeenCalledTimes(1);
      expect(mockTx.account.upsert).toHaveBeenCalledTimes(2);
    });
  });
});

import { Prisma } from '@prisma/client';
import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateRateCardDto } from './dto/create-rate-card.dto';
import { GenerateInvoiceDto } from './dto/generate-invoice.dto';
import * as crypto from 'crypto';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AuditService } from '../platform/audit/audit.service';

@Injectable()
export class BillingService {
  constructor(
    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
    private auditService: AuditService,
  ) {}

  async createRateCard(companyId: string, dto: CreateRateCardDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.rateCard.create({
        data: {
          companyId,
          ...dto,
        },
      });
    });
  }

  async getRateCards(companyId: string, customerId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { active: true };
      if (customerId) where.customerId = customerId;
      return tx.rateCard.findMany({ where, include: { customer: true } });
    });
  }

  async generateInvoice(companyId: string, dto: GenerateInvoiceDto) {
    const invoice = await this.prisma.runAsTenant(companyId, async (tx) => {
      const load = await tx.load.findFirst({
        where: { id: dto.loadId },
        include: { customer: true },
      });
      if (!load) throw new NotFoundException('Load not found');
      if (load.status !== 'DELIVERED')
        throw new BadRequestException(
          'Load must be DELIVERED before invoicing',
        );

      const existingInvoice = await tx.invoice.findFirst({
        where: { loadId: load.id, status: { not: 'VOIDED' } },
      });

      if (existingInvoice) {
        throw new BadRequestException(
          'An active invoice already exists for this load',
        );
      }

      let amount = dto.manualAmount || load.rate;
      let rateCard = null;

      if (dto.rateCardId) {
        rateCard = await tx.rateCard.findFirst({
          where: { id: dto.rateCardId },
        });
        if (rateCard) {
          if (rateCard.type === 'FLAT' || rateCard.type === 'ROUTE')
            amount = rateCard.rate;
          if (rateCard.type === 'DISTANCE')
            amount = rateCard.rate * (load.weight || 1);
          amount +=
            (rateCard.fuelSurcharge || 0) + (rateCard.tollSurcharge || 0);
        }
      }

      const invoiceNumber = `INV-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;

      const invoice = await tx.invoice.create({
        data: {
          companyId,
          customerId: load.customerId,
          loadId: load.id,
          invoiceNumber,
          amount,
          status: 'DRAFT',
          dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // Net 30 default
          lineItems: {
            create: [
              {
                description: `Freight for Load ${load.referenceNumber}`,
                quantity: 1,
                unitPrice: amount,
                amount: amount,
                type: 'LINE_HAUL',
              },
            ],
          },
        },
        include: { lineItems: true },
      });

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'INVOICE',
        trigger: 'INVOICE_GENERATED',
        entityData: invoice,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Invoice generation rejected by business rules.',
        );
      }

      return invoice;
    });

    this.eventEmitter.emit('invoice.created', invoice);

    await this.auditService.logEvent({
      action: 'INVOICE_GENERATED',
      entity: 'Invoice',
      entityId: invoice.id,
      companyId: companyId,
      source: 'BILLING_SERVICE',
      details: { amount: invoice.amount },
    });

    return invoice;
  }

  async approveInvoice(companyId: string, invoiceId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const invoice = await tx.invoice.findFirst({
        where: { id: invoiceId, companyId },
        include: { customer: true },
      });
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.status !== 'DRAFT')
        throw new BadRequestException('Only DRAFT invoices can be approved');

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'INVOICE',
        trigger: 'INVOICE_APPROVAL',
        entityData: invoice,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Invoice approval rejected by business rules.',
        );
      }

      const approvedInvoice = await tx.invoice.updateMany({
        where: { id: invoiceId, companyId, status: 'DRAFT' },
        data: { status: 'SENT' },
      });

      if (approvedInvoice.count === 0) {
        throw new BadRequestException(
          'Invoice is not in DRAFT status or already approved',
        );
      }

      // LEDGER INTEGRATION (Double Entry)
      const arAccount = await tx.account.upsert({
        where: { companyId_code: { companyId, code: '1200' } },
        update: {},
        create: {
          companyId,
          name: 'Accounts Receivable',
          code: '1200',
          type: 'ASSET',
        },
      });

      const revAccount = await tx.account.upsert({
        where: { companyId_code: { companyId, code: '4000' } },
        update: {},
        create: {
          companyId,
          name: 'Freight Revenue',
          code: '4000',
          type: 'REVENUE',
        },
      });

      await tx.journalEntry.create({
        data: {
          companyId,
          referenceType: 'INVOICE',
          referenceId: invoice.id,
          description: `Invoice ${invoice.invoiceNumber} for ${invoice.customer.name}`,
          status: 'POSTED',
          lines: {
            create: [
              {
                companyId,
                accountId: arAccount.id,
                debit: invoice.amount,
                credit: 0,
                description: 'AR',
              },
              {
                companyId,
                accountId: revAccount.id,
                debit: 0,
                credit: invoice.amount,
                description: 'Revenue',
              },
            ],
          },
        },
      });

      return { ...invoice, status: 'SENT' };
    });
  }
}

import { Controller, Post, Req, Res, Headers, Logger } from '@nestjs/common';
import { ApiTags } from '@nestjs/swagger';

@ApiTags('Billing')
@Controller('billing/stripe')
export class StripeController {
  private readonly logger = new Logger(StripeController.name);

  @Post('webhook')
  async handleWebhook(
    @Req() req: any,
    @Res() res: any,
    @Headers('stripe-signature') signature: string,
  ) {
    this.logger.log('Received Stripe Webhook');
    // Scaffolded: Needs Stripe library and Endpoint Secret to verify signature
    // const event = this.stripe.webhooks.constructEvent(req.body, signature, process.env.STRIPE_WEBHOOK_SECRET);

    // Fake event for scaffolding
    const event = req.body;

    switch (event.type) {
      case 'invoice.paid':
        this.logger.log('Invoice paid event processed');
        break;
      case 'invoice.payment_failed':
        this.logger.log('Invoice payment failed event processed');
        break;
      case 'customer.subscription.updated':
        this.logger.log('Subscription updated event processed');
        break;
      case 'customer.subscription.deleted':
        this.logger.log('Subscription deleted event processed');
        break;
      default:
        this.logger.warn(`Unhandled Stripe event type: ${event.type}`);
    }

    return res.status(200).send({ received: true });
  }
}

