  describe('Multi-Channel Dispatch & Rate Limiting', () => {
    it('should dispatch notification to target user across enabled channels', async () => {
      mockPrisma.notificationTemplate.findFirst.mockResolvedValueOnce({
        id: 'tpl-1',
