      const res = await orchestrator.dispatchNotification('comp-1', 'admin-1', {
        targetUserId: 'usr-1',
        eventType: 'load.ready',
        priority: NotificationPriority.HIGH,
        templateData: { driver: 'John', loadNumber: 'LD-100' },
      });

      expect(res.success).toBe(true);
      expect(res.results.length).toBeGreaterThanOrEqual(1);
      expect(mockSse.emitToUser).toHaveBeenCalled();
    });
  });

  describe('Metrics & Resilience', () => {
    it('should get delivery metrics breakdown', async () => {
      const metrics = await orchestrator.getDeliveryMetrics('comp-1');
      expect(metrics.summary.delivered).toBeDefined();
      expect(metrics.channelBreakdown).toHaveLength(1);
    });

    it('should retry failed notification deliveries', async () => {
      const retry = await orchestrator.retryFailedDeliveries(
        'comp-1',
        'admin-1',
      );
      expect(retry.requeuedCount).toBe(1);
      expect(mockQueue.add).toHaveBeenCalled();
    });
  });
});

import { Injectable, Logger } from '@nestjs/common';
import { Subject } from 'rxjs';

@Injectable()
export class SseService {
  private readonly logger = new Logger(SseService.name);

  // In a multi-instance production environment, this would be backed by Redis Pub/Sub.
  // We use an RxJS Subject for MVP local instance pub/sub.
  private events$ = new Subject<{ userId: string; event: any }>();

  subscribe(userId: string) {
    // Returns an observable filtered by userId
    return this.events$.asObservable();
  }

  emitToUser(userId: string, data: any) {
    this.logger.log(`Emitting event to user ${userId}`);
    this.events$.next({ userId, event: data });
  }

  emitToCompany(companyId: string, data: any) {
    this.logger.log(`Emitting event to company ${companyId}`);
    // MVP implementation: we just emit a generic event and clients filter
    this.events$.next({
      userId: 'ALL',
      event: { ...data, targetCompanyId: companyId },
    });
  }
}

import { Controller, Get, Req, UseGuards } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';

@Controller('dashboard')
@UseGuards(JwtAuthGuard, ThrottlerGuard)
export class ExecutiveDashboardController {
  constructor(private prisma: PrismaService) {}

  @Get('ceo')
  @Throttle({ default: { limit: 500, ttl: 60000 } }) // Prevent DDoS on heavy read-replica queries (500 requests per minute)
  async getCeoMetrics(@Req() req: any) {
    const companyId = req.user.companyId;
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Run parallel aggregation queries optimized for read-replicas
    const [revenue, expenses, activeTrips, idleTrucks] = await Promise.all([
      // Today's Revenue (Generated Invoices)
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.invoice.aggregate({
          _sum: { amount: true },
          where: {
            companyId,
            createdAt: { gte: today },
            status: { in: ['GENERATED', 'PAID'] },
          },
        }),
      ),
      // Today's Expenses (Fuel, Toll, Cash)
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.expense.aggregate({
          _sum: { amount: true },
          where: { companyId, date: { gte: today } },
        }),
      ),
      // Active Trips Count
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.trip.count({
          where: { companyId, status: 'IN_TRANSIT' },
        }),
      ),
      // Idle Trucks Count (Assuming no active trip means idle)
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.vehicle.count({
          where: {
            companyId,
            status: 'ACTIVE',
            tripsVehicle: { none: { status: 'IN_TRANSIT' } },
          },
        }),
      ),
    ]);

    return {
      todaysRevenue: revenue._sum?.amount || 0,
      todaysExpenses: expenses._sum?.amount || 0,
      activeTrips,
      idleTrucks,
      cashPosition: (revenue._sum?.amount || 0) - (expenses._sum?.amount || 0),
    };
  }
}

import type { AuthenticatedUser } from '../auth/decorators/get-user.decorator';
import { GetUser } from '../auth/decorators/get-user.decorator';
import {
  Controller,
  Post,
  Get,
  Body,
  Param,
  UseGuards,
  Request,
  Res,
} from '@nestjs/common';
import { ExportService } from './export.service';
import { ImportService } from './import.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../auth/guards/permissions.guard';
