import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { parse } from 'json2csv';
import * as archiver from 'archiver';
import * as crypto from 'crypto';
import { Response } from 'express';

@Injectable()
export class ExportService {
  private readonly logger = new Logger(ExportService.name);

  constructor(private readonly prisma: PrismaService) {}

  async exportCompanyData(
    companyId: string,
    modules: string[],
    format: string,
    res: Response,
  ) {
    this.logger.log(
      `Starting enterprise export for company ${companyId}, modules: ${modules.join(',')}`,
    );

    const exportData: Record<string, any[]> = {};

    // Enforce tenant isolation via Prisma runAsTenant where applicable, or explicit where checks
    if (modules.includes('Fleet')) {
      exportData.vehicles = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.vehicle.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Drivers')) {
      exportData.drivers = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.driver.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Customers')) {
      exportData.customers = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.customer.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Loads')) {
      exportData.loads = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.load.findMany({
          where: { companyId },
          take: 10000,
        }),
      );
    }
    if (modules.includes('Trips')) {
      exportData.trips = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.trip.findMany({
          where: { companyId },
          take: 10000,
        }),
      );
    }
    if (modules.includes('Invoices')) {
      exportData.invoices = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.invoice.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('AuditLogs')) {
      exportData.auditLogs = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.auditLog.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }

    if (format.toLowerCase() === 'json') {
      res.setHeader('Content-Type', 'application/json');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="parilink_export_${companyId}.json"`,
      );
      return res.send(exportData);
    }

    if (format.toLowerCase() === 'csv') {
      const archive = (archiver as any)('zip', { zlib: { level: 9 } });
      res.setHeader('Content-Type', 'application/zip');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="parilink_export_${companyId}.zip"`,
      );

      archive.pipe(res);

      for (const [key, data] of Object.entries(exportData)) {
        if (data.length > 0) {
          try {
            const csv = parse(data);
            archive.append(csv, { name: `${key}.csv` });
          } catch (err) {
            this.logger.error(`Error parsing CSV for ${key}`, err);
          }
        }
      }

      await archive.finalize();
      return;
    }

    throw new BadRequestException(`Unsupported export format: ${format}`);
  }
}

import { AuditService } from '../platform/audit/audit.service';
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class ImportService {
  private readonly logger = new Logger(ImportService.name);

  constructor(
    private readonly auditService: AuditService,
    private readonly prisma: PrismaService,
  ) {}

  async importData(
    companyId: string,
    moduleType: string,
    data: any[],
    userId: string,
  ) {
    this.logger.log(
      `Starting enterprise import for company ${companyId}, module: ${moduleType}`,
    );

    // Enterprise safeguards: Rollback on failure, limit to 1000 rows
    if (data.length > 1000) {
      throw new BadRequestException(
        'Import payload exceeds maximum allowed size of 1000 records per batch.',
      );
    }

    try {
      return await this.prisma.$transaction(async (tx) => {
        let importedCount = 0;
        for (const record of data) {
          if (moduleType === 'Customers') {
            await tx.customer.create({
              data: {
                companyId,
                name: record.name,
                email: record.email,
                phone: record.phone,
                status: 'ACTIVE',
              },
            });
            importedCount++;
          }
        }

        // Log Audit Event
        await this.auditService.logEvent(
          {
            companyId,
            userId,
            action: 'BULK_IMPORT',
            entity: moduleType,
            entityId: 'BATCH',
            details: { recordCount: importedCount },
          },
          null,
          tx,
        );

        return { success: true, importedCount };
      });
    } catch (error) {
      this.logger.error('Import transaction failed, rolling back.', error);
      throw new BadRequestException(
        'Import failed due to validation or integrity errors.',
      );
    }
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { DispatchService } from './dispatch.service';
import { PrismaService } from '../prisma/prisma.service';
import { WorkflowService } from '../workflow/workflow.service';
import { BadRequestException } from '@nestjs/common';

describe('DispatchService', () => {
  let service: DispatchService;

  const mockTx = {
    load: {
      findUnique: jest.fn(),
      findFirst: jest.fn(),
      findMany: jest.fn(),
      update: jest.fn(),
      updateMany: jest.fn(),
    },
    driver: {
      findUnique: jest.fn(),
      findMany: jest.fn(),
      update: jest.fn(),
    },
    vehicle: {
      findUnique: jest.fn(),
      findMany: jest.fn(),
    },
    trip: {
      findMany: jest.fn(),
      create: jest.fn(),
      findFirst: jest.fn(),
    },
    trailer: { findMany: jest.fn() },
  };

  const mockPrisma = {
    runAsSystem: jest.fn().mockImplementation(async (cb) => cb(mockPrisma)),
    runAsTenant: jest.fn((companyId: string, cb: (tx: any) => any) =>
      cb(mockTx),
    ),
    updateWithOcc: jest.fn().mockResolvedValue({ status: 'IN_PROGRESS' }),
    load: {
      findFirst: jest.fn(),
      update: jest.fn(),
    },
  };

  beforeEach(async () => {
    jest.clearAllMocks();

    const mockWorkflowService = {
      evaluateRules: jest.fn().mockResolvedValue({ triggeredActions: [] }),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        DispatchService,
        { provide: PrismaService, useValue: mockPrisma },
        { provide: WorkflowService, useValue: mockWorkflowService },
        { provide: EventEmitter2, useValue: { emit: jest.fn() } },
      ],
    }).compile();
    service = module.get<DispatchService>(DispatchService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('getBoardData', () => {
    it('should return all board data with metrics', async () => {
      mockTx.load.findMany.mockResolvedValue([
        { id: 'load-1', status: 'PENDING' },
      ]);
      mockTx.driver.findMany.mockResolvedValue([
        { id: 'driver-1', status: 'AVAILABLE' },
      ]);
      mockTx.vehicle.findMany.mockResolvedValueOnce([
        { id: 'vehicle-1', type: 'TRUCK' },
      ]);
      mockTx.vehicle.findMany.mockResolvedValueOnce([
        { id: 'trailer-1', type: 'TRAILER' },
      ]);
      mockTx.trip.findMany.mockResolvedValue([
        { id: 'trip-1', status: 'PLANNED' },
      ]);

      const result = await service.getBoardData('company-1');

      expect(result.pendingLoads).toHaveLength(1);
      expect(result.availableDrivers).toHaveLength(1);
      expect(result.metrics.pendingLoadsCount).toBe(1);
      expect(result.metrics.availableDriversCount).toBe(1);
      expect(result.metrics.activeTripsCount).toBe(1);
    });
  });

  describe('moveBoardCard', () => {
    it('should throw BadRequestException if load not found', async () => {
      mockTx.load.findFirst.mockResolvedValue(null);
      await expect(
        service.moveBoardCard('company-1', 'load-1', 'IN_PROGRESS', 2),
      ).rejects.toThrow(BadRequestException);
    });

    it('should update load status and position', async () => {
      const mockLoad = { id: 'load-1', status: 'PENDING' };
      mockTx.load.findFirst.mockResolvedValue(mockLoad);
      mockTx.load.update.mockResolvedValue({
        ...mockLoad,
        status: 'IN_PROGRESS',
        boardPosition: 2,
      });

      const result = await service.moveBoardCard(
        'company-1',
        'load-1',
        'IN_PROGRESS',
        2,
      );
      expect(result.status).toBe('IN_PROGRESS');
    });
  });

  describe('Tenant Isolation', () => {
    it('should always call runAsTenant with the provided companyId', async () => {
      mockTx.load.findMany.mockResolvedValue([]);
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.vehicle.findMany.mockResolvedValue([]);
      mockTx.trip.findMany.mockResolvedValue([]);

      await service.getBoardData('company-specific-id');

      expect(mockPrisma.runAsTenant).toHaveBeenCalledWith(
        'company-specific-id',
        expect.any(Function),
      );
    });

    it('should not allow data from a different company', async () => {
      // Each runAsTenant call is scoped — verify it is not called with the wrong ID
      mockTx.load.findMany.mockResolvedValue([]);
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.vehicle.findMany.mockResolvedValue([]);
      mockTx.trip.findMany.mockResolvedValue([]);

      await service.getBoardData('company-A');

      const calls = mockPrisma.runAsTenant.mock.calls;
      expect(calls.every((c) => c[0] === 'company-A')).toBe(true);
    });
  });
});

import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class DispatchService {
  constructor(
    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
  ) {}

  async getBoardData(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const [
        pendingLoads,
        availableDrivers,
        availableVehicles,
        availableTrailers,
        activeTrips,
      ] = await Promise.all([
        // 1. Pending Loads
        tx.load.findMany({
          where: { companyId, status: 'PENDING' },
          include: { customer: true },
          orderBy: { createdAt: 'desc' },
          take: 50,
        }),

        // 2. Available Drivers
        tx.driver.findMany({
          where: { companyId, status: 'AVAILABLE' },
          orderBy: { firstName: 'asc' },
          take: 100,
        }),

        // 3. Available Vehicles
        tx.vehicle.findMany({
          where: {
            companyId,
            status: 'IN_SERVICE',
            type: { not: 'TRAILER' },
          },
          orderBy: { licensePlate: 'asc' },
          take: 100,
        }),

        // 4. Available Trailers
        tx.vehicle.findMany({
          where: {
            companyId,
            status: 'IN_SERVICE',
            type: 'TRAILER',
          },
          orderBy: { licensePlate: 'asc' },
          take: 100,
        }),

        // 5. Active Trips
        tx.trip.findMany({
          where: {
            companyId,
            status: { in: ['PLANNED', 'DISPATCHED', 'IN_PROGRESS'] },
          },
          include: { driver: true, vehicle: true, trailer: true, loads: true },
          orderBy: { startDate: 'asc' },
          take: 100,
        }),
      ]);

      return {
        pendingLoads,
        availableDrivers,
        availableVehicles,
        availableTrailers,
        activeTrips,
        metrics: {
          pendingLoadsCount: pendingLoads.length,
          availableDriversCount: availableDrivers.length,
          availableVehiclesCount: availableVehicles.length,
          availableTrailersCount: availableTrailers.length,
          activeTripsCount: activeTrips.length,
        },
      };
    });
  }

  async moveBoardCard(
    companyId: string,
    loadId: string,
    newStatus: string,
    boardPosition: number,
  ) {
    const updatedLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id: loadId, companyId },
      });

      if (!existingLoad) {
        throw new BadRequestException('Load not found');
      }

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'DISPATCH',
        trigger: 'BOARD_CARD_MOVED',
        entityData: { load: existingLoad, newStatus, boardPosition },
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Dispatch move rejected by business rules.',
        );
      }

      return this.prisma.updateWithOcc<any>(
        tx,
        'load',
        loadId,
        existingLoad.updatedAt,
        { status: newStatus, boardPosition },
      );
    });

    this.eventEmitter.emit('dispatch.updated', {
      loadId,
      newStatus,
      boardPosition,
    });

    return updatedLoad;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { PredictionEngineService } from '../../ai/prediction/prediction.service';

@Injectable()
export class AiOperationsService {
  private readonly logger = new Logger(AiOperationsService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly aiPrediction: PredictionEngineService,
  ) {}

  /**
   * Predicts ETAs for active trips dynamically based on current GPS, weather, and historical telemetry.
   * Target execution: Background or fast query (<100ms)
   */
  async predictTripEta(companyId: string, tripId: string) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: { id: tripId, companyId },
        include: { loads: true },
      }),
    );

    if (!trip) return null;

    // Call underlying AI Prediction Service
    const prediction = await this.aiPrediction.generatePrediction(
      companyId,
      'Trip',
      trip.id,
      {
        origin: trip.loads[0]?.originCity,
        destination: trip.loads[0]?.destinationCity,
        departureTime: trip.startDate,
        currentTime: new Date(),
      },
    );

    const predictedData = prediction?.predictedValue as any;
    if (predictedData && predictedData.eta) {
      const newEta = new Date(predictedData.eta);
      // Update trip ETA
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.trip.update({
          where: { id: trip.id },
          data: { eta: newEta },
        }),
      );

      // Issue event for potential delay
      if (trip.eta && newEta > trip.eta) {
        await this.eventStore.append({
          tenantId: companyId,
          streamId: trip.id,
          streamType: 'TRIP',
          eventType: 'TripDelayPredicted',
          payload: { originalEta: trip.eta, newEta },
          userId: 'SYSTEM',
        });
      }
    }

    return prediction;
  }

  /**
   * Evaluates Risk Scoring for a trip based on driver behavior, vehicle maintenance, and route weather.
   */
  async evaluateRiskScore(
    companyId: string,
    tripId: string,
  ): Promise<{ score: number; factors: string[] }> {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: { id: tripId, companyId },
        include: { driver: true, vehicle: true },
      }),
    );

    if (!trip) return { score: 0, factors: [] };

    let score = 0;
    const factors: string[] = [];

    // Simple heuristic-based risk for speed, actual AI would use tensor scoring
    if (trip.driver) {
      // check violations (mock)
      const violations = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            entity: 'Driver',
            entityId: trip.driver?.id || '',
            action: 'OVERSPEED_DETECTED',
          },
        }),
      );
      if (violations > 0) {
        score += violations * 10;
        factors.push(`${violations} recent speed violations`);
      }
    }

    if (trip.vehicle) {
      // Mock logic: checking recent incidents or breakdowns
      const incidents = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            entity: 'Vehicle',
            entityId: trip.vehicle?.id || '',
            action: 'BREAKDOWN_REPORTED',
          },
        }),
      );
      if (incidents > 0) {
        score += 30;
        factors.push(`Recent breakdowns reported on vehicle`);
      }
    }

    return { score: Math.min(score, 100), factors };
  }

  async recommendDriverForLoad(companyId: string, loadId: string) {
    const load = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.load.findFirst({
        where: { id: loadId, companyId },
      }),
    );
    if (!load) return [];

    // Find available drivers and score them based on proximity and duty hours
    const availableDrivers = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.driver.findMany({
          where: { companyId, status: 'AVAILABLE' },
        }),
    );

    return availableDrivers
      .map((d, index) => ({
        driverId: d.id,
        name: `${d.firstName} ${d.lastName}`,
        score: 85 - index * 5, // Deterministic placeholder score
        reason: 'Optimal duty hours and proximity',
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, 5);
  }
}

import { Injectable, Logger } from '@nestjs/common';

export interface ConstraintContext {
  load: {
    weight?: number | null;
    volume?: number | null;
    equipmentType?: string | null;
    pickupDate: Date;
    deliveryDate: Date;
  };
  vehicle: {
    id: string;
    capacityWeight?: number | null;
    capacityVolume?: number | null;
    type: string;
    status: string;
  };
  driver: {
    id: string;
    licenseExpiry?: Date | null;
    status: string;
  };
}

export interface ConstraintResult {
  passed: boolean;
  violations: Array<{
    constraint: string;
    message: string;
    isFatal: boolean;
    vehicleId?: string;
    driverId?: string;
  }>;
}

@Injectable()
export class ConstraintEngine {
  private readonly logger = new Logger(ConstraintEngine.name);

  evaluate(ctx: ConstraintContext, config?: any): ConstraintResult {
    const violations: ConstraintResult['violations'] = [];

    // Default strictness to true if not provided in config
    const strictWeight = config?.strictWeight !== false;
    const strictVolume = config?.strictVolume !== false;

    // ── Vehicle Constraints ─────────────────────────────────

    // 1. Vehicle must be IN_SERVICE
    if (ctx.vehicle.status !== 'IN_SERVICE') {
      violations.push({
        constraint: 'VEHICLE_NOT_AVAILABLE',
        message: `Vehicle ${ctx.vehicle.id} status is ${ctx.vehicle.status}, not IN_SERVICE.`,
        isFatal: true,
        vehicleId: ctx.vehicle.id,
      });
    }

    // 2. Weight Capacity
    if (ctx.load.weight && ctx.vehicle.capacityWeight) {
      if (ctx.load.weight > ctx.vehicle.capacityWeight) {
        violations.push({
          constraint: 'WEIGHT_EXCEEDED',
          message: `Load weight ${ctx.load.weight}kg exceeds vehicle capacity ${ctx.vehicle.capacityWeight}kg.`,
          isFatal: strictWeight,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // 3. Volume Capacity
    if (ctx.load.volume && ctx.vehicle.capacityVolume) {
      if (ctx.load.volume > ctx.vehicle.capacityVolume) {
        violations.push({
          constraint: 'VOLUME_EXCEEDED',
          message: `Load volume ${ctx.load.volume}m³ exceeds vehicle capacity ${ctx.vehicle.capacityVolume}m³.`,
          isFatal: strictVolume,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // 4. Equipment Type Compatibility
    if (ctx.load.equipmentType && ctx.vehicle.type) {
      if (
        ctx.load.equipmentType === 'REFRIGERATED' &&
        ctx.vehicle.type !== 'REEFER'
      ) {
        violations.push({
          constraint: 'EQUIPMENT_MISMATCH',
          message: `Load requires REFRIGERATED equipment but vehicle type is ${ctx.vehicle.type}.`,
          isFatal: true,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // ── Driver Constraints ──────────────────────────────────

    // 5. Driver must be AVAILABLE
    if (ctx.driver.status !== 'AVAILABLE') {
      violations.push({
        constraint: 'DRIVER_NOT_AVAILABLE',
        message: `Driver ${ctx.driver.id} status is ${ctx.driver.status}, not AVAILABLE.`,
        isFatal: true,
        driverId: ctx.driver.id,
      });
    }

    // 6. Driver Licence Expiry
    if (ctx.driver.licenseExpiry) {
      const now = new Date();
      if (ctx.driver.licenseExpiry < now) {
        violations.push({
          constraint: 'LICENSE_EXPIRED',
          message: `Driver ${ctx.driver.id} licence expired on ${ctx.driver.licenseExpiry.toISOString()}.`,
          isFatal: true,
          driverId: ctx.driver.id,
        });
      }
      // Warn if licence expires within 30 days
      const thirtyDays = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
      if (ctx.driver.licenseExpiry < thirtyDays) {
        violations.push({
          constraint: 'LICENSE_EXPIRING_SOON',
          message: `Driver ${ctx.driver.id} licence expires on ${ctx.driver.licenseExpiry.toISOString()}.`,
          isFatal: false,
          driverId: ctx.driver.id,
        });
      }
    }

    return {
      passed: violations.filter((v) => v.isFatal).length === 0,
      violations,
    };
  }
}

import type { AuthenticatedUser } from '../../auth/decorators/get-user.decorator';
import { GetUser } from '../../auth/decorators/get-user.decorator';
import {
  Controller,
  Post,
  Get,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  UploadedFile,
  BadRequestException,
  Req,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import {
  ApiTags,
  ApiOperation,
  ApiBearerAuth,
  ApiConsumes,
  ApiBody,
} from '@nestjs/swagger';
import { PlatformFileInterceptor } from '../../platform/files/file.interceptor';
import type { Request } from 'express';

import {
  CreateFolderDto,
  UpdateFolderDto,
  CheckoutDocumentDto,
  CheckinDocumentDto,
  CreateSignatureRequestDto,
  SignDocumentDto,
  CreateComplianceRequirementDto,
  ClassifyDocumentDto,
} from '../dto/document.dto';

import { DocumentFolderService } from '../services/document-folder.service';
import { DocumentVersionService } from '../services/document-version.service';
import { DocumentSignatureService } from '../services/document-signature.service';
import { DocumentComplianceService } from '../services/document-compliance.service';
import { DocumentAiService } from '../services/document-ai.service';

@ApiTags('Enterprise Document Management & Compliance')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('documents/enterprise')
export class EnterpriseDocumentController {
  constructor(
    private readonly folderService: DocumentFolderService,
    private readonly versionService: DocumentVersionService,
    private readonly signatureService: DocumentSignatureService,
    private readonly complianceService: DocumentComplianceService,
    private readonly aiService: DocumentAiService,
  ) {}

  // 1. Folder & Tree Management
  @Get('folders/tree')
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'Get hierarchical document folder tree' })
  async getFolderTree(@GetUser() user: AuthenticatedUser) {
    return this.folderService.getFolderTree(user.companyId);
  }

  @Post('folders')
  @RequirePermissions('documents:create')
  @ApiOperation({ summary: 'Create folder' })
  async createFolder(
    @Body() dto: CreateFolderDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.folderService.createFolder(user.companyId, user.userId, dto);
  }

  @Put('folders/:id')
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Update folder name or location' })
  async updateFolder(
    @Param('id') id: string,
    @Body() dto: UpdateFolderDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.folderService.updateFolder(
      user.companyId,
      id,
      user.userId,
      dto,
    );
  }

  @Delete('folders/:id')
  @RequirePermissions('documents:delete')
  @ApiOperation({ summary: 'Delete empty folder' })
  async deleteFolder(
    @Param('id') id: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.folderService.deleteFolder(user.companyId, id, user.userId);
  }

  @Put('move/:documentId')
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Move document to another folder' })
  async moveDocument(
    @Param('documentId') documentId: string,
    @Body('folderId') folderId: string | null,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.folderService.moveDocument(
      user.companyId,
      documentId,
      folderId || null,
      user.userId,
    );
  }

  // 2. Version Control & Checkout/Checkin
  @Post(':documentId/checkout')
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Lock document for editing (checkout)' })
  async checkoutDocument(
    @Param('documentId') documentId: string,
    @Body() dto: CheckoutDocumentDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.versionService.checkout(
      user.companyId,
      documentId,
      user.userId,
      dto,
    );
  }

  @Post(':documentId/checkin')
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Check in a new version of a document' })
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: { type: 'string', format: 'binary' },
        changeSummary: { type: 'string', example: 'Updated pricing and terms' },
      },
    },
  })
  @PlatformFileInterceptor('file', 5)
  async checkinDocument(
    @Param('documentId') documentId: string,
    @UploadedFile() file: Express.Multer.File,
    @Body() dto: CheckinDocumentDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    if (!file) throw new BadRequestException('File is required for check-in');
    return this.versionService.checkin(
      user.companyId,
      documentId,
      user.userId,
      file,
      dto,
    );
  }

  @Post(':documentId/unlock')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions('documents:update')
  @ApiOperation({
    summary: 'Unlock document without checking in a new version',
  })
  async unlockDocument(
    @Param('documentId') documentId: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.versionService.unlock(
      user.companyId,
      documentId,
      user.userId,
      false,
    );
  }

  @Get(':documentId/versions')
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'Get full version history of a document' })
  async getVersionHistory(
    @Param('documentId') documentId: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.versionService.getVersionHistory(user.companyId, documentId);
  }

  @Post(':documentId/revert/:version')
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Revert document to an older version number' })
  async revertVersion(
    @Param('documentId') documentId: string,
    @Param('version') version: number,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.versionService.revertToVersion(
      user.companyId,
      documentId,
      Number(version),
      user.userId,
    );
  }

  // 3. E-Signatures & Verification
  @Post(':documentId/signatures')
  @RequirePermissions('documents:create')
  @ApiOperation({ summary: 'Request e-signature on document' })
  async requestSignature(
    @Param('documentId') documentId: string,
    @Body() dto: CreateSignatureRequestDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.signatureService.requestSignature(
      user.companyId,
      documentId,
      user.userId,
      dto,
    );
  }

  @Get(':documentId/signatures')
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'List all signature requests for a document' })
  async getSignatures(
    @Param('documentId') documentId: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.signatureService.getDocumentSignatures(
      user.companyId,
      documentId,
    );
  }

  @Post('signatures/:signatureId/sign')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Submit cryptographic e-signature' })
  async signDocument(
    @Param('signatureId') signatureId: string,
    @Body() dto: SignDocumentDto,
    @GetUser() user: AuthenticatedUser,
    @Req() req: Request,
  ) {
    const ipAddress =
      req.ip || req.headers['x-forwarded-for']?.toString() || '127.0.0.1';
    const userAgent = req.headers['user-agent'] || 'Unknown Agent';
    return this.signatureService.signDocument(
      user.companyId,
      signatureId,
      dto,
      ipAddress,
      userAgent,
    );
  }

  @Post('signatures/:signatureId/reject')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions('documents:update')
  @ApiOperation({ summary: 'Reject signature request' })
  async rejectSignature(
    @Param('signatureId') signatureId: string,
    @Body('reason') reason?: string,
    @GetUser() user: AuthenticatedUser = {} as any,
  ) {
    return this.signatureService.rejectSignature(
      user.companyId,
      signatureId,
      reason,
    );
  }

  @Get('signatures/:signatureId/certificate')
  @RequirePermissions('documents:read')
  @ApiOperation({
    summary: 'Generate verifiable digital signature audit certificate',
  })
  async getVerificationCertificate(
    @Param('signatureId') signatureId: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.signatureService.generateVerificationCertificate(
      user.companyId,
      signatureId,
    );
  }

