import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import { ClassifyDocumentDto } from '../dto/document.dto';

@Injectable()
export class DocumentAiService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async classifyAndExtractMetadata(
    companyId: string,
    documentId: string,
    userId: string,
    dto: ClassifyDocumentDto,
  ) {
    const doc = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.findUnique({ where: { id: documentId } }),
    );
    if (!doc || doc.companyId !== companyId || doc.deletedAt) {
      throw new NotFoundException('Document not found');
    }

    const text = dto.ocrText.toUpperCase();
    let detectedType = doc.type;
    let confidence = 0.5;
    const extractedMetadata: Record<string, any> = {};

    // 1. Classification rules
    if (
      text.includes('BILL OF LADING') ||
      text.includes('BOL #') ||
      text.includes('B/L')
    ) {
      detectedType = 'BILL_OF_LADING';
      confidence = 0.95;
    } else if (
      text.includes('PROOF OF DELIVERY') ||
      text.includes('POD') ||
      text.includes('RECEIVED BY') ||
      text.includes('CONSIGNEE SIGNATURE')
    ) {
      detectedType = 'PROOF_OF_DELIVERY';
      confidence = 0.92;
    } else if (
      text.includes('COMMERCIAL DRIVER') ||
      text.includes('CDL') ||
      text.includes('DRIVER LICENSE') ||
      text.includes('CLASS A')
    ) {
      detectedType = 'DRIVER_LICENSE';
      confidence = 0.94;
    } else if (
      text.includes('CERTIFICATE OF LIABILITY INSURANCE') ||
      text.includes('ACORD') ||
      text.includes('INSURED') ||
      text.includes('POLICY NUMBER')
    ) {
      detectedType = 'INSURANCE_COI';
      confidence = 0.96;
    } else if (
      text.includes('RATE CONFIRMATION') ||
      text.includes('RATE CONF') ||
      text.includes('CARRIER PAY')
    ) {
      detectedType = 'RATE_CONFIRMATION';
      confidence = 0.9;
    } else if (
      text.includes('INVOICE') ||
      text.includes('AMOUNT DUE') ||
      text.includes('REMIT TO')
    ) {
      detectedType = 'INVOICE';
      confidence = 0.89;
    }

    // 2. Metadata extraction heuristics
    const loadMatch = text.match(
      /(?:LOAD|LD|TRIP|ORDER|BOL)\s*[#:]?\s*([A-Z0-9-]{4,15})/i,
    );
    if (loadMatch && loadMatch[1]) {
      extractedMetadata.loadNumber = loadMatch[1];
    }

    const weightMatch = text.match(/([0-9,]+)\s*(?:LBS|POUNDS|KG)/i);
    if (weightMatch && weightMatch[1]) {
      extractedMetadata.weight = parseInt(weightMatch[1].replace(/,/g, ''), 10);
    }

    const dateMatch = text.match(/(\d{4}-\d{2}-\d{2}|\d{2}\/\d{2}\/\d{4})/);
    if (dateMatch && dateMatch[1]) {
      extractedMetadata.documentDate = dateMatch[1];
    }

    const amountMatch = text.match(
      /(?:\$|USD|TOTAL|AMOUNT)\s*([0-9,]+\.\d{2})/i,
    );
    if (amountMatch && amountMatch[1]) {
      extractedMetadata.totalAmount = parseFloat(
        amountMatch[1].replace(/,/g, ''),
      );
    }

    const policyMatch = text.match(
      /(?:POLICY|POL)\s*[#:]?\s*([A-Z0-9-]{6,20})/i,
    );
    if (policyMatch && policyMatch[1]) {
      extractedMetadata.policyNumber = policyMatch[1];
    }

    // Auto-filing folder matching
    let autoFolderId = doc.folderId;
    if (!autoFolderId) {
      const folders = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.documentFolder.findMany({ where: { companyId } }),
      );
      const matchingFolder = folders.find((f) =>
        f.name.toUpperCase().includes(detectedType.replace(/_/g, ' ')),
      );
      if (matchingFolder) {
        autoFolderId = matchingFolder.id;
      }
    }

    const updatedDoc = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.update({
        where: { id: documentId },
        data: {
          type: detectedType,
          folderId: autoFolderId,
          metadata: {
            ...(typeof doc.metadata === 'object' && doc.metadata !== null
              ? doc.metadata
              : {}),
            ...extractedMetadata,
            aiClassification: {
              detectedType,
              confidence,
              processedAt: new Date().toISOString(),
            },
          },
        },
      }),
    );

    await this.audit.logEvent({
      action: 'document:ai:classify',
      entity: 'Document',
      entityId: documentId,
      userId,
      companyId,
      details: { detectedType, confidence, extractedMetadata, autoFolderId },
    });

    return {
      documentId: doc.id,
      originalType: doc.type,
      detectedType,
      confidence,
      extractedMetadata,
      autoFiledFolderId: autoFolderId,
      updatedDocument: updatedDoc,
    };
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import {
  CreateComplianceRequirementDto,
  EntityComplianceStatus,
} from '../dto/document.dto';

@Injectable()
export class DocumentComplianceService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async createRequirement(
    companyId: string,
    userId: string,
    dto: CreateComplianceRequirementDto,
  ) {
    const req = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.complianceRequirement.create({
        data: {
          companyId,
          entityType: dto.entityType,
          docType: dto.docType,
          name: dto.name,
          description: dto.description || null,
          isMandatory: dto.isMandatory !== undefined ? dto.isMandatory : true,
          validityDays: dto.validityDays || null,
          warningDays: dto.warningDays || 30,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'document:compliance_req:create',
      entity: 'ComplianceRequirement',
      entityId: req.id,
      userId,
      companyId,
      details: {
        entityType: req.entityType,
        docType: req.docType,
        name: req.name,
      },
    });

    return req;
  }

  async getRequirements(companyId: string, entityType?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.complianceRequirement.findMany({
        where: {
          companyId,
          entityType: entityType || undefined,
        },
        orderBy: { entityType: 'asc' },
      }),
    );
  }

  async deleteRequirement(companyId: string, id: string, userId: string) {
    const req = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.complianceRequirement.findUnique({ where: { id } }),
    );
    if (!req || req.companyId !== companyId) {
      throw new NotFoundException('Compliance requirement not found');
    }

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.complianceRequirement.delete({ where: { id } }),
    );

    await this.audit.logEvent({
      action: 'document:compliance_req:delete',
      entity: 'ComplianceRequirement',
      entityId: id,
      userId,
      companyId,
      details: { name: req.name },
    });

    return { success: true, id };
  }

  async evaluateEntityCompliance(
    companyId: string,
    entityType: string,
    entityId: string,
  ) {
    const requirements = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.complianceRequirement.findMany({
        where: { companyId, entityType },
      }),
    );

    const documents = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.findMany({
        where: {
          companyId,
          entityType,
          entityId,
          status: 'ACTIVE',
        },
        orderBy: { createdAt: 'desc' },
      }),
    );

    const now = new Date();
    const thirtyDaysFromNow = new Date();
    thirtyDaysFromNow.setDate(now.getDate() + 30);

    const docMap = new Map<string, any>();
    documents.forEach((doc) => {
      if (!docMap.has(doc.type)) {
        docMap.set(doc.type, doc);
      }
    });

    const evaluations: any[] = [];
    let hasExpiredOrMissingMandatory = false;
    let hasExpiringSoon = false;

    for (const req of requirements) {
      const doc = docMap.get(req.docType);
      let status = EntityComplianceStatus.COMPLIANT;
      let reason = 'Valid document on file';
      let expiresAt: Date | null = null;

      if (!doc) {
        if (req.isMandatory) {
          status = EntityComplianceStatus.NON_COMPLIANT;
          reason = 'Mandatory document missing';
          hasExpiredOrMissingMandatory = true;
        } else {
          status = EntityComplianceStatus.COMPLIANT;
          reason = 'Optional document not provided';
        }
      } else {
        expiresAt = doc.expiresAt;
        if (doc.expiresAt) {
          const expDate = new Date(doc.expiresAt);
          if (expDate <= now) {
            status = EntityComplianceStatus.NON_COMPLIANT;
            reason = 'Document has expired';
            if (req.isMandatory) hasExpiredOrMissingMandatory = true;
          } else {
            const warningDate = new Date();
            warningDate.setDate(now.getDate() + req.warningDays);
            if (expDate <= warningDate) {
              status = EntityComplianceStatus.EXPIRING_SOON;
              reason = `Document expires in less than ${req.warningDays} days`;
              hasExpiringSoon = true;
            }
          }
        }
      }

      evaluations.push({
        requirementId: req.id,
        docType: req.docType,
        requirementName: req.name,
        isMandatory: req.isMandatory,
        documentId: doc ? doc.id : null,
        expiresAt,
        status,
        reason,
      });
    }

    let overallStatus = EntityComplianceStatus.COMPLIANT;
    if (hasExpiredOrMissingMandatory) {
      overallStatus = EntityComplianceStatus.NON_COMPLIANT;
    } else if (hasExpiringSoon) {
      overallStatus = EntityComplianceStatus.EXPIRING_SOON;
    }

    return {
      companyId,
      entityType,
      entityId,
      overallStatus,
      evaluatedAt: now.toISOString(),
      requirementsCount: requirements.length,
      evaluations,
    };
  }

  async scanExpiringDocuments(companyId: string) {
    const now = new Date();
    const warningThreshold = new Date();
    warningThreshold.setDate(now.getDate() + 30);

    const expiringDocs = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.findMany({
        where: {
          companyId,
          status: 'ACTIVE',
          expiresAt: {
            lte: warningThreshold,
            gte: now,
          },
        },
        include: {
          uploadedBy: {
            select: { id: true, email: true, firstName: true, lastName: true },
          },
        },
        orderBy: { expiresAt: 'asc' },
      }),
    );

    const expiredDocs = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.findMany({
        where: {
          companyId,
          status: 'ACTIVE',
          expiresAt: {
            lt: now,
          },
        },
        include: {
          uploadedBy: {
            select: { id: true, email: true, firstName: true, lastName: true },
          },
        },
        orderBy: { expiresAt: 'asc' },
      }),
    );

    return {
      companyId,
      scannedAt: now.toISOString(),
      expiringCount: expiringDocs.length,
      expiredCount: expiredDocs.length,
      expiringWithin30Days: expiringDocs,
      expired: expiredDocs,
    };
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import { CreateFolderDto, UpdateFolderDto } from '../dto/document.dto';

@Injectable()
export class DocumentFolderService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async createFolder(companyId: string, userId: string, dto: CreateFolderDto) {
    if (dto.parentId) {
      const parent = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.documentFolder.findUnique({ where: { id: dto.parentId } }),
      );
      if (!parent || parent.companyId !== companyId) {
        throw new NotFoundException('Parent folder not found');
      }
    }

    const folder = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.create({
        data: {
          companyId,
          name: dto.name,
          parentId: dto.parentId || null,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'document:folder:create',
      entity: 'DocumentFolder',
      entityId: folder.id,
      userId,
      companyId,
      details: { name: folder.name, parentId: folder.parentId },
    });

    return folder;
  }

  async getFolders(companyId: string, parentId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.findMany({
        where: {
          companyId,
          parentId: parentId || null,
        },
        include: {
          _count: {
            select: {
              subFolders: true,
              documents: {},
            },
          },
        },
        orderBy: { name: 'asc' },
      }),
    );
  }

  async getFolderTree(companyId: string) {
    const allFolders = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.findMany({
        where: { companyId },
        orderBy: { name: 'asc' },
      }),
    );

    const folderMap = new Map<string, any>();
    allFolders.forEach((f) => folderMap.set(f.id, { ...f, subFolders: [] }));

    const rootFolders: any[] = [];
    folderMap.forEach((folder) => {
      if (folder.parentId && folderMap.has(folder.parentId)) {
        folderMap.get(folder.parentId).subFolders.push(folder);
      } else {
        rootFolders.push(folder);
      }
    });

    return rootFolders;
  }

  async updateFolder(
    companyId: string,
    id: string,
    userId: string,
    dto: UpdateFolderDto,
  ) {
    const folder = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.findUnique({ where: { id } }),
    );
    if (!folder || folder.companyId !== companyId) {
      throw new NotFoundException('Folder not found');
    }

    if (dto.parentId === id) {
      throw new BadRequestException('A folder cannot be its own parent');
    }

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.update({
        where: { id },
        data: {
          name: dto.name,
          parentId: dto.parentId !== undefined ? dto.parentId : folder.parentId,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'document:folder:update',
      entity: 'DocumentFolder',
      entityId: id,
      userId,
      companyId,
      details: { updates: dto },
    });

    return updated;
  }

  async deleteFolder(companyId: string, id: string, userId: string) {
    const folder = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.findUnique({
        where: { id },
        include: {
          subFolders: true,
          documents: {},
        },
      }),
    );
    if (!folder || folder.companyId !== companyId) {
      throw new NotFoundException('Folder not found');
    }

    if (folder.subFolders.length > 0 || folder.documents.length > 0) {
      throw new BadRequestException(
        'Cannot delete non-empty folder. Move or remove items first.',
      );
    }

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.documentFolder.delete({ where: { id } }),
    );

    await this.audit.logEvent({
      action: 'document:folder:delete',
      entity: 'DocumentFolder',
      entityId: id,
      userId,
      companyId,
      details: { name: folder.name },
    });

    return { success: true, id };
  }

  async moveDocument(
    companyId: string,
    documentId: string,
    folderId: string | null,
    userId: string,
  ) {
    const doc = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.findUnique({ where: { id: documentId } }),
    );
    if (!doc || doc.companyId !== companyId) {
      throw new NotFoundException('Document not found');
    }

    if (folderId) {
      const targetFolder = await this.prisma.runAsTenant(
        companyId,
        async (tx) => tx.documentFolder.findUnique({ where: { id: folderId } }),
      );
      if (!targetFolder || targetFolder.companyId !== companyId) {
        throw new NotFoundException('Target folder not found');
      }
    }

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.document.update({
        where: { id: documentId },
        data: { folderId },
      }),
    );

    await this.audit.logEvent({
      action: 'document:move',
      entity: 'Document',
      entityId: documentId,
      userId,
      companyId,
      details: { previousFolderId: doc.folderId, newFolderId: folderId },
    });

    return updated;
  }
}

import { Test, TestingModule } from '@nestjs/testing';
