      mockTx.driver.create.mockResolvedValue(mockDriver);

      const result = await service.create('company-1', dto);

      expect(result).toEqual(mockDriver);
      expect(mockTx.driver.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({
            companyId: 'company-1',
            licenseExpiry: new Date('2028-01-01'),
          }),
        }),
      );
    });

    it('should create a driver without licenseExpiry', async () => {
      const dto = {
        firstName: 'Jane',
        lastName: 'Smith',
        licenseNumber: 'DL-99999',
        phone: '+9999999999',
      };
      const mockDriver = { id: 'driver-2', companyId: 'company-1', ...dto };
      mockTx.driver.create.mockResolvedValue(mockDriver);

      const result = await service.create('company-1', dto);
      expect(result).toEqual(mockDriver);
    });
  });

  describe('findAll', () => {
    it('should return paginated drivers', async () => {
      mockTx.driver.findMany.mockResolvedValue([{ id: 'driver-1' }]);
      mockTx.driver.count.mockResolvedValue(1);

      const result = await service.findAll('company-1', { page: 1, limit: 10 });

      expect(result.data).toHaveLength(1);
      expect(result.meta.total).toBe(1);
    });

    it('should filter by status when provided', async () => {
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.driver.count.mockResolvedValue(0);

      await service.findAll('company-1', { status: 'AVAILABLE' });

      expect(mockTx.driver.findMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({
            status: 'AVAILABLE',
          }),
        }),
      );
    });

    it('should apply search filter when provided', async () => {
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.driver.count.mockResolvedValue(0);

      await service.findAll('company-1', { search: 'john' });

      expect(mockTx.driver.findMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ OR: expect.any(Array) }),
        }),
      );
    });
  });

  describe('findOne', () => {
    it('should return a driver if found', async () => {
      const mockDriver = { id: 'driver-1', firstName: 'John' };
      mockTx.driver.findFirst.mockResolvedValue(mockDriver);

      const result = await service.findOne('company-1', 'driver-1');
      expect(result).toEqual(mockDriver);
    });

    it('should throw NotFoundException if driver not found', async () => {
      mockTx.driver.findFirst.mockResolvedValue(null);
      await expect(service.findOne('company-1', 'driver-999')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('remove', () => {
    it('should soft-delete driver and set status to TERMINATED', async () => {
      const mockDriver = {
        id: 'driver-1',
        firstName: 'John',
        status: 'AVAILABLE',
      };
      mockTx.driver.findFirst.mockResolvedValue(mockDriver);
      mockTx.driver.update.mockResolvedValue({
        ...mockDriver,
        deletedAt: new Date(),
        status: 'TERMINATED',
      });

      const result = await service.remove('company-1', 'driver-1');
      expect(result.status).toBe('TERMINATED');
      expect(result.deletedAt).toBeDefined();
    });

    it('should throw NotFoundException if driver not found', async () => {
      mockTx.driver.findFirst.mockResolvedValue(null);
      await expect(service.remove('company-1', 'driver-999')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('update', () => {
    it('should update a driver', async () => {
      const existing = { id: 'driver-1', firstName: 'John' };
      const updated = { ...existing, firstName: 'Johnny' };
      mockTx.driver.findFirst.mockResolvedValue(existing);
      mockTx.driver.update.mockResolvedValue(updated);

      const result = await service.update('company-1', 'driver-1', {
        firstName: 'Johnny',
      });
      expect(result.firstName).toBe('Johnny');
    });

    it('should throw NotFoundException if driver not found', async () => {
      mockTx.driver.findFirst.mockResolvedValue(null);
      await expect(
        service.update('company-1', 'driver-999', {} as any),
      ).rejects.toThrow(NotFoundException);
    });
  });
});

import { AuditService } from '../platform/audit/audit.service';
import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import {
  Injectable,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateDriverDto } from './dto/create-driver.dto';
import { UpdateDriverDto } from './dto/update-driver.dto';
import { DriverQueryDto } from './dto/driver-query.dto';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class DriversService {
  constructor(
    private readonly auditService: AuditService,

    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
  ) {}

  async create(companyId: string, createDriverDto: CreateDriverDto) {
    const newDriver = await this.prisma.runAsTenant(companyId, async (tx) => {
      // 1. Duplicate Prevention
      if (createDriverDto.email || createDriverDto.licenseNumber) {
        const orConditions = [];
        if (createDriverDto.email)
          orConditions.push({ email: createDriverDto.email });
        if (createDriverDto.licenseNumber)
          orConditions.push({ licenseNumber: createDriverDto.licenseNumber });

        const existing = await tx.driver.findFirst({
          where: {
            companyId,
            OR: orConditions,
          },
        });

        if (existing) {
          throw new ConflictException(
            'A driver with this email or license number already exists.',
          );
        }
      }

      const data: any = { ...createDriverDto, companyId };
      if (data.licenseExpiry) {
        data.licenseExpiry = new Date(data.licenseExpiry);
      }
      const newDriver = await tx.driver.create({ data });

      // 2. Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'DRIVER',
        trigger: 'DRIVER_CREATED',
        entityData: newDriver,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new Error('Driver creation rejected by business rules.');
      }

      // 3. Audit Logging
      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Driver',
          entityType: 'Driver',
          entityId: newDriver.id,
          action: 'CREATE',
          details: { ...newDriver },
          source: 'API',
        },
        null,
        tx,
      );

      return newDriver;
    });

    this.eventEmitter.emit('driver.created', newDriver);

    return newDriver;
  }

  async findAll(companyId: string, query: DriverQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { page = 1, limit = 10, search, status } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.DriverWhereInput = {};

      if (search) {
        where.OR = [
          { firstName: { contains: search, mode: 'insensitive' } },
          { lastName: { contains: search, mode: 'insensitive' } },
          { email: { contains: search, mode: 'insensitive' } },
          { licenseNumber: { contains: search, mode: 'insensitive' } },
        ];
      }

      if (status) {
        where.status = status;
      }

      const [data, total] = await Promise.all([
        tx.driver.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
        }),
        tx.driver.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const driver = await tx.driver.findFirst({
        where: { id },
      });

      if (!driver) {
        throw new NotFoundException(`Driver with ID ${id} not found`);
      }
      return driver;
    });
  }

  async update(
    companyId: string,
    id: string,
    updateDriverDto: UpdateDriverDto,
  ) {
    const updatedDriver = await this.prisma.runAsTenant(
      companyId,
      async (tx) => {
        const existingDriver = await tx.driver.findFirst({
          where: { id },
        });
        if (!existingDriver) throw new NotFoundException();

        // Duplicate Prevention
        if (updateDriverDto.email || updateDriverDto.licenseNumber) {
          const orConditions = [];
          if (updateDriverDto.email)
            orConditions.push({ email: updateDriverDto.email });
          if (updateDriverDto.licenseNumber)
            orConditions.push({ licenseNumber: updateDriverDto.licenseNumber });

          const existingDuplicate = await tx.driver.findFirst({
            where: {
              companyId,
              id: { not: id },
              OR: orConditions,
            },
          });

          if (existingDuplicate) {
            throw new ConflictException(
              'A driver with this email or license number already exists.',
            );
          }
        }

        const data: any = { ...updateDriverDto };
        if (data.licenseExpiry) {
          data.licenseExpiry = new Date(data.licenseExpiry);
        }

        const updatedDriver = await this.prisma.updateWithOcc<any>(
          tx,
          'driver',
          id,
          existingDriver.updatedAt,
          data,
        );

        // Rule Engine Integration
        const ruleResult = await this.workflow.evaluateRules(companyId, {
          entityType: 'DRIVER',
          trigger: 'DRIVER_UPDATED',
          entityData: updatedDriver,
        });

        if (
          ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')
        ) {
          throw new Error('Driver update rejected by business rules.');
        }

        // Audit Logging
        await this.auditService.logEvent(
          {
            companyId,
            entity: 'Driver',
            entityType: 'Driver',
            entityId: updatedDriver.id,
            action: 'UPDATE',
            beforeValue: { ...existingDriver },
            afterValue: { ...updatedDriver },
            source: 'API',
          },
          null,
          tx,
        );

        return updatedDriver;
      },
    );

    this.eventEmitter.emit('driver.updated', updatedDriver);

    return updatedDriver;
  }

  async remove(companyId: string, id: string) {
    const deletedDriver = await this.prisma.runAsTenant(
      companyId,
      async (tx) => {
        const existingDriver = await tx.driver.findFirst({
          where: { id },
        });
        if (!existingDriver) throw new NotFoundException();

        const deletedDriver = await tx.driver.update({
          where: { id },
          data: { deletedAt: new Date(), status: 'TERMINATED' },
        });

        await this.auditService.logEvent(
          {
            companyId,
            entity: 'Driver',
            entityType: 'Driver',
            entityId: deletedDriver.id,
            action: 'DELETE',
            details: { ...deletedDriver },
            source: 'API',
          },
          null,
          tx,
        );

        return deletedDriver;
      },
    );

    this.eventEmitter.emit('driver.deleted', deletedDriver);

    return deletedDriver;
  }
}

