import { SetMetadata } from '@nestjs/common';

export const ABAC_KEY = 'abac_attributes';
export const RequireAttributes = (attributes: Record<string, any>) =>
  SetMetadata(ABAC_KEY, attributes);

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ABAC_KEY } from './abac.decorator';
import { AuthenticatedUser } from '../../auth/decorators/get-user.decorator';
import { AuditService } from '../../platform/audit/audit.service';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class AbacGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly audit: AuditService,
    private readonly prisma: PrismaService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredAttributes = this.reflector.getAllAndOverride<
      Record<string, any>
    >(ABAC_KEY, [context.getHandler(), context.getClass()]);

    if (!requiredAttributes || Object.keys(requiredAttributes).length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user as AuthenticatedUser;

    if (!user) {
      throw new ForbiddenException('User is not authenticated');
    }

    if (user.roles?.includes('SUPER_ADMIN')) {
      return true;
    }

    // In a full implementation, you would fetch User properties, Company properties,
    // or even load attributes like load.value, load.region from the DB dynamically based on request params.
    // Here we do a simplified check against user's extended properties or company settings.

    // For demonstration, fetch user's company and check its region/department
    const company = await this.prisma.runAsSystem(async (tx) =>
      tx.company.findUnique({
        where: { id: user.companyId },
        include: { tenantConfiguration: true },
      }),
    );

    const userMetadata = {}; // Usually fetched from user profile/attributes
    const companyMetadata =
      (company?.tenantConfiguration?.settings as Record<string, any>) || {};

    let isAuthorized = true;
    const missingAttributes: Record<string, any> = {};

    for (const [key, expectedValue] of Object.entries(requiredAttributes)) {
      const actualValue =
        (userMetadata as Record<string, any>)[key] || companyMetadata[key];
      if (actualValue !== expectedValue) {
        isAuthorized = false;
        missingAttributes[key] = {
          expected: expectedValue,
          actual: actualValue,
        };
      }
    }

    if (!isAuthorized) {
      await this.audit.logEvent({
        companyId: user.companyId,
        userId: user.userId,
        entity: 'Attribute',
        entityId: context.getHandler().name,
        action: 'DENY',
        details: { requiredAttributes, missingAttributes },
        source: 'IAM',
      });
      throw new ForbiddenException(`ABAC Policy Denied: Mismatched attributes`);
    }

    return true;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import * as crypto from 'crypto';

@Injectable()
export class IntegrationAuthService {
  private readonly logger = new Logger(IntegrationAuthService.name);

  // In production, this MUST come from an environment variable (e.g. process.env.IPAAS_MASTER_KEY)
  // For V1 validation, we use a static 32-byte key
  private readonly ENCRYPTION_KEY = Buffer.from(
    '12345678901234567890123456789012',
  ); // 32 bytes
  private readonly ALGORITHM = 'aes-256-gcm';

  /**
   * Encrypts sensitive credentials before storing in the database
   */
  encryptCredentials(credentials: any): string {
    try {
      const iv = crypto.randomBytes(16);
      const cipher = crypto.createCipheriv(
        this.ALGORITHM,
        this.ENCRYPTION_KEY,
        iv,
      );

      let encrypted = cipher.update(JSON.stringify(credentials), 'utf8', 'hex');
      encrypted += cipher.final('hex');
      const authTag = cipher.getAuthTag().toString('hex');

      // Store IV and AuthTag alongside the encrypted payload
      return JSON.stringify({
        iv: iv.toString('hex'),
        content: encrypted,
        tag: authTag,
      });
    } catch (e: any) {
      this.logger.error(`Failed to encrypt credentials: ${e.message}`);
      throw new Error('Encryption failed');
    }
  }

  /**
   * Decrypts credentials retrieved from the database
   */
  decryptCredentials(encryptedPayloadString: string): any {
    try {
      const payload = JSON.parse(encryptedPayloadString);
      const decipher = crypto.createDecipheriv(
        this.ALGORITHM,
        this.ENCRYPTION_KEY,
        Buffer.from(payload.iv, 'hex'),
      );
      decipher.setAuthTag(Buffer.from(payload.tag, 'hex'));

      let decrypted = decipher.update(payload.content, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      return JSON.parse(decrypted);
    } catch (e: any) {
      this.logger.error(`Failed to decrypt credentials: ${e.message}`);
      throw new Error('Decryption failed');
    }
  }

  /**
   * Validates an HMAC signature for incoming webhooks
   */
  verifyWebhookSignature(
    payload: string,
    signature: string,
    secret: string,
  ): boolean {
    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    return signature === expectedSignature;
  }
}

