          snippet: `POST /v1/integration/sync/trigger HTTP/1.1\nHost: api.parilink.enterprise.io\nAuthorization: Bearer YOUR_API_KEY\nContent-Type: application/json\n\n{"connectionId":"conn_12345","entityType":"INVOICE"}`,
        };
