import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../../platform/events/event.service';

@Injectable()
export class GeofenceService {
  private readonly logger = new Logger(GeofenceService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  // Haversine distance formula
  private getDistance(
    lat1: number,
    lon1: number,
    lat2: number,
    lon2: number,
  ): number {
    const R = 6371e3; // metres
    const φ1 = (lat1 * Math.PI) / 180; // φ, λ in radians
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c; // in metres
  }

  @OnEvent('GpsPing.Received')
  async handleGpsPing(event: any) {
    const { tenantId, payload, timestamp } = event;
    const { vehicleId, latitude, longitude } = payload;

    // 1. Fetch active geofences for this company
    // Optimisation: In a real system, you'd use PostGIS or Redis geospatial indexing (GEORADIUS)
    // rather than loading all geofences, but for the MVP we will filter in memory.
    const geofences = await this.prisma.runAsSystem(async (tx) =>
      tx.geofence.findMany({
        where: { companyId: tenantId, isActive: true },
      }),
    );

    for (const geofence of geofences) {
      // 2. Calculate distance
      const distance = this.getDistance(
        latitude,
        longitude,
        geofence.latitude,
        geofence.longitude,
      );
      const isInsideNow = distance <= geofence.radiusMeters;

      // 3. Check previous state (did we already enter/exit?)
      const lastEvent = await this.prisma.runAsSystem(async (tx) =>
        tx.geofenceEvent.findFirst({
          where: { vehicleId, geofenceId: geofence.id },
          orderBy: { timestamp: 'desc' },
        }),
      );

      const wasInsideBefore = lastEvent?.eventType === 'ENTER';

      if (isInsideNow && !wasInsideBefore) {
        // Trigger ENTER event
        await this.prisma.runAsSystem(async (tx) =>
          tx.geofenceEvent.create({
            data: {
              companyId: tenantId,
              geofenceId: geofence.id,
              vehicleId,
              eventType: 'ENTER',
              timestamp: new Date(timestamp),
            },
          }),
        );

        this.eventService.publish('Geofence.Entered', {
          tenantId,
          userId: 'SYSTEM',
          correlationId: event.correlationId,
          payload: {
            vehicleId,
            geofenceId: geofence.id,
            geofenceName: geofence.name,
          },
          timestamp: new Date(timestamp),
        });

        this.logger.debug(
          `Vehicle ${vehicleId} ENTERED geofence ${geofence.name}`,
        );
      } else if (!isInsideNow && wasInsideBefore) {
        // Trigger EXIT event
        const dwellTimeMs =
          new Date(timestamp).getTime() -
          new Date(lastEvent.timestamp).getTime();

        await this.prisma.runAsSystem(async (tx) =>
          tx.geofenceEvent.create({
            data: {
              companyId: tenantId,
              geofenceId: geofence.id,
              vehicleId,
              eventType: 'EXIT',
              timestamp: new Date(timestamp),
              metadata: { dwellTimeMs },
            },
          }),
        );

        this.eventService.publish('Geofence.Exited', {
          tenantId,
          userId: 'SYSTEM',
          correlationId: event.correlationId,
          payload: {
            vehicleId,
            geofenceId: geofence.id,
            geofenceName: geofence.name,
            dwellTimeMs,
          },
          timestamp: new Date(timestamp),
        });

        this.logger.debug(
          `Vehicle ${vehicleId} EXITED geofence ${geofence.name} (Dwell: ${Math.round(dwellTimeMs / 60000)}m)`,
        );
      }
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class TimelineService {
  private readonly logger = new Logger(TimelineService.name);

  constructor(private readonly prisma: PrismaService) {}

  async addEvent(
    tripId: string,
    companyId: string,
    eventName: string,
    metadata: any = {},
  ) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId },
      }),
    );

    if (!trip || trip.companyId !== companyId) return;

    let timeline: any[] = [];
    if (trip.timeline && Array.isArray(trip.timeline)) {
      timeline = trip.timeline as any[];
    }

    timeline.push({
      event: eventName,
      timestamp: new Date().toISOString(),
      metadata,
    });

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.update({
        where: { id: tripId },
        data: { timeline },
      }),
    );

    this.logger.debug(`Timeline event ${eventName} added to trip ${tripId}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import type {
  StandardCloudEvent,
  PlatformEvent,
} from '../../platform/events/event.service';

@Injectable()
export class LinAnonymizationService {
  private readonly logger = new Logger(LinAnonymizationService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Listen to critical operational events and siphon them into the anonymized
   * Intelligence Network archive. In a true distributed system, this would listen
   * to a Kafka topic. Here we listen to the local event bus.
   */
  @OnEvent('trip.completed')
  async handleTripCompleted(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing trip.completed event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    // Strict Anonymization Map
    // Drops: tripNumber, driverId, vehicleId, precise locations
    // Keeps: duration, status, delays, fuel metrics (if any)
    const anonymizedPayload = {
      durationSeconds: payload.actualDurationSeconds || null,
      distanceMeters: payload.actualDistanceMeters || null,
      delayed: payload.status === 'DELAYED',
      region: this.generalizeLocation(payload.startLocation), // e.g. "US-West" instead of GPS
    };

    await this.archiveEvent('trip.completed', anonymizedPayload);
  }

  @OnEvent('BusinessHealth.Updated')
  async handleBusinessHealth(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing BusinessHealth.Updated event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    const anonymizedPayload = {
      operationalScore: payload.operationalScore,
      financialScore: payload.financialScore,
      timestamp: payload.timestamp,
    };

    await this.archiveEvent('business_health.updated', anonymizedPayload);
  }

  @OnEvent('anomaly.resolved')
  async handleAnomalyResolved(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing anomaly.resolved event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    const anonymizedPayload = {
      anomalyType: payload.type,
      resolutionTimeSeconds: payload.resolutionTimeSeconds,
      aiRecommendationUsed: payload.aiRecommendationUsed || false,
    };

    await this.archiveEvent('anomaly.resolved', anonymizedPayload);
  }

  private async archiveEvent(eventType: string, anonymizedPayload: any) {
    try {
      await this.prisma.runAsSystem(async (tx) =>
        tx.linEventArchive.create({
          data: {
            eventType,
            anonymizedPayload,
          },
        }),
      );
      this.logger.debug(
        `[LIN] Successfully archived anonymized event: ${eventType}`,
      );
    } catch (error) {
      this.logger.error(`[LIN] Failed to archive event: ${error.message}`);
    }
  }

  private generalizeLocation(location: any): string {
    // Stub implementation to generalize GPS into large geographic buckets
    return 'US-West';
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class LinBenchmarkEngine {
  private readonly logger = new Logger(LinBenchmarkEngine.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Periodically computes network-wide benchmarks from the anonymized event archive.
   * In a real system, this would be an offline batch job (e.g. Apache Spark) syncing
   * results back to the transactional database.
   */
  @Cron(CronExpression.EVERY_HOUR)
  async computeNetworkBenchmarks() {
    this.logger.log(`[LIN] Starting Network Benchmark computation...`);

    // 1. Compute AI Approval Rate Benchmark
    await this.computeAiApprovalRate();

    // 2. Compute Average Operational Health
    await this.computeAverageHealthScore();

    this.logger.log(`[LIN] Network Benchmark computation completed.`);
  }

  private async computeAiApprovalRate() {
    const events = await this.prisma.runAsSystem(async (tx) =>
      tx.linEventArchive.findMany({
        where: { eventType: 'anomaly.resolved' },
      }),
    );

    if (events.length === 0) return;

    const approvedCount = events.filter(
      (e: any) => e.anonymizedPayload.aiRecommendationUsed,
    ).length;
    const approvalRate = (approvedCount / events.length) * 100;

    await this.upsertBenchmark(
      'ai_approval_rate_avg',
      approvalRate,
      0.9,
      events.length,
    );
  }

  private async computeAverageHealthScore() {
    const events = await this.prisma.runAsSystem(async (tx) =>
      tx.linEventArchive.findMany({
        where: { eventType: 'business_health.updated' },
        orderBy: { timestamp: 'desc' },
        take: 1000, // Sample size of recent pulses across the network
      }),
    );

    if (events.length === 0) return;

    const sum = events.reduce(
      (acc, e: any) => acc + (e.anonymizedPayload.operationalScore || 0),
      0,
    );
    const avgScore = sum / events.length;

    await this.upsertBenchmark(
      'operational_health_avg',
      avgScore,
      0.85,
      events.length,
    );
  }

  private async upsertBenchmark(
    metricName: string,
    value: number,
    confidenceScore: number,
    sampleSize: number,
  ) {
    await this.prisma.runAsSystem(async (tx) =>
      tx.linBenchmark.upsert({
        where: { metricName },
        update: {
          value,
          confidenceScore,
          sampleSize,
        },
        create: {
          metricName,
          value,
          confidenceScore,
          sampleSize,
        },
      }),
    );
    this.logger.debug(
      `[LIN] Updated benchmark ${metricName} = ${value.toFixed(2)}`,
    );
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';

export interface DigitalTwinRule {
  id: string;
  condition: (twinState: any) => boolean;
  action: (twinId: string, state: any) => void;
}

@Injectable()
export class RuleEngineService {
  private readonly logger = new Logger(RuleEngineService.name);
  private rules: DigitalTwinRule[] = [];

  constructor(private readonly prisma: PrismaService) {
    this.registerDefaultRules();
  }

  private registerDefaultRules() {
    // Example declarative rule reacting to twin state
    this.rules.push({
      id: 'maintenance-overdue',
      condition: (state: any) =>
        state.odometer > 100000 && !state.maintenanceRequested,
      action: (twinId, state) => {
        this.logger.warn(
          `Twin [${twinId}]: Maintenance Overdue! (Odometer: ${state.odometer})`,
        );
        // Emit Alert or create MaintenanceJob via EventStore
      },
    });
  }

  @OnEvent('DomainEvent.*.*')
  async evaluateRules(event: any) {
    const { tenantId, payload } = event;
    const { streamId } = payload;

    // In a pure Event Sourced system, we fetch the latest snapshot
    const snapshot = await this.prisma.runAsSystem(async (tx) =>
      tx.twinSnapshot.findFirst({
        where: { companyId: tenantId, twinId: streamId },
      }),
    );

    if (!snapshot) return;

    for (const rule of this.rules) {
      if (rule.condition(snapshot.state)) {
        rule.action(streamId, snapshot.state);
      }
    }
  }
}

