import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class InvoicesService {
  constructor(private prisma: PrismaService) {}

  async getInvoices(
    companyId: string,
    page = 1,
    limit = 50,
    sort = 'createdAt',
    order: 'asc' | 'desc' = 'desc',
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const skip = (page - 1) * limit;
      const where = { companyId };

      const [data, total] = await Promise.all([
        tx.invoice.findMany({
          where,
          orderBy: { [sort]: order },
          skip,
          take: limit,
          include: {
            customer: { select: { id: true, name: true } },
            load: { select: { id: true, referenceNumber: true } },
          },
        }),
        tx.invoice.count({ where }),
      ]);

      return {
        data,
        total,
        meta: {
          total,
          page,
          limit,
          lastPage: Math.ceil(total / limit) || 1,
        },
      };
    });
  }

  async getInvoiceById(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const invoice = await tx.invoice.findFirst({
        where: { id, companyId },
        include: {
          customer: true,
          load: true,
          lineItems: true,
        },
      });
      if (!invoice) throw new NotFoundException('Invoice not found');
      return invoice;
    });
  }

  async createInvoice(companyId: string, payload: any) {
    const {
      customerId,
      loadId,
      invoiceNumber,
      amount,
      dueDate,
      notes,
      lineItems,
    } = payload;

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const invoice = await tx.invoice.create({
        data: {
          companyId,
          customerId,
          loadId,
          invoiceNumber,
          amount,
          dueDate: dueDate ? new Date(dueDate) : null,
          notes,
          status: 'DRAFT',
        },
      });

      if (lineItems && lineItems.length > 0) {
        await tx.invoiceLineItem.createMany({
          data: lineItems.map((item: any) => ({
            invoiceId: invoice.id,
            description: item.description,
            quantity: item.quantity || 1,
            unitPrice: item.unitPrice,
            amount: (item.quantity || 1) * item.unitPrice,
            type: item.type || 'LINE_HAUL',
          })),
        });
      }

      return tx.invoice.findUnique({
        where: { id: invoice.id },
        include: { lineItems: true },
      });
    });
  }

  async updateInvoiceStatus(companyId: string, id: string, status: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Verify invoice belongs to this company before updating (prevents IDOR)
      const existing = await tx.invoice.findFirst({
        where: { id, companyId },
      });
      if (!existing) throw new NotFoundException('Invoice not found');

      return tx.invoice.update({
        where: { id },
        data: { status },
      });
    });
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class LedgerService {
  constructor(private prisma: PrismaService) {}

  async getChartOfAccounts(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.account.findMany({ orderBy: { code: 'asc' } });
    });
  }

  async getTrialBalance(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const accounts = await tx.account.findMany({ orderBy: { code: 'asc' } });

      const aggregations = await tx.journalLine.groupBy({
        by: ['accountId'],
        _sum: { debit: true, credit: true },
        where: { entry: { status: 'POSTED' } },
      });

      const aggMap = new Map(aggregations.map((a) => [a.accountId, a]));

      return accounts.map((account) => {
        const agg = aggMap.get(account.id);
        const totalDebit = agg?._sum?.debit || 0;
        const totalCredit = agg?._sum?.credit || 0;

        let balance = 0;
        if (account.type === 'ASSET' || account.type === 'EXPENSE') {
          balance = totalDebit - totalCredit;
        } else {
          balance = totalCredit - totalDebit;
        }

        return {
          accountId: account.id,
          code: account.code,
          name: account.name,
          type: account.type,
          totalDebit,
          totalCredit,
          balance,
        };
      });
    });
  }

  async getProfitAndLoss(
    companyId: string,
    startDate?: string,
    endDate?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const whereClause: any = { status: 'POSTED' };
      if (startDate || endDate) {
        whereClause.date = {};
        if (startDate) whereClause.date.gte = new Date(startDate);
        if (endDate) whereClause.date.lte = new Date(endDate);
      }

      const revAgg = await tx.journalLine.aggregate({
        _sum: { debit: true, credit: true },
        where: { account: { type: 'REVENUE' }, entry: whereClause },
      });

      const expAgg = await tx.journalLine.aggregate({
        _sum: { debit: true, credit: true },
        where: { account: { type: 'EXPENSE' }, entry: whereClause },
      });

      const totalRevenue = (revAgg._sum.credit || 0) - (revAgg._sum.debit || 0);
      const totalExpense = (expAgg._sum.debit || 0) - (expAgg._sum.credit || 0);

      return {
        totalRevenue,
        totalExpense,
        netIncome: totalRevenue - totalExpense,
      };
    });
  }
}

import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import {
  ConflictException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateLoadDto } from './dto/create-load.dto';
import { UpdateLoadDto } from './dto/update-load.dto';
import { LoadQueryDto } from './dto/load-query.dto';
import * as crypto from 'crypto';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class LoadsService {
  private readonly logger = new Logger(LoadsService.name);
  constructor(
    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
  ) {}

  async create(companyId: string, createLoadDto: CreateLoadDto) {
    const newLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const { customerId, ...restDto } = createLoadDto;
      const data: any = { ...restDto };

      if (data.pickupDate) data.pickupDate = new Date(data.pickupDate);
      if (data.deliveryDate) data.deliveryDate = new Date(data.deliveryDate);

      // Auto-generate referenceNumber if not provided
      if (!data.referenceNumber) {
        data.referenceNumber = `LD-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
      }

      const newLoad = await tx.load.create({
        data: {
          ...data,
          company: { connect: { id: companyId } },
          customer: { connect: { id: customerId } },
        },
        include: { customer: true },
      });

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'LOAD',
        trigger: 'LOAD_CREATED',
        entityData: newLoad,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new Error('Load creation rejected by business rules.');
      }

      return newLoad;
    });

    this.eventEmitter.emit('load.created', newLoad);

    return newLoad;
  }

  async findAll(companyId: string, query: LoadQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { page = 1, limit = 10, search, status, customerId } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.LoadWhereInput = { companyId };

      if (search) {
        where.OR = [
          { referenceNumber: { contains: search, mode: 'insensitive' } },
          { originCity: { contains: search, mode: 'insensitive' } },
          { destinationCity: { contains: search, mode: 'insensitive' } },
          { customer: { name: { contains: search, mode: 'insensitive' } } },
        ];
      }

      if (status) {
        where.status = status;
      }

      if (customerId) {
        where.customerId = customerId;
      }

      this.logger.debug(
        `findMany args: page=${page} limit=${limit} status=${status ?? 'all'} customerId=${customerId ?? 'all'}`,
      );
      const [data, total] = await Promise.all([
        tx.load.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: { customer: true },
        }),
        tx.load.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const load = await tx.load.findFirst({
        where: { id, companyId },
        include: { customer: true, documents: true, invoices: true },
      });

      if (!load) {
        throw new NotFoundException(`Load with ID ${id} not found`);
      }
      return load;
    });
  }

  async update(companyId: string, id: string, updateLoadDto: UpdateLoadDto) {
    const updatedLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id, companyId },
      });
      if (!existingLoad) throw new NotFoundException();

      const { driverId, vehicleId, ...restData } = updateLoadDto;
      const data: any = { ...restData };
      if (data.pickupDate) data.pickupDate = new Date(data.pickupDate);
      if (data.deliveryDate) data.deliveryDate = new Date(data.deliveryDate);

      // Create a trip if driver and vehicle are assigned and we don't already have one
      if (
        driverId &&
        vehicleId &&
        data.status === 'ASSIGNED' &&
        !existingLoad.tripId
      ) {
        const trip = await tx.trip.create({
          data: {
            companyId,
            tripNumber: `TRP-${crypto.randomBytes(4).toString('hex').toUpperCase()}`,
            driverId,
            vehicleId,
            status: 'DISPATCHED',
          },
        });
        data.tripId = trip.id;
      }

      this.logger.debug(
        `Updating load ${id} with status=${updateLoadDto.status ?? 'unchanged'}`,
      );

      const updatedLoad = await this.prisma.updateWithOcc<any>(
        tx,
        'load',
        id,
        existingLoad.updatedAt,
        data,
        { customer: true },
      );

      this.logger.debug(`Load ${id} updated successfully`);

      // Auto-generate invoice when status becomes DELIVERED
      if (updateLoadDto.status === 'DELIVERED') {
        const existingInvoice = await tx.invoice.findFirst({
          where: { loadId: id },
        });
        if (!existingInvoice) {
          const refPart = updatedLoad.referenceNumber
            ? updatedLoad.referenceNumber.split('-').pop()
            : crypto.randomBytes(4).toString('hex').toUpperCase();
          await tx.invoice.create({
            data: {
              companyId,
              customerId: updatedLoad.customerId,
              loadId: updatedLoad.id,
              invoiceNumber: `INV-${refPart}`,
              status: 'DRAFT',
              amount: updatedLoad.rate || 1500,
              dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
            },
          });
        }
      }

      return updatedLoad;
    });

    this.eventEmitter.emit('load.updated', updatedLoad);

    return updatedLoad;
  }

  async remove(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id, companyId },
      });
      if (!existingLoad) throw new NotFoundException();

      return tx.load.update({
        where: { id },
        data: { deletedAt: new Date(), status: 'CANCELLED' },
      });
    });
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
