/** Retention policies per entity type (days). 0 = indefinite. */
export const RETENTION_POLICIES: Record<string, number> = {
  auditLog: 2555, // 7 years — regulatory requirement
  platformMetric: 90, // 90 days
  vehicleLocation: 365, // 1 year
  domainEvent: 365,
  aiInteractionLog: 180,
  webhookDelivery: 30,
  syncJob: 30,
};

@Injectable()
export class DataGovernanceService {
  private readonly logger = new Logger(DataGovernanceService.name);

  private readonly fieldRegistry = new Map<string, FieldClassification>(
    SENSITIVE_FIELD_REGISTRY.map((f) => [f.field, f]),
  );

  /** Classify a field name and return its governance metadata. */
  classify(fieldName: string): FieldClassification | undefined {
    return this.fieldRegistry.get(fieldName);
  }

  /**
   * Mask PII and financial fields in an object for API responses.
   * Call this before returning data to low-privilege callers.
   * Pass `privileged=true` to skip masking (e.g., for admin dashboards).
   */
  maskForResponse<T extends Record<string, unknown>>(
    data: T,
    privileged = false,
  ): T {
    if (privileged) return data;
    const result = (Array.isArray(data) ? [] : {}) as Record<string, unknown>;

    for (const [key, value] of Object.entries(data)) {
      const classification = this.fieldRegistry.get(key);
      if (classification?.maskPattern) {
        result[key] = this.applyMask(
          String(value ?? ''),
          classification.maskPattern,
        );
      } else if (Array.isArray(value)) {
        result[key] = value.map((item) =>
          typeof item === 'object' && item !== null
            ? this.maskForResponse(item as Record<string, unknown>, privileged)
            : item,
        );
      } else if (value && typeof value === 'object') {
        result[key] = this.maskForResponse(
          value as Record<string, unknown>,
          privileged,
        );
      } else {
        result[key] = value;
      }
    }

    return result as unknown as T;
  }

  /** Returns the retention policy (days) for an entity type. */
  getRetentionDays(entityType: string): number {
    return RETENTION_POLICIES[entityType] ?? 0;
  }

  /** Returns all PII fields registered in the platform (for DPDP erasure processing). */
  getPiiFields(): string[] {
    return SENSITIVE_FIELD_REGISTRY.filter((f) => f.pii).map((f) => f.field);
  }

  /** Annotates a data record with data lineage metadata. */
  annotateLineage(
    data: Record<string, unknown>,
    source: string,
    tenantId: string,
  ): Record<string, unknown> {
    return {
      ...data,
      _lineage: {
        source,
        tenantId,
        ingestedAt: new Date().toISOString(),
        classification: 'INTERNAL',
      },
    };
  }

  // ─────────────────────────────────────────────────────────────────────────
  private applyMask(
    value: string,
    pattern: FieldClassification['maskPattern'],
  ): string {
    if (!value) return value;
    switch (pattern) {
      case 'email': {
        const [name, domain] = value.split('@');
        if (!domain) return '***';
        return `${name.charAt(0)}***@${domain}`;
      }
      case 'phone': {
        return value.replace(/\d(?=\d{4})/g, '*');
      }
      case 'aadhaar': {
        return `****-****-${value.slice(-4)}`;
      }
      case 'pan': {
        return `${value.slice(0, 2)}***${value.slice(-2)}`;
      }
      case 'partial': {
        if (value.length <= 4) return '****';
        return `${value.slice(0, 2)}${'*'.repeat(value.length - 4)}${value.slice(-2)}`;
      }
      default:
        return '***';
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { RawTelemetryEvent } from './quality-engine.service';
import { PrismaService } from '../../../prisma/prisma.service';
import { EventService } from '../../events/event.service';

interface ProviderConfidence {
  provider: string;
  baseConfidence: number; // 0-100
}

const PROVIDER_CONFIDENCE_SCORES: ProviderConfidence[] = [
  { provider: 'FASTAG', baseConfidence: 99 }, // Ground truth toll crossing
  { provider: 'TATA_FLEET_EDGE', baseConfidence: 95 }, // OEM Deep CAN Bus
  { provider: 'SAMSARA', baseConfidence: 85 }, // Premium Telematics
  { provider: 'LOCONAV', baseConfidence: 75 }, // Standard Telematics
];

@Injectable()
export class FusionEngineService {
  private readonly logger = new Logger(FusionEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  private getProviderConfidence(provider: string): number {
    const p = PROVIDER_CONFIDENCE_SCORES.find((c) => c.provider === provider);
    return p ? p.baseConfidence : 50; // Unknown provider gets 50
  }

  async processTelemetry(
    event: RawTelemetryEvent,
    qualityScore: number,
  ): Promise<void> {
    if (!event.vehicleId) {
      this.logger.warn(
        `Cannot fuse telemetry without a resolved vehicleId for providerVehicleId: ${event.providerVehicleId}`,
      );
      return;
    }

    const providerConfidence = this.getProviderConfidence(event.provider);
    const fusionScore = providerConfidence * 0.7 + qualityScore * 0.3; // Weighted confidence

    // Save the raw location data for historical mapping
    if (event.latitude !== undefined && event.longitude !== undefined) {
      await this.prisma.runAsSystem(async (tx) =>
        tx.vehicleLocation.create({
          data: {
            companyId: event.tenantId,
            provider: event.provider,
            providerVehicleId: event.providerVehicleId,
            vehicleId: event.vehicleId,
            latitude: event.latitude as number,
            longitude: event.longitude as number,
            speed: event.speed,
            heading: event.heading,
            ignition: event.ignition,
            fuel: event.fuelLevel,
            odometer: event.odometer,
            gpsTimestamp: event.timestamp,
          },
        }),
      );
    }

    // Now, retrieve the current Digital Twin snapshot for this vehicle
    const twin = await this.prisma.runAsSystem(async (tx) =>
      tx.twinSnapshot.findUnique({
        where: {
          twinId_twinType: {
            twinId: event.vehicleId as string,
            twinType: 'VEHICLE',
          },
        },
      }),
    );

    const currentState = twin ? (twin.state as any) : {};

    // FUSION LOGIC: Should we overwrite the twin's state?
    // E.g. If current state was set by an OEM (Confidence 95), do not overwrite with LOCONAV (Confidence 75) unless
    // the OEM data is very old. For simplicity in this iteration, we merge the latest event, but track confidence.

    const newState = {
      ...currentState,
      lastProvider: event.provider,
      lastFusionScore: fusionScore,
      lastUpdateAt: new Date().toISOString(),
    };

    if (event.latitude !== undefined) newState.latitude = event.latitude;
    if (event.longitude !== undefined) newState.longitude = event.longitude;
    if (event.speed !== undefined) newState.speed = event.speed;
    if (event.odometer !== undefined) newState.odometer = event.odometer;
    if (event.fuelLevel !== undefined) newState.fuelLevel = event.fuelLevel;
    if (event.ignition !== undefined) newState.ignition = event.ignition;

    const nextVersion = twin ? twin.version + 1 : 1;

    // Update the Digital Twin in the Database
    await this.prisma.runAsSystem(async (tx) =>
      tx.twinSnapshot.upsert({
        where: {
          twinId_twinType: {
            twinId: event.vehicleId as string,
            twinType: 'VEHICLE',
          },
        },
        create: {
          companyId: event.tenantId,
          twinId: event.vehicleId as string,
          twinType: 'VEHICLE',
          version: nextVersion,
          state: newState,
        },
        update: {
          version: nextVersion,
          state: newState,
          timestamp: new Date(),
        },
      }),
    );

    // Emit the Digital Twin State Change Event so other modules (Dispatch, AI) can react instantly
    this.eventService.publish('DomainEvent.VEHICLE.TwinUpdated', {
      tenantId: event.tenantId,
      correlationId: `fusion-${event.provider}-${Date.now()}`,
      payload: {
        streamId: event.vehicleId,
        version: nextVersion,
        data: newState,
      },
    });

    this.logger.debug(
      `VehicleTwin [${event.vehicleId}] updated by FusionEngine (Score: ${fusionScore.toFixed(2)})`,
    );
  }
}

import { Injectable, Logger, ConflictException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../events/event.service';

export interface AppendEventParams {
  tenantId: string;
  streamId: string;
  streamType: string;
  eventType: string;
  payload: any;
  expectedVersion?: number;
  userId?: string;
  correlationId?: string;
}

@Injectable()
export class EventStoreService {
  private readonly logger = new Logger(EventStoreService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  async append(params: AppendEventParams): Promise<void> {
    const {
      tenantId,
      streamId,
      streamType,
      eventType,
      payload,
      expectedVersion,
      userId,
      correlationId,
    } = params;

    return await this.prisma.$transaction(async (tx) => {
      // 1. Get current version of the stream
      const lastEvent = await tx.domainEvent.findFirst({
        where: { streamId, companyId: tenantId },
        orderBy: { version: 'desc' },
      });

      const currentVersion = lastEvent?.version || 0;
      const nextVersion = currentVersion + 1;

      // 2. Optimistic Concurrency Control
      if (expectedVersion !== undefined && expectedVersion !== currentVersion) {
        throw new ConflictException(
          `Concurrency conflict: Expected version ${expectedVersion}, got ${currentVersion}`,
        );
      }

      // 3. Append the new event
      const newEvent = await tx.domainEvent.create({
        data: {
          companyId: tenantId,
          streamId,
          streamType,
          eventType,
          version: nextVersion,
          payload,
          userId: userId || 'SYSTEM',
          correlationId,
        },
      });

      this.logger.debug(
        `Appended [${eventType}] to ${streamType}:${streamId} @ v${nextVersion}`,
      );

      // 4. Publish to Memory Bus for Live Projections to pick up
      this.eventService.publish(`DomainEvent.${streamType}.${eventType}`, {
        tenantId,
        correlationId: correlationId || `event-${newEvent.id}`,
        timestamp: newEvent.timestamp,
        payload: {
          streamId,
          version: nextVersion,
          data: payload,
          metadata: {
            eventId: newEvent.id,
            timestamp: newEvent.timestamp,
          },
        },
      });
    });
  }

  async getStream(tenantId: string, streamId: string, fromVersion = 0) {
    return await this.prisma.runAsSystem(async (tx) =>
      tx.domainEvent.findMany({
        where: { companyId: tenantId, streamId, version: { gt: fromVersion } },
        orderBy: { version: 'asc' },
      }),
    );
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EnterpriseGraphService } from '../graph/enterprise-graph.service';
import {
  PredictionEngine,
  PredictionResult,
} from '../prediction/prediction.engine';

export interface SimulationParameters {
  scenario: string;
  mutations: Array<{ targetId: string; mutation: any }>;
}

export interface SimulationResult {
  scenario: string;
  baselineHealth: number;
  simulatedHealth: number;
  impactedNodes: string[];
  predictions: Record<string, PredictionResult>;
}

@Injectable()
export class SimulationEngine {
  private readonly logger = new Logger(SimulationEngine.name);

  constructor(
    private readonly graphService: EnterpriseGraphService,
    private readonly predictionEngine: PredictionEngine,
  ) {}

  /**
   * Run simulations without modifying production data.
   * Clones a TwinSnapshot into memory, applies mutations (e.g., "Fuel increases 15%"),
   * runs the prediction heuristics, and returns the diff.
   */
  async runSimulation(
    companyId: string,
    parameters: SimulationParameters,
  ): Promise<SimulationResult> {
    this.logger.log(`[Simulation] Running scenario: ${parameters.scenario}`);

    // In a full implementation, we would recursively clone the graph context for all mutated targets.
    // For MVP, we simulate the outcome based on the prediction engine.

    const predictions: Record<string, PredictionResult> = {};
    const impactedNodes: string[] = [];
    let cumulativeRiskDelta = 0;

    for (const mutation of parameters.mutations) {
      this.logger.debug(
        `[Simulation] Applying mutation to ${mutation.targetId}`,
      );
      impactedNodes.push(mutation.targetId);

      // Simulate getting a baseline prediction vs mutated prediction
      const baseline = await this.predictionEngine.predictState(
        companyId,
        mutation.targetId,
      );

      // Mocking the mutation effect: artificially inflate risk for the simulation
      const simulatedRisk = Math.min(baseline.riskScore + 25, 100);
      cumulativeRiskDelta += simulatedRisk - baseline.riskScore;

      predictions[mutation.targetId] = {
        ...baseline,
        riskScore: simulatedRisk,
        predictedFutureState: {
          ...baseline.predictedFutureState,
          ...mutation.mutation,
        },
        recommendations: [
          ...baseline.recommendations,
          `Simulation Alert: Mutation caused a ${simulatedRisk - baseline.riskScore} point risk increase.`,
        ],
      };
    }

    // Business Health is generally inverse to aggregate risk
    const baselineHealth = 95; // Mock baseline
    const simulatedHealth = Math.max(
      baselineHealth -
        cumulativeRiskDelta / Math.max(parameters.mutations.length, 1),
      0,
    );

    return {
      scenario: parameters.scenario,
      baselineHealth,
      simulatedHealth,
      impactedNodes,
      predictions,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import * as crypto from 'crypto';
import * as fs from 'fs';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../events/event.service';

export interface PlatformFileUpload {
  companyId: string;
  userId: string;
  file: Express.Multer.File;
  category?: string;
  metadata?: Record<string, any>;
  referenceId?: string;
}

@Injectable()
export class FilePlatformService {
  private readonly logger = new Logger(FilePlatformService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  async processUpload(upload: PlatformFileUpload) {
    this.logger.debug(
      `[FilePlatform] Processing upload for company ${upload.companyId}`,
    );

    // Compute checksum for deduplication and integrity
    const fileBuffer = fs.readFileSync(upload.file.path);
    const checksum = crypto
      .createHash('sha256')
      .update(fileBuffer)
      .digest('hex');

    // Here we can hook in ClamAV virus scanning, Image optimization (sharp), etc.

    const document = await this.prisma.runAsSystem(async (tx) =>
      tx.document.create({
        data: {
          companyId: upload.companyId,
          uploadedById: upload.userId,
          fileUrl: upload.file.path, // Abstraction ready for S3
          fileName: upload.file.originalname,
          mimeType: upload.file.mimetype,
          sizeBytes: upload.file.size,
          type: upload.category || 'GENERAL',
          loadId: upload.referenceId, // If it maps to a load
          metadata: {
            ...upload.metadata,
            checksum,
          },
        },
      }),
    );

    this.eventService.publish('DocumentUploaded', {
      tenantId: upload.companyId,
      userId: upload.userId,
      correlationId: crypto.randomUUID(),
      payload: { documentId: document.id, checksum },
      timestamp: new Date(),
    });

    return document;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

// ---------------------------------------------------------------------------
// PariLink IAM Policy Engine (Ultimate Enterprise Grade)
//
// Implements a layered authorization model:
//   Layer 1 — RBAC: Role → Permission Strings (e.g. 'invoices:read')
//   Layer 2 — ABAC: Contextual attribute checks (ownership, branch, region, cost-center)
//   Layer 3 — Row-Level Security: Automatic companyId enforcement on all
//             data access (tenant isolation guarantee)
//
// Permission Format:
//   JSON Array of conditions. Example:
//   [
//      "invoices:read",
//      {"resource": "invoice", "action": "approve", "conditions": {"branchId": "$user.branchId", "maxAmount": 50000}}
//   ]
// ---------------------------------------------------------------------------

export interface PolicyContext {
  userId: string;
  companyId: string;
  roleId?: string | null;
  resource: string;
  action: string;

  // ABAC Context Variables
  resourceOwnerId?: string;
  resourceCompanyId?: string;
  resourceBranchId?: string;
  resourceRegion?: string;
  resourceCostCenterId?: string;

  // Optional metadata to evaluate against conditions
  metadata?: Record<string, any>;
}

export interface PolicyDecision {
  granted: boolean;
  reason: string;
}

interface CachedPermissions {
  permissions: any[]; // Now supports JSON objects for ABAC
  expiry: number;
}

@Injectable()
export class IamPolicyEngineService {
  private readonly logger = new Logger(IamPolicyEngineService.name);
  private readonly cache = new Map<string, CachedPermissions>();
  private readonly CACHE_TTL_MS = 60_000; // 60 seconds

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Primary authorization check.
   */
  async authorize(ctx: PolicyContext): Promise<PolicyDecision> {
    // Layer 3: Row-Level Security — ALWAYS enforce tenant isolation first
    if (ctx.resourceCompanyId && ctx.resourceCompanyId !== ctx.companyId) {
      this.logger.warn(
        `[IAM] Cross-tenant access denied: user from tenant ${ctx.companyId} attempted ` +
          `to access resource owned by ${ctx.resourceCompanyId}`,
      );
      return { granted: false, reason: 'CROSS_TENANT_ACCESS_DENIED' };
    }

    if (!ctx.roleId) {
      return { granted: false, reason: 'NO_ROLE_ASSIGNED' };
    }

    const permissions = await this.loadPermissions(ctx.roleId, ctx.companyId);

    // Super-admin bypass
    if (permissions.includes('*')) {
      return { granted: true, reason: 'SUPER_ADMIN' };
    }

    const requiredPermission = `${ctx.resource}:${ctx.action}`;
    const wildcardPermission = `${ctx.resource}:*`;

    // Flatten simple string permissions for Layer 1 Check
    const stringPerms = permissions.filter((p) => typeof p === 'string');
    const hasRbac =
      stringPerms.includes(requiredPermission) ||
      stringPerms.includes(wildcardPermission);

    // Layer 2: ABAC Evaluation
    // Find any JSON rule that applies to this resource and action
    const abacRules = permissions.filter(
      (p) =>
        typeof p === 'object' &&
        p.resource === ctx.resource &&
        (p.action === ctx.action || p.action === '*'),
    );

    let hasAbac = false;
    let failedAbacReason = '';

    if (abacRules.length > 0) {
      // User must satisfy AT LEAST ONE applicable ABAC rule
      const user = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.findUnique({
          where: { id: ctx.userId },
          select: { branchId: true, region: true, costCenterId: true },
        }),
      );

      for (const rule of abacRules) {
        let ruleSatisfied = true;
        const conditions = rule.conditions || {};

        if (
          conditions.branchId === '$user.branchId' &&
          ctx.resourceBranchId !== user?.branchId
        ) {
          ruleSatisfied = false;
          failedAbacReason = 'BRANCH_ISOLATION_VIOLATION';
        }
        if (
          conditions.region === '$user.region' &&
          ctx.resourceRegion !== user?.region
        ) {
          ruleSatisfied = false;
          failedAbacReason = 'REGION_ISOLATION_VIOLATION';
        }
        if (
          conditions.costCenterId === '$user.costCenterId' &&
          ctx.resourceCostCenterId !== user?.costCenterId
        ) {
          ruleSatisfied = false;
          failedAbacReason = 'COST_CENTER_ISOLATION_VIOLATION';
        }

        if (ruleSatisfied) {
          hasAbac = true;
          break;
        }
      }
    } else {
      // If no ABAC rules specifically constrain this, fallback to RBAC
      hasAbac = hasRbac;
    }

    if (!hasAbac && !hasRbac) {
      return {
        granted: false,
        reason: failedAbacReason || `MISSING_PERMISSION:${requiredPermission}`,
      };
    }

    // Default Ownership Check (Implicit ABAC constraint)
    if (ctx.resourceOwnerId && ctx.resourceOwnerId !== ctx.userId) {
      const canAccessOthers = stringPerms.includes(`${ctx.resource}:read:any`);
      if (!canAccessOthers && !hasAbac) {
        // Allow explicit ABAC to override ownership
        return { granted: false, reason: 'OWNERSHIP_VIOLATION' };
      }
    }

    return { granted: true, reason: 'ABAC_RBAC_GRANTED' };
  }

  async hasPermission(
    roleId: string,
    companyId: string,
    permission: string,
  ): Promise<boolean> {
    const permissions = await this.loadPermissions(roleId, companyId);
    const stringPerms = permissions.filter((p) => typeof p === 'string');
    const [resource] = permission.split(':');
    return (
      stringPerms.includes(permission) ||
      stringPerms.includes(`${resource}:*`) ||
      stringPerms.includes('*')
    );
  }

  invalidateRoleCache(roleId: string): void {
    this.cache.delete(roleId);
    this.logger.debug(`[IAM] Cache invalidated for role ${roleId}`);
  }

  private async loadPermissions(
    roleId: string,
    companyId: string,
  ): Promise<any[]> {
    const cacheKey = `${companyId}:${roleId}`;
    const cached = this.cache.get(cacheKey);

    if (cached && cached.expiry > Date.now()) {
      return cached.permissions;
    }

    const role = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.role.findUnique({
        where: { id: roleId },
        select: { permissions: true },
      }),
    );

    if (!role) return [];

    const permissions = Array.isArray(role.permissions) ? role.permissions : [];
    this.cache.set(cacheKey, {
      permissions,
      expiry: Date.now() + this.CACHE_TTL_MS,
    });

    return permissions;
  }
}

