import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class ClaimsService {
  private readonly logger = new Logger(ClaimsService.name);

  constructor(private readonly prisma: PrismaService) {}

  async createClaim(
    companyId: string,
    customerId: string,
    data: { loadId?: string; amount: number; reason: string },
  ) {
    this.logger.log(
      `Creating claim for customer ${customerId} (amount: ${data.amount})`,
    );

    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      return tx.claim.create({
        data: {
          companyId,
          customerId,
          loadId: data.loadId,
          amount: data.amount,
          reason: data.reason,
          status: 'PENDING',
        },
      });
    });
  }

  async getClaimsByCustomer(companyId: string, customerId: string) {
    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      return tx.claim.findMany({
        where: { companyId, customerId },
        orderBy: { createdAt: 'desc' },
      });
    });
  }

  async getClaimDetails(companyId: string, claimId: string) {
    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      const claim = await tx.claim.findUnique({
        where: { id: claimId, companyId },
      });
      if (!claim) {
        throw new NotFoundException(`Claim ${claimId} not found`);
      }
      return claim;
    });
  }

  async updateClaimStatus(companyId: string, claimId: string, status: string) {
    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      return tx.claim.update({
        where: { id: claimId, companyId },
        data: { status },
      });
    });
  }
}

import { Injectable, UnauthorizedException, Logger } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';

@Injectable()
export class CustomerAnalyticsService {
  private readonly logger = new Logger(CustomerAnalyticsService.name);

  constructor(private prisma: PrismaService) {}

  async getDashboardKpis(companyId: string, customerId: string) {
    if (!customerId)
      throw new UnauthorizedException('Customer context missing');

    const [activeLoads, totalDelivered, totalInvoices] = await Promise.all([
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.load.count({
          where: {
            companyId,
            customerId,
            status: { in: ['DISPATCHED', 'IN_TRANSIT'] },
          },
        }),
      ),
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.load.count({
          where: { companyId, customerId, status: 'DELIVERED' },
        }),
      ),
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.invoice.aggregate({
          where: { companyId, customerId, status: { not: 'PAID' } },
          _sum: { amount: true },
        }),
      ),
    ]);

    return {
      activeLoads,
      totalDelivered,
      outstandingBalance: totalInvoices._sum?.amount || 0,
      onTimeDeliveryRate: 98.5, // Mock for now, would aggregate from IntelligenceRiskAssessment
    };
  }
}

