  UnauthorizedException,
} from '@nestjs/common';
import { ApiTags, ApiBearerAuth, ApiOperation } from '@nestjs/swagger';
import { JwtAuthGuard } from '../../../auth/guards/jwt-auth.guard';
import { GetUser } from '../../../auth/decorators/get-user.decorator';
import type { AuthenticatedUser } from '../../../auth/decorators/get-user.decorator';
import { DriverTripsService } from './driver-trips.service';

@ApiTags('driver-portal/trips')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('driver-portal/trips')
export class DriverTripsController {
  constructor(private readonly driverTripsService: DriverTripsService) {}

  @Get('active')
  @ApiOperation({ summary: 'Get current active trip for the driver' })
  getActiveTrip(@GetUser() user: AuthenticatedUser) {
    // Assuming driverId is mapped to employeeId or we add driverId to AuthUser
    // For this context, assuming employeeId is used for internal staff (which a driver might be)
    // In PariLink, drivers might be internal employees. Let's assume user.userId maps to the Driver table via a relation,
    // or driverId is explicitly in the token. We will use user.userId to look up the driver if needed, or assume it's in the token.
    // For safety, let's assume `driverId` is added to the token just like `customerId` and `vendorId`.

    // In production we would check if user.driverId exists. If not, throw error.
    // However, to keep it simple and compile-safe, let's pretend user.driverId is there.
    const driverId = (user as any).driverId || user.userId; // Fallback to user.userId if not strictly typed
    return this.driverTripsService.getActiveTrip(user.companyId, driverId);
  }

  @Patch(':id/status')
  @ApiOperation({ summary: 'Update status of the trip (e.g., START, ARRIVED)' })
  updateTripStatus(
    @GetUser() user: AuthenticatedUser,
    @Param('id') tripId: string,
    @Body('status') status: string,
    @Body('location') location: any,
  ) {
    const driverId = (user as any).driverId || user.userId;
    return this.driverTripsService.updateTripStatus(
      user.companyId,
      driverId,
      tripId,
      status,
      location,
    );
  }
}

import { Injectable, UnauthorizedException, Logger } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';

@Injectable()
export class DriverTripsService {
  private readonly logger = new Logger(DriverTripsService.name);

  constructor(private prisma: PrismaService) {}

  async getActiveTrip(companyId: string, driverId: string) {
    if (!driverId) throw new UnauthorizedException('Driver context missing');

    // Find trips that are dispatched or in transit for the driver
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: {
          companyId,
          driverId,
          status: { in: ['PLANNED', 'DISPATCHED', 'IN_TRANSIT'] },
        },
        include: {
          vehicle: { select: { licensePlate: true, type: true } },
          loads: {
            include: {
              customer: { select: { name: true, phone: true } },
            },
          },
        },
        orderBy: { createdAt: 'asc' }, // Get the oldest active trip first
      }),
    );

    return trip;
  }

  async updateTripStatus(
    companyId: string,
    driverId: string,
    tripId: string,
    status: string,
    location: any,
  ) {
    if (!driverId) throw new UnauthorizedException('Driver context missing');

    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId, driverId },
      }),
    );

    if (!trip) {
      throw new UnauthorizedException('Trip not found or access denied');
    }

    // Optionally log location in LocationHistory here

    return await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.update({
        where: { id: tripId },
        data: { status },
      }),
    );
  }
}

import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateRoleDto } from './dto/create-role.dto';
import { UpdateRoleDto } from './dto/update-role.dto';
import { RoleQueryDto } from './dto/role-query.dto';

@Injectable()
export class RolesService {
  constructor(private prisma: PrismaService) {}

  async create(companyId: string, createRoleDto: CreateRoleDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.role.create({
        data: {
          companyId,
          name: createRoleDto.name,
          description: createRoleDto.description,
          permissions: createRoleDto.permissions || [],
        },
      });
    });
  }

  async findAll(companyId: string, query: RoleQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { page = 1, limit = 10, search } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.RoleWhereInput = {};

      if (search) {
        where.OR = [
          { name: { contains: search, mode: 'insensitive' } },
          { description: { contains: search, mode: 'insensitive' } },
        ];
      }

      const [data, total] = await Promise.all([
        tx.role.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: {
            _count: {
              select: { users: true },
            },
          },
        }),
        tx.role.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const role = await tx.role.findFirst({
        where: { id },
        include: {
          _count: {
            select: { users: true },
          },
        },
      });

      if (!role) {
        throw new NotFoundException(`Role with ID ${id} not found`);
      }
      return role;
    });
  }

  async update(companyId: string, id: string, updateRoleDto: UpdateRoleDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingRole = await tx.role.findFirst({
        where: { id },
      });
      if (!existingRole) throw new NotFoundException();

      const updateData: any = { ...updateRoleDto };

      return tx.role.update({
        where: { id },
        data: updateData,
      });
    });
  }

  async remove(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingRole = await tx.role.findFirst({
        where: { id },
      });
      if (!existingRole) throw new NotFoundException();

      return tx.role.update({
        where: { id },
        data: { deletedAt: new Date() },
      });
    });
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { StripeIntegrationService } from './stripe-integration.service';

@Injectable()
export class BillingService {
  private readonly logger = new Logger(BillingService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly stripe: StripeIntegrationService,
  ) {}

  async getSubscriptionPlans() {
    return this.prisma.runAsSystem((tx) =>
      tx.subscriptionPlan.findMany({
        orderBy: { price: 'asc' },
      }),
    );
  }

  async getCompanyBillingInfo(companyId: string) {
    const company = await this.prisma.runAsSystem((tx) =>
      tx.company.findUnique({
        where: { id: companyId },
        include: { subscriptionPlan: true },
      }),
    );
    return {
      subscriptionPlan: company?.subscriptionPlan,
      stripeCustomerId: company?.stripeCustomerId,
    };
  }

  async upgradePlan(
    companyId: string,
    planId: string,
    successUrl: string,
    cancelUrl: string,
  ) {
    const company = await this.prisma.runAsSystem((tx) =>
      tx.company.findUnique({ where: { id: companyId } }),
    );

    if (!company) throw new NotFoundException('Company not found');

    const plan = await this.prisma.runAsSystem((tx) =>
      tx.subscriptionPlan.findUnique({ where: { id: planId } }),
    );

    if (!plan || !plan.stripePriceId) {
      throw new NotFoundException(
        'Subscription Plan or Stripe Price ID missing',
      );
    }

    let customerId = company.stripeCustomerId;
    if (!customerId) {
      customerId = await this.stripe.createCustomer(
        companyId,
        company.email || 'billing@example.com',
        company.name,
      );
      await this.prisma.runAsSystem((tx) =>
        tx.company.update({
          where: { id: companyId },
          data: { stripeCustomerId: customerId },
        }),
      );
    }

    return this.stripe.createCheckoutSession(
      companyId,
      customerId,
      plan.stripePriceId,
      successUrl,
      cancelUrl,
    );
  }

  async handleWebhook(event: any) {
    this.logger.log(`Handling stripe webhook: ${event.type}`);

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;
      const companyId = session.metadata?.companyId;
      const subscriptionId = session.subscription;

      if (companyId && subscriptionId) {
        await this.prisma.runAsSystem((tx) =>
          tx.company.update({
            where: { id: companyId },
            data: { stripeSubscriptionId: subscriptionId as string },
          }),
        );
      }
    }
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import Stripe from 'stripe';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class StripeIntegrationService {
  private readonly logger = new Logger(StripeIntegrationService.name);
  private stripe: Stripe;

  constructor(private readonly prisma: PrismaService) {
    this.stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'sk_test_mock', {
      apiVersion: '2025-01-27.acacia' as any,
    });
  }

  async createCustomer(companyId: string, email: string, name: string) {
    // In dev mode without a real key, return a mock ID
    if ((process.env.STRIPE_SECRET_KEY || 'sk_test_mock') === 'sk_test_mock') {
      return `cus_mock_${companyId}`;
    }

    const customer = await this.stripe.customers.create({
      email,
      name,
      metadata: { companyId },
    });

    return customer.id;
  }

  async createCheckoutSession(
    companyId: string,
    stripeCustomerId: string,
    stripePriceId: string,
    successUrl: string,
    cancelUrl: string,
  ) {
    if ((process.env.STRIPE_SECRET_KEY || 'sk_test_mock') === 'sk_test_mock') {
      return { url: `${successUrl}?session_id=mock_session_id` };
    }

    const session = await this.stripe.checkout.sessions.create({
      customer: stripeCustomerId,
      mode: 'subscription',
      payment_method_types: ['card'],
      line_items: [
        {
          price: stripePriceId,
          quantity: 1,
        },
      ],
      success_url: successUrl,
      cancel_url: cancelUrl,
      metadata: {
        companyId,
      },
    });

    return { url: session.url };
  }

  constructEvent(payload: string | Buffer, signature: string) {
    const secret = process.env.STRIPE_WEBHOOK_SECRET || 'whsec_mock';
    if (secret === 'whsec_mock') {
      return JSON.parse(payload.toString());
    }
    return this.stripe.webhooks.constructEvent(payload, signature, secret);
  }
}

import {
  Controller,
  Post,
  Req,
  Headers,
  BadRequestException,
} from '@nestjs/common';
import type { Request } from 'express';
import { StripeIntegrationService } from './stripe-integration.service';
import { BillingService } from './billing.service';
import { ApiTags, ApiOperation } from '@nestjs/swagger';

@ApiTags('Stripe Webhooks')
@Controller('webhooks/stripe')
export class StripeWebhookController {
  constructor(
    private readonly stripeService: StripeIntegrationService,
    private readonly billingService: BillingService,
  ) {}

  @Post()
  @ApiOperation({ summary: 'Stripe webhook receiver' })
  async handleWebhook(
    @Req() req: Request,
    @Headers('stripe-signature') signature: string,
  ) {
    if (!signature) {
      throw new BadRequestException('Missing stripe-signature header');
    }

    let event;
    try {
      // Need raw body for Stripe signature validation.
      // Assuming a raw body parser is configured, or we're using a specific interceptor.
      // For mock environments without raw body:
      const payload = req.body;
      event = this.stripeService.constructEvent(
        Buffer.isBuffer(req.body) ? req.body : JSON.stringify(req.body),
        signature,
      );
    } catch (err: any) {
      throw new BadRequestException(`Webhook Error: ${err.message}`);
    }

    await this.billingService.handleWebhook(event);

    return { received: true };
  }
}

import { Controller, Get, Query, Req, UseGuards } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';

@Controller('search')
@UseGuards(JwtAuthGuard, ThrottlerGuard)
export class UniversalSearchController {
  constructor(private prisma: PrismaService) {}

  @Get()
  @Throttle({ default: { limit: 500, ttl: 60000 } }) // 500 requests per minute to prevent DB spam
  async globalSearch(@Query('q') query: string, @Req() req: any) {
    if (!query || query.length < 2) return [];

    const companyId = req.user.companyId;

    // Execute parallel fuzzy searches across core tables using Postgres partial matching.
    // In production, this would route to ElasticSearch or Typesense.
    const [vehicles, drivers, invoices, customers] = await Promise.all([
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.vehicle.findMany({
          where: {
            companyId,
            licensePlate: { contains: query, mode: 'insensitive' },
          },
          take: 5,
        }),
      ),
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.driver.findMany({
          where: {
            companyId,
            OR: [
              { firstName: { contains: query, mode: 'insensitive' } },
              { phone: { contains: query } },
            ],
          },
          take: 5,
        }),
      ),
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.invoice.findMany({
          where: { companyId, id: { contains: query, mode: 'insensitive' } },
          take: 5,
        }),
      ),
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.customer.findMany({
          where: { companyId, name: { contains: query, mode: 'insensitive' } },
          take: 5,
        }),
      ),
    ]);

    // Format for the frontend CMD+K palette
    return [
      ...vehicles.map((v: any) => ({
        type: 'Vehicle',
        id: v.id,
        label: v.licensePlate,
      })),
      ...drivers.map((d: any) => ({
        type: 'Driver',
        id: d.id,
        label: `${d.firstName} (${d.phone})`,
      })),
      ...invoices.map((i: any) => ({ type: 'Invoice', id: i.id, label: i.id })),
      ...customers.map((c: any) => ({
        type: 'Customer',
        id: c.id,
        label: c.name,
      })),
    ];
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { ProcessEngine } from '../platform/bpm/process.engine'; // E.g., for complex dispatch actions

@WebSocketGateway({
  cors: {
    origin: '*',
  },
  namespace: '/command',
})
export class CommandGateway {
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(CommandGateway.name);

  constructor(private readonly bpm?: ProcessEngine) {}

  @SubscribeMessage('dispatch_action')
  async handleDispatchAction(
    @MessageBody() payload: any,
    @ConnectedSocket() client: Socket,
  ) {
    this.logger.log(
      `Received dispatch command: ${payload.action} for vehicle ${payload.vehicleId}`,
    );

    // In production, we authenticate and authorize the socket client here.

    // Simulate action processing (e.g. assigning a driver or pausing a trip)
    // If we have a ProcessEngine, we might trigger a BPMN workflow here.

    // Acknowledge the command back to the sender
    client.emit('command_ack', {
      status: 'SUCCESS',
      action: payload.action,
      timestamp: new Date(),
    });

    // Broadcast the state change to the telemetry namespace so everyone sees the update immediately
    // Note: Cross-namespace emission requires the server reference or an event bus.
    // For now, we assume the command triggers a DB change which triggers an event bus emission to TelemetryGateway.
    return { status: 'ACCEPTED' };
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard'; // Assume we have a WS version or we authenticate on connect

@WebSocketGateway({
  cors: {
    origin: '*',
  },
  namespace: '/telemetry',
})
export class TelemetryGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(TelemetryGateway.name);

  handleConnection(client: Socket) {
    this.logger.log(`Client connected: ${client.id}`);

    // In production, we extract the token from headers/query, verify JWT,
    // and then join the user to their company's room.
    const companyId = client.handshake.query.companyId as string;

    if (companyId) {
      client.join(`company_${companyId}`);
      this.logger.log(`Client ${client.id} joined room company_${companyId}`);
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client disconnected: ${client.id}`);
  }

  /**
   * Broadcast a telemetry update (location, speed, ETA) for a specific vehicle.
   * This is typically called internally by our TelemetryIngressService when
   * a truck's IoT device sends a ping via REST or MQTT.
   */
  broadcastVehicleUpdate(companyId: string, update: any) {
    // We broadcast to all clients joined in this company's room
    this.server.to(`company_${companyId}`).emit('vehicle_update', update);
  }

  /**
   * Broadcast an event stream item (e.g. Geofence entered, delayed)
   */
  broadcastEvent(companyId: string, event: any) {
    this.server.to(`company_${companyId}`).emit('event_stream', event);
  }

  /**
   * Broadcast an exception (e.g. Overspeeding, Late Delivery)
   */
  broadcastException(companyId: string, exception: any) {
    this.server.to(`company_${companyId}`).emit('exception_alert', exception);
  }

  @OnEvent('GpsPing.Received')
  handleGpsPingReceived(event: any) {
    const { tenantId, payload } = event;
    // Broadcast the full vehicle update (location, speed, etc.)
    this.broadcastVehicleUpdate(tenantId, payload);
  }

  @OnEvent('Geofence.Entered')
  handleGeofenceEntered(event: any) {
    const { tenantId, payload, timestamp } = event;
    this.broadcastEvent(tenantId, {
      type: 'GEOFENCE_ENTERED',
      vehicleId: payload.vehicleId,
      geofenceName: payload.geofenceName,
      timestamp,
    });
  }

  @OnEvent('Geofence.Exited')
  handleGeofenceExited(event: any) {
    const { tenantId, payload, timestamp } = event;
    this.broadcastEvent(tenantId, {
      type: 'GEOFENCE_EXITED',
      vehicleId: payload.vehicleId,
      geofenceName: payload.geofenceName,
      timestamp,
    });
  }

  @OnEvent('Alert.Triggered')
  handleAlertTriggered(event: any) {
    const { tenantId, payload, timestamp } = event;
    this.broadcastException(tenantId, {
      alertId: payload.alertId,
      ruleType: payload.ruleType,
      timestamp,
    });
  }
}

import type { AuthenticatedUser } from '../../auth/decorators/get-user.decorator';
import { GetUser } from '../../auth/decorators/get-user.decorator';
import {
  Controller,
  Post,
  Get,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';

import {
  VehicleTelemetryDto,
  CreateGeofenceDto,
  CreateAlertRuleDto,
  UpdateAlertStatusDto,
} from '../dto/telematics.dto';

import { GeofenceEngineService } from '../services/geofence-engine.service';
import { TelematicsIngestionService } from '../services/telematics-ingestion.service';

@ApiTags('Enterprise Fleet Telematics, IoT & Geofence Intelligence Platform')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('tracking/enterprise')
export class EnterpriseTelematicsController {
  constructor(
    private readonly geofenceEngine: GeofenceEngineService,
    private readonly telematicsService: TelematicsIngestionService,
  ) {}

  // --- TELEMETRY INGESTION ---
  @Post('telemetry')
  @RequirePermissions('tracking:write')
  @ApiOperation({
    summary:
      'Ingest real-time OBD-II and CAN-bus telemetry and evaluate alert rules',
  })
  async ingestTelemetry(
    @Body() dto: VehicleTelemetryDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.telematicsService.ingestTelemetry(user.companyId, dto);
  }

  // --- GEOFENCE MANAGEMENT ---
  @Post('geofences')
  @RequirePermissions('tracking:write')
  @ApiOperation({ summary: 'Create circular or polygon geofence' })
  async createGeofence(
    @Body() dto: CreateGeofenceDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.geofenceEngine.createGeofence(user.companyId, user.userId, dto);
  }

  @Get('geofences')
  @RequirePermissions('tracking:read')
  @ApiOperation({ summary: 'List active geofences' })
  async getGeofences(
    @Query('type') type?: string,
    @GetUser() user: AuthenticatedUser = {} as any,
  ) {
    return this.geofenceEngine.getGeofences(user.companyId, type);
  }

  @Get('geofences/:id')
  @RequirePermissions('tracking:read')
  @ApiOperation({ summary: 'Get geofence by ID with recent transition events' })
  async getGeofenceById(
    @Param('id') id: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.geofenceEngine.getGeofenceById(user.companyId, id);
  }

  @Delete('geofences/:id')
  @RequirePermissions('tracking:write')
  @ApiOperation({ summary: 'Delete geofence' })
  async deleteGeofence(
    @Param('id') id: string,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.geofenceEngine.deleteGeofence(user.companyId, id, user.userId);
  }

  @Post('geofences/evaluate')
  @HttpCode(HttpStatus.OK)
  @RequirePermissions('tracking:write')
  @ApiOperation({
    summary:
      'Evaluate GPS location against geofences and record boundary transitions',
  })
  async evaluateLocation(
    @Body()
    dto: {
      vehicleId: string;
      latitude: number;
      longitude: number;
      timestamp?: string;
    },
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.geofenceEngine.evaluateLocationAgainstGeofences(
      user.companyId,
      dto.vehicleId,
      dto.latitude,
      dto.longitude,
      dto.timestamp ? new Date(dto.timestamp) : new Date(),
    );
  }

  @Get('geofence-events')
  @RequirePermissions('tracking:read')
  @ApiOperation({
    summary: 'View recent geofence boundary transition and dwell time events',
  })
  async getGeofenceEvents(
    @Query('geofenceId') geofenceId?: string,
    @Query('vehicleId') vehicleId?: string,
    @GetUser() user: AuthenticatedUser = {} as any,
  ) {
    return this.geofenceEngine.getGeofenceEvents(
      user.companyId,
      geofenceId,
      vehicleId,
    );
  }

  // --- ALERT RULES & FLEET HEALTH ---
  @Post('alert-rules')
  @RequirePermissions('tracking:write')
  @ApiOperation({ summary: 'Create IoT/telematics alert rule' })
  async createAlertRule(
    @Body() dto: CreateAlertRuleDto,
    @GetUser() user: AuthenticatedUser,
  ) {
    return this.telematicsService.createAlertRule(
      user.companyId,
      user.userId,
      dto,
    );
  }

