});

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import { CreateGeofenceDto } from '../dto/telematics.dto';

@Injectable()
export class GeofenceEngineService {
  private readonly logger = new Logger(GeofenceEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async createGeofence(
    companyId: string,
    userId: string,
    dto: CreateGeofenceDto,
  ) {
    const geofence = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.create({
        data: {
          companyId,
          name: dto.name,
          description: dto.description || null,
          type: dto.type,
          latitude: dto.latitude,
          longitude: dto.longitude,
          radiusMeters: dto.radiusMeters || 100,
          polygon: dto.polygon ? (dto.polygon as any) : undefined,
          isActive: dto.isActive !== undefined ? dto.isActive : true,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'geofence:create',
      entity: 'Geofence',
      entityId: geofence.id,
      userId,
      companyId,
      details: {
        name: geofence.name,
        type: geofence.type,
        radiusMeters: geofence.radiusMeters,
      },
    });

    return geofence;
  }

  async getGeofences(companyId: string, type?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.findMany({
        where: {
          companyId,
          type: type || undefined,
          isActive: true,
        },
        orderBy: { name: 'asc' },
      }),
    );
  }

  async getGeofenceById(companyId: string, id: string) {
    const geofence = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.findUnique({
        where: { id },
        include: {
          events: {
            orderBy: { timestamp: 'desc' },
            take: 10,
          },
        },
      }),
    );
    if (!geofence || geofence.companyId !== companyId) {
      throw new NotFoundException('Geofence not found');
    }
    return geofence;
  }

  async deleteGeofence(companyId: string, id: string, userId: string) {
    const geofence = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.findUnique({ where: { id } }),
    );
    if (!geofence || geofence.companyId !== companyId) {
      throw new NotFoundException('Geofence not found');
    }

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.delete({ where: { id } }),
    );

    await this.audit.logEvent({
      action: 'geofence:delete',
      entity: 'Geofence',
      entityId: id,
      userId,
      companyId,
      details: { name: geofence.name },
    });

    return { success: true, id };
  }

  // Haversine formula to calculate distance in meters between two lat/lng points
  private calculateDistanceMeters(
    lat1: number,
    lon1: number,
    lat2: number,
    lon2: number,
  ): number {
    const R = 6371e3; // Earth radius in meters
    const phi1 = (lat1 * Math.PI) / 180;
    const phi2 = (lat2 * Math.PI) / 180;
    const deltaPhi = ((lat2 - lat1) * Math.PI) / 180;
    const deltaLambda = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
      Math.cos(phi1) *
        Math.cos(phi2) *
        Math.sin(deltaLambda / 2) *
        Math.sin(deltaLambda / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c;
  }

  // Real-time Geospatial Geofence Boundary Transition Engine
  async evaluateLocationAgainstGeofences(
    companyId: string,
    vehicleId: string,
    latitude: number,
    longitude: number,
    timestamp: Date = new Date(),
  ) {
    const geofences = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofence.findMany({
        where: { companyId, isActive: true },
      }),
    );

    const eventsCreated: any[] = [];

    for (const fence of geofences) {
      const distance = this.calculateDistanceMeters(
        latitude,
        longitude,
        fence.latitude,
        fence.longitude,
      );
      const isInside = distance <= fence.radiusMeters;

      // Check last event for this vehicle in this geofence
      const lastEvent = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.geofenceEvent.findFirst({
          where: { geofenceId: fence.id, vehicleId },
          orderBy: { timestamp: 'desc' },
        }),
      );

      const wasInside = lastEvent?.eventType === 'ENTER';

      if (isInside && !wasInside) {
        // TRANSITION: ENTER
        const enterEvent = await this.prisma.runAsTenant(
          companyId,
          async (tx) =>
            tx.geofenceEvent.create({
              data: {
                companyId,
                geofenceId: fence.id,
                vehicleId,
                eventType: 'ENTER',
                timestamp,
                metadata: { distanceMeters: Math.round(distance) },
              },
            }),
        );

        await this.audit.logEvent({
          action: 'geofence:transition:enter',
          entity: 'GeofenceEvent',
          entityId: enterEvent.id,
          userId: undefined,
          companyId,
          details: {
            geofenceName: fence.name,
            vehicleId,
            geofenceId: fence.id,
          },
        });

        eventsCreated.push(enterEvent);
      } else if (!isInside && wasInside) {
        // TRANSITION: EXIT (calculate dwell time)
        const enterTime = lastEvent.timestamp.getTime();
        const exitTime = timestamp.getTime();
        const dwellMinutes = Math.max(
          1,
          Math.round((exitTime - enterTime) / 60000),
        );

        const exitEvent = await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.geofenceEvent.create({
            data: {
              companyId,
              geofenceId: fence.id,
              vehicleId,
              eventType: 'EXIT',
              timestamp,
              metadata: {
                dwellMinutes,
                enteredAt: lastEvent.timestamp.toISOString(),
                exitedAt: timestamp.toISOString(),
                distanceMeters: Math.round(distance),
              },
            },
          }),
        );

        await this.audit.logEvent({
          action: 'geofence:transition:exit',
          entity: 'GeofenceEvent',
          entityId: exitEvent.id,
          userId: undefined,
          companyId,
          details: { geofenceName: fence.name, vehicleId, dwellMinutes },
        });

        eventsCreated.push(exitEvent);
      }
    }

    return { evaluatedCount: geofences.length, eventsCreated };
  }

  async getGeofenceEvents(
    companyId: string,
    geofenceId?: string,
    vehicleId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.geofenceEvent.findMany({
        where: {
          companyId,
          geofenceId: geofenceId || undefined,
          vehicleId: vehicleId || undefined,
        },
        include: {
          geofence: { select: { name: true, type: true } },
          vehicle: { select: { licensePlate: true } },
        },
        orderBy: { timestamp: 'desc' },
        take: 50,
      }),
    );
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import { NotificationOrchestratorService } from '../../communications/engine/notification-orchestrator.service';
import { NotificationPriority } from '../../communications/dto/notification.dto';
import {
  VehicleTelemetryDto,
  CreateAlertRuleDto,
  UpdateAlertStatusDto,
} from '../dto/telematics.dto';

@Injectable()
export class TelematicsIngestionService {
  private readonly logger = new Logger(TelematicsIngestionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
    private readonly notificationOrchestrator: NotificationOrchestratorService,
  ) {}

  async ingestTelemetry(companyId: string, dto: VehicleTelemetryDto) {
    const vehicle = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.vehicle.findUnique({
        where: { id: dto.vehicleId },
      }),
    );
    if (!vehicle || vehicle.companyId !== companyId) {
      throw new NotFoundException('Vehicle not found in company');
    }

    const timestamp = dto.timestamp ? new Date(dto.timestamp) : new Date();

    // 1. Save Telemetry
    const telemetry = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.vehicleTelemetry.create({
        data: {
          companyId,
          vehicleId: dto.vehicleId,
          odometer: dto.odometer || null,
          engineHours: dto.engineHours || null,
          fuelLevel: dto.fuelLevel || null,
          batteryVolts: dto.batteryVolts || null,
          coolantTemp: dto.coolantTemp || null,
          engineLoad: dto.engineLoad || null,
          rpm: dto.rpm || null,
          dtcCodes: dto.dtcCodes ? (dto.dtcCodes as any) : undefined,
          ignition: dto.ignition !== undefined ? dto.ignition : null,
          timestamp,
        },
      }),
    );

    // 2. Evaluate Active Alert Rules
    const rules = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alertRule.findMany({
        where: { companyId, isActive: true },
      }),
    );

    const triggeredAlerts: any[] = [];

    for (const rule of rules) {
      let triggered = false;
      let actualValue: any = null;
      let message = '';

      if (rule.type === 'SPEEDING' && dto.speed !== undefined) {
        if (rule.condition === 'EXCEEDS' && dto.speed > rule.threshold) {
          triggered = true;
          actualValue = dto.speed;
          message = `Vehicle ${vehicle.licensePlate} speeding at ${dto.speed} mph (threshold: ${rule.threshold} mph)`;
        }
      } else if (rule.type === 'MAINTENANCE' || rule.type === 'COOLANT') {
        if (dto.coolantTemp !== undefined && dto.coolantTemp > rule.threshold) {
          triggered = true;
          actualValue = dto.coolantTemp;
          message = `Vehicle ${vehicle.licensePlate} engine overheating at ${dto.coolantTemp}°F`;
        } else if (dto.dtcCodes && dto.dtcCodes.length > 0) {
          triggered = true;
          actualValue = dto.dtcCodes;
          message = `Vehicle ${vehicle.licensePlate} reported diagnostic trouble codes: ${dto.dtcCodes.join(', ')}`;
        }
      } else if (rule.type === 'LOW_FUEL' && dto.fuelLevel !== undefined) {
        if (rule.condition === 'LESS_THAN' && dto.fuelLevel < rule.threshold) {
          triggered = true;
          actualValue = dto.fuelLevel;
          message = `Vehicle ${vehicle.licensePlate} low fuel level at ${dto.fuelLevel}%`;
        }
      } else if (rule.type === 'BATTERY' && dto.batteryVolts !== undefined) {
        if (
          rule.condition === 'LESS_THAN' &&
          dto.batteryVolts < rule.threshold
        ) {
          triggered = true;
          actualValue = dto.batteryVolts;
          message = `Vehicle ${vehicle.licensePlate} low battery voltage at ${dto.batteryVolts}V`;
        }
      }

      if (triggered) {
        const alert = await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.alert.create({
            data: {
              companyId,
              ruleId: rule.id,
              vehicleId: dto.vehicleId,
              driverId: dto.driverId || null,
              severity: rule.severity || 'MEDIUM',
              message,
              status: 'NEW',
              timestamp,
              metadata: {
                actualValue,
                threshold: rule.threshold,
                telemetryId: telemetry.id,
              },
            },
          }),
        );

        triggeredAlerts.push(alert);

        // Notify Admin / Dispatch via Orchestrator if HIGH or CRITICAL
        if (rule.severity === 'HIGH' || rule.severity === 'CRITICAL') {
          try {
            // Find an admin user in the company to receive alert
            const adminUser = await this.prisma.runAsTenant(
              companyId,
              async (tx) =>
                tx.user.findFirst({
                  where: { companyId, status: 'ACTIVE' },
                }),
            );
            if (adminUser) {
              await this.notificationOrchestrator.dispatchNotification(
                companyId,
                adminUser.id,
                {
                  targetUserId: adminUser.id,
                  eventType: `telematics.${rule.type.toLowerCase()}`,
                  priority:
                    rule.severity === 'CRITICAL'
                      ? NotificationPriority.URGENT
                      : NotificationPriority.HIGH,
                  title: `Fleet Alert: ${rule.name}`,
                  body: message,
                  entityType: 'Vehicle',
                  entityId: vehicle.id,
                  channels: ['IN_APP', 'EMAIL'],
                },
              );
            }
          } catch (e) {
            this.logger.error(`Failed to dispatch alert notification: ${e}`);
          }
        }
      }
    }

    return {
      success: true,
      telemetryId: telemetry.id,
      evaluatedRulesCount: rules.length,
      triggeredAlertsCount: triggeredAlerts.length,
      triggeredAlerts,
    };
  }

  // Alert Rules CRUD
  async createAlertRule(
    companyId: string,
    userId: string,
    dto: CreateAlertRuleDto,
  ) {
    const rule = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alertRule.create({
        data: {
          companyId,
          name: dto.name,
          type: dto.type,
          condition: dto.condition,
          threshold: dto.threshold,
          severity: dto.severity || 'MEDIUM',
          isActive: dto.isActive !== undefined ? dto.isActive : true,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'telematics:alert_rule:create',
      entity: 'AlertRule',
      entityId: rule.id,
      userId,
      companyId,
      details: { name: rule.name, type: rule.type, threshold: rule.threshold },
    });

    return rule;
  }

  async getAlertRules(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alertRule.findMany({
        where: { companyId },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }

  async deleteAlertRule(companyId: string, id: string, userId: string) {
    const rule = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alertRule.findUnique({ where: { id } }),
    );
    if (!rule || rule.companyId !== companyId) {
      throw new NotFoundException('Alert rule not found');
    }

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alertRule.delete({ where: { id } }),
    );
    return { success: true, id };
  }

  // Alerts Management
  async getAlerts(companyId: string, status?: string, vehicleId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.findMany({
        where: {
          companyId,
          status: status || undefined,
          vehicleId: vehicleId || undefined,
        },
        include: {
          vehicle: { select: { licensePlate: true, make: true, model: true } },
          rule: { select: { name: true, type: true } },
        },
        orderBy: { timestamp: 'desc' },
        take: 100,
      }),
    );
  }

  async updateAlertStatus(
    companyId: string,
    id: string,
    userId: string,
    dto: UpdateAlertStatusDto,
  ) {
    const alert = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.findUnique({ where: { id } }),
    );
    if (!alert || alert.companyId !== companyId) {
      throw new NotFoundException('Alert not found');
    }

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.update({
        where: { id },
        data: {
          status: dto.status,
          resolvedAt: dto.status === 'RESOLVED' ? new Date() : undefined,
          metadata: {
            ...(alert.metadata as any),
            lastUpdatedBy: userId,
            notes: dto.notes || null,
          },
        },
      }),
    );

    await this.audit.logEvent({
      action: `telematics:alert:${dto.status.toLowerCase()}`,
      entity: 'Alert',
      entityId: id,
      userId,
      companyId,
      details: {
        previousStatus: alert.status,
        newStatus: dto.status,
        notes: dto.notes,
      },
    });

    return updated;
  }

  async getFleetHealthAnalytics(companyId: string) {
    const [totalAlerts, unresolvedAlerts, criticalAlerts, vehicleCount] =
      await Promise.all([
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.alert.count({ where: { companyId } }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.alert.count({
            where: { companyId, status: { in: ['NEW', 'ACKNOWLEDGED'] } },
          }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.alert.count({
            where: {
              companyId,
              severity: 'CRITICAL',
              status: { in: ['NEW', 'ACKNOWLEDGED'] },
            },
          }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.vehicle.count({ where: { companyId } }),
        ),
      ]);

    const alertsByType = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.groupBy({
        by: ['ruleId'],
        where: { companyId, status: { in: ['NEW', 'ACKNOWLEDGED'] } },
        _count: true,
      }),
    );

    return {
      companyId,
      summary: { vehicleCount, totalAlerts, unresolvedAlerts, criticalAlerts },
      timestamp: new Date().toISOString(),
    };
  }
}

import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { LogLocationDto } from './dto/log-location.dto';

@Injectable()
export class TrackingService {
  constructor(private prisma: PrismaService) {}

  async getLiveTracking(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const activeTrips = await tx.trip.findMany({
        where: {
          companyId,
          status: { in: ['IN_PROGRESS', 'DISPATCHED'] },
        },
        include: {
          driver: true,
          vehicle: true,
          loads: {
            include: { customer: true },
          },
        },
      });

      const tripIds = activeTrips.map((t) => t.id);

      let latestLocations: any[] = [];
      if (tripIds.length > 0) {
        latestLocations = await tx.$queryRaw<any[]>`
          SELECT DISTINCT ON ("companyId", "tripId") * FROM "LocationHistory" 
          WHERE "companyId" = ${companyId} AND "tripId" = ANY(${tripIds}) 
          ORDER BY "companyId", "tripId", "timestamp" DESC
        `;
      }

      const locationMap = new Map(
        latestLocations.map((loc) => [loc.tripId, loc]),
      );

      const trackingData = activeTrips.map((trip) => {
        const lastLocation = locationMap.get(trip.id);

        return {
          tripId: trip.id,
          tripNumber: trip.tripNumber,
          status: trip.status,
          driver: trip.driver
            ? {
                id: trip.driver.id,
                name: `${trip.driver.firstName} ${trip.driver.lastName}`,
                phone: trip.driver.phone,
              }
            : null,
          vehicle: trip.vehicle
            ? { id: trip.vehicle.id, licensePlate: trip.vehicle.licensePlate }
            : null,
          loads: trip.loads.map((l) => ({
            id: l.id,
            referenceNumber: l.referenceNumber,
            origin: `${l.originCity}, ${l.originState}`,
            destination: `${l.destinationCity}, ${l.destinationState}`,
          })),
          lastLocation: lastLocation
            ? {
                latitude: lastLocation.latitude,
                longitude: lastLocation.longitude,
                speed: lastLocation.speed,
                heading: lastLocation.heading,
                timestamp: lastLocation.timestamp,
              }
            : null,
        };
      });

      return {
        activeVehiclesCount: activeTrips.length,
        trackingData,
      };
    });
  }

  async logLocation(companyId: string, logLocationDto: LogLocationDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const locations = logLocationDto.locations.map((loc) => ({
        ...loc,
        companyId,
        timestamp: loc.timestamp ? new Date(loc.timestamp) : new Date(),
      }));

      await tx.locationHistory.createMany({
        data: locations,
        skipDuplicates: true, // In case of retry
      });

      return { success: true, count: locations.length };
    });
  }
}

import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateTrailerDto } from './dto/create-trailer.dto';
import { UpdateTrailerDto } from './dto/update-trailer.dto';
import { TrailerQueryDto } from './dto/trailer-query.dto';

@Injectable()
export class TrailersService {
  constructor(private prisma: PrismaService) {}

  async create(companyId: string, createTrailerDto: CreateTrailerDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.vehicle.create({
        data: {
          ...createTrailerDto,
          companyId,
          type: 'TRAILER', // Force type to TRAILER
        },
      });
    });
  }

  async findAll(companyId: string, query: TrailerQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { page = 1, limit = 10, search, status } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: any = {
        type: 'TRAILER',
      };

      if (search) {
        where.OR = [
          { licensePlate: { contains: search, mode: 'insensitive' } },
          { vin: { contains: search, mode: 'insensitive' } },
          { make: { contains: search, mode: 'insensitive' } },
          { model: { contains: search, mode: 'insensitive' } },
        ];
      }

      if (status) {
        where.status = status;
      }

      const [data, total] = await Promise.all([
        tx.vehicle.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
        }),
        tx.vehicle.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trailer = await tx.vehicle.findFirst({
        where: { id, type: 'TRAILER' },
      });

      if (!trailer) {
        throw new NotFoundException(`Trailer with ID ${id} not found`);
      }
      return trailer;
    });
  }

  async update(
    companyId: string,
    id: string,
    updateTrailerDto: UpdateTrailerDto,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrailer = await tx.vehicle.findFirst({
        where: { id, type: 'TRAILER' },
      });

      if (!existingTrailer) throw new NotFoundException();

      return tx.vehicle.update({
        where: { id },
        data: updateTrailerDto,
      });
    });
  }

  async remove(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrailer = await tx.vehicle.findFirst({
        where: { id, type: 'TRAILER' },
      });

      if (!existingTrailer) throw new NotFoundException();

      return tx.vehicle.update({
        where: { id },
        data: { deletedAt: new Date(), status: 'OUT_OF_SERVICE' },
      });
    });
  }
}

