import { NotFoundException } from '@nestjs/common';

describe('TripsService', () => {
  let service: TripsService;
  let eventEmitter: jest.Mocked<EventEmitter2>;

  const mockTx = {
    trip: {
      create: jest.fn(),
      findMany: jest.fn(),
      findFirst: jest.fn(),
      count: jest.fn(),
      update: jest.fn(),
    },
    load: { updateMany: jest.fn(), findMany: jest.fn().mockResolvedValue([]) },
    auditLog: { create: jest.fn() },
  };

  const mockPrisma = {
    runAsSystem: jest.fn().mockImplementation(async (cb) => cb(mockPrisma)),
    runAsTenant: jest.fn((companyId: string, cb: (tx: any) => any) =>
      cb(mockTx),
    ),
    updateWithOcc: jest.fn(),
  };

  const mockEventEmitter = { emit: jest.fn() };

  beforeEach(async () => {
    jest.clearAllMocks();

    const mockWorkflowService = {
      evaluateRules: jest.fn().mockResolvedValue({ triggeredActions: [] }),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        TripsService,
        { provide: AuditService, useValue: { logEvent: jest.fn() } },
        { provide: PrismaService, useValue: mockPrisma },
        { provide: EventEmitter2, useValue: mockEventEmitter },
        { provide: WorkflowService, useValue: mockWorkflowService },
      ],
    }).compile();
    service = module.get<TripsService>(TripsService);
    eventEmitter = module.get(EventEmitter2);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('create', () => {
    it('should auto-generate a tripNumber if not provided', async () => {
      const dto = { driverId: 'driver-1', vehicleId: 'vehicle-1' };
      const mockTrip = {
        id: 'trip-1',
        tripNumber: 'TRP-ABC123',
        status: 'PLANNED',
        loads: [],
      };
      mockTx.trip.create.mockResolvedValue(mockTrip);

      const result = await service.create('company-1', dto);

      expect(result.tripNumber).toMatch(/TRP-/);
      expect(mockEventEmitter.emit).toHaveBeenCalledWith(
        'trip.created',
        expect.any(Object),
      );
    });

    it('should use provided tripNumber if given', async () => {
      const dto = { tripNumber: 'TRP-CUSTOM-001', driverId: 'driver-1' };
      const mockTrip = {
        id: 'trip-1',
        tripNumber: 'TRP-CUSTOM-001',
        status: 'PLANNED',
        loads: [],
      };
      mockTx.trip.create.mockResolvedValue(mockTrip);

      const result = await service.create('company-1', dto);
      expect(result.tripNumber).toBe('TRP-CUSTOM-001');
    });

    it('should convert date strings to Date objects', async () => {
      const dto = {
        startDate: '2026-08-01',
        endDate: '2026-08-05',
        tripNumber: 'TRP-001',
      };
      const mockTrip = { id: 'trip-1', tripNumber: 'TRP-001', loads: [] };
      mockTx.trip.create.mockResolvedValue(mockTrip);

      await service.create('company-1', dto);

      expect(mockTx.trip.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({
            startDate: new Date('2026-08-01'),
            endDate: new Date('2026-08-05'),
          }),
        }),
      );
    });
  });

  describe('findOne', () => {
    it('should return trip if found', async () => {
      const mockTrip = { id: 'trip-1', tripNumber: 'TRP-001' };
      mockTx.trip.findFirst.mockResolvedValue(mockTrip);

      const result = await service.findOne('company-1', 'trip-1');
      expect(result).toEqual(mockTrip);
    });

    it('should throw NotFoundException if trip not found', async () => {
      mockTx.trip.findFirst.mockResolvedValue(null);
      await expect(service.findOne('company-1', 'trip-999')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('assignLoads', () => {
    it('should assign loads to a trip and update their status to ASSIGNED', async () => {
      const mockTrip = { id: 'trip-1', loads: [] };
      mockTx.trip.findFirst.mockResolvedValue(mockTrip);
      mockTx.load.updateMany.mockResolvedValue({ count: 2 });
      mockTx.trip.findFirst
        .mockResolvedValueOnce(mockTrip)
        .mockResolvedValueOnce({
          ...mockTrip,
          loads: [{ id: 'load-1' }, { id: 'load-2' }],
        });

      mockTx.load.findMany.mockResolvedValue([
        { id: 'load-1' },
        { id: 'load-2' },
      ]);

      await service.assignLoads('company-1', 'trip-1', ['load-1', 'load-2']);

      expect(mockTx.load.updateMany).toHaveBeenCalledWith({
        where: { id: { in: ['load-1', 'load-2'] }, companyId: 'company-1' },
        data: { tripId: 'trip-1', status: 'ASSIGNED' },
      });
    });

    it('should throw NotFoundException if trip not found', async () => {
      mockTx.trip.findFirst.mockResolvedValue(null);
      mockTx.load.findMany.mockResolvedValue([{ id: 'load-1' }]);
      await expect(
        service.assignLoads('company-1', 'trip-999', ['load-1']),
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('remove', () => {
    it('should soft-delete trip, unassign loads, and set status to CANCELLED', async () => {
      const mockTrip = { id: 'trip-1', tripNumber: 'TRP-001' };
      mockTx.trip.findFirst.mockResolvedValue(mockTrip);
      mockTx.load.updateMany.mockResolvedValue({ count: 2 });
      mockTx.trip.update.mockResolvedValue({
        ...mockTrip,
        deletedAt: new Date(),
        status: 'CANCELLED',
      });

      const result = await service.remove('company-1', 'trip-1');

      expect(mockTx.load.updateMany).toHaveBeenCalledWith(
        expect.objectContaining({ data: { tripId: null, status: 'PENDING' } }),
      );
      expect(result.status).toBe('CANCELLED');
    });
  });
});

import { AuditService } from '../platform/audit/audit.service';
import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import {
  Injectable,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateTripDto } from './dto/create-trip.dto';
import { WorkflowService } from '../workflow/workflow.service';
import { UpdateTripDto } from './dto/update-trip.dto';
import { TripQueryDto } from './dto/trip-query.dto';
import { EventEmitter2 } from '@nestjs/event-emitter';
import * as crypto from 'crypto';

@Injectable()
export class TripsService {
  constructor(
    private readonly auditService: AuditService,

    private prisma: PrismaService,
    private eventEmitter: EventEmitter2,
    private workflow: WorkflowService,
  ) {}

  async create(companyId: string, createTripDto: CreateTripDto) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) => {
      const data: any = { ...createTripDto, companyId };
      if (data.startDate) data.startDate = new Date(data.startDate);
      if (data.endDate) data.endDate = new Date(data.endDate);
      if (data.eta) data.eta = new Date(data.eta);

      if (!data.tripNumber) {
        data.tripNumber = `TRP-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
      } else {
        const existingTripNum = await tx.trip.findFirst({
          where: { tripNumber: data.tripNumber },
        });
        if (existingTripNum) {
          throw new ConflictException(
            `Trip number ${data.tripNumber} already exists.`,
          );
        }
      }

      const trip = await tx.trip.create({
        data,
        include: { driver: true, vehicle: true, trailer: true, loads: true },
      });

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'TRIP',
        trigger: 'TRIP_CREATED',
        entityData: trip,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new Error('Trip creation rejected by business rules.');
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: trip.id,
          action: 'CREATE',
          details: { tripNumber: trip.tripNumber, status: trip.status },
          source: 'API',
        },
        null,
        tx,
      );

      return trip;
    });

    this.eventEmitter.emit('trip.created', {
      companyId,
      tripId: trip.id,
      tripNumber: trip.tripNumber,
      status: trip.status,
    });

    return trip;
  }

  async findAll(companyId: string, query: TripQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const {
        page = 1,
        limit = 10,
        search,
        status,
        driverId,
        vehicleId,
      } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.TripWhereInput = { companyId };

      if (search) {
        where.OR = [
          { tripNumber: { contains: search, mode: 'insensitive' } },
          { driver: { firstName: { contains: search, mode: 'insensitive' } } },
          { driver: { lastName: { contains: search, mode: 'insensitive' } } },
          {
            vehicle: {
              licensePlate: { contains: search, mode: 'insensitive' },
            },
          },
        ];
      }

      if (status) where.status = status;
      if (driverId) where.driverId = driverId;
      if (vehicleId) where.vehicleId = vehicleId;

      const [data, total] = await Promise.all([
        tx.trip.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: {
            driver: true,
            vehicle: true,
            trailer: true,
            loads: { include: { customer: true } },
          },
        }),
        tx.trip.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findFirst({
        where: { id, companyId },
        include: {
          driver: true,
          vehicle: true,
          trailer: true,
          loads: { include: { customer: true } },
        },
      });

      if (!trip) {
        throw new NotFoundException(`Trip with ID ${id} not found`);
      }
      return trip;
    });
  }

  async update(companyId: string, id: string, updateTripDto: UpdateTripDto) {
    const result = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id, companyId },
      });
      if (!existingTrip) throw new NotFoundException();

      const data: any = { ...updateTripDto };
      if (data.startDate) data.startDate = new Date(data.startDate);
      if (data.endDate) data.endDate = new Date(data.endDate);
      if (data.eta) data.eta = new Date(data.eta);

      if (data.tripNumber && data.tripNumber !== existingTrip.tripNumber) {
        const duplicate = await tx.trip.findFirst({
          where: { tripNumber: data.tripNumber },
        });
        if (duplicate) {
          throw new ConflictException(
            `Trip number ${data.tripNumber} already exists.`,
          );
        }
      }

      const updatedTrip = await this.prisma.updateWithOcc<any>(
        tx,
        'trip',
        id,
        existingTrip.updatedAt,
        data,
        { driver: true, vehicle: true, trailer: true, loads: true },
      );

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: updatedTrip.id,
          action: 'UPDATE',
          beforeValue: { status: existingTrip.status },
          afterValue: { status: updatedTrip.status },
          source: 'API',
        },
        null,
        tx,
      );

      return { updatedTrip, existingStatus: existingTrip.status };
    });

    if (
      result.existingStatus !== 'IN_TRANSIT' &&
      result.updatedTrip.status === 'IN_TRANSIT'
    ) {
      this.eventEmitter.emit('trip.started', result.updatedTrip);
    } else if (
      result.existingStatus !== 'COMPLETED' &&
      result.updatedTrip.status === 'COMPLETED'
    ) {
      this.eventEmitter.emit('trip.completed', result.updatedTrip);
    } else {
      this.eventEmitter.emit('trip.updated', result.updatedTrip);
    }

    return result.updatedTrip;
  }

  async assignLoads(companyId: string, id: string, loadIds: string[]) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id },
      });
      if (!existingTrip) throw new NotFoundException();

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'TRIP',
        trigger: 'ASSIGN_LOADS',
        entityData: { trip: existingTrip, loadIds },
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new Error('Load assignment rejected by business rules.');
      }

      // Verify that all loads are unassigned before assigning them
      const availableLoads = await tx.load.findMany({
        where: {
          id: { in: loadIds },
          companyId,
          tripId: null,
          status: 'PENDING',
        },
      });

      if (availableLoads.length !== loadIds.length) {
        throw new ConflictException(
          'One or more loads are already assigned to another trip or do not exist.',
        );
      }

      // Assign tripId to each load
      await tx.load.updateMany({
        where: { id: { in: loadIds }, companyId },
        data: { tripId: id, status: 'ASSIGNED' },
      });

      const updatedTrip = await tx.trip.findFirst({
        where: { id },
        include: { loads: true },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: id,
          action: 'ASSIGN_LOADS',
          details: { loadIds },
          source: 'API',
        },
        null,
        tx,
      );

      return updatedTrip;
    });
  }

  async remove(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id },
      });
      if (!existingTrip) throw new NotFoundException();

      // Unassign loads when trip is cancelled/removed
      await tx.load.updateMany({
        where: { tripId: id, companyId },
        data: { tripId: null, status: 'PENDING' },
      });

      const deletedTrip = await tx.trip.update({
        where: { id },
        data: { deletedAt: new Date(), status: 'CANCELLED' },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: deletedTrip.id,
          action: 'DELETE',
          details: { tripNumber: deletedTrip.tripNumber },
          source: 'API',
        },
        null,
        tx,
      );

      return deletedTrip;
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

@Injectable()
export class ComplianceEngine {
  private readonly logger = new Logger(ComplianceEngine.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  /**
   * Evaluates document expiry for Fleet Assets (Vehicles/Drivers).
   */
  async evaluateDocumentCompliance(
    companyId: string,
    assetType: 'VEHICLE' | 'DRIVER',
    assetId: string,
    documents: any[],
  ) {
    this.logger.log(`Evaluating compliance for ${assetType} ${assetId}`);

    const now = new Date();
    const expiryThreshold = new Date();
    expiryThreshold.setDate(now.getDate() + 30); // Alert 30 days prior

    let isCompliant = true;
    let criticalExpiry = false;

    for (const doc of documents) {
      if (doc.expiryDate) {
        const expiry = new Date(doc.expiryDate);

        if (expiry < now) {
          isCompliant = false;
          criticalExpiry = true;
          this.logger.error(
            `Critical Compliance Failure: ${doc.type} expired on ${assetType} ${assetId}`,
          );

          await this.eventStore.append({
            tenantId: companyId,
            streamId: assetId,
            streamType: assetType,
            eventType: 'DocumentExpired',
            payload: { type: doc.type, expiry: doc.expiryDate },
            userId: 'SYSTEM',
          });
        } else if (expiry < expiryThreshold) {
          // Warning threshold
          this.logger.warn(
            `Compliance Warning: ${doc.type} expiring soon on ${assetType} ${assetId}`,
          );

          await this.eventStore.append({
            tenantId: companyId,
            streamId: assetId,
            streamType: assetType,
            eventType: 'DocumentExpiring',
            payload: { type: doc.type, expiry: doc.expiryDate },
            userId: 'SYSTEM',
          });
        }
      }
    }

    // Auto-block asset if critically non-compliant
    if (criticalExpiry) {
      try {
        const model = (this.prisma as any)[assetType.toLowerCase()];
        const asset = await model.findUnique({
          where: { id: assetId },
          select: { status: true },
        });

        if (asset && asset.status === 'ACTIVE') {
          await this.lifecycle.transitionState({
            companyId,
            entityType: assetType === 'VEHICLE' ? 'Vehicle' : 'Driver',
            entityId: assetId,
            fromState: asset.status,
            toState: 'BLOCKED',
            userId: 'SYSTEM',
            reason: 'Auto-blocked due to expired critical compliance documents',
          });
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        this.logger.error(
          `Failed to auto-block non-compliant asset: ${errorMessage}`,
        );
      }
    }

    return isCompliant;
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import {
  IAnalyticsProvider,
  AnalyticsRegistryService,
} from '../../platform/analytics/analytics-registry.service';

export interface FleetAnalyticsResult {
  fleetUtilizationPercentage: number;
  downtimeHours: number;
  maintenanceCost: number;
  fuelEfficiencyKmpl: number;
  costPerKm: number;
  breakdownFrequency: number;
  vehicleAvailabilityPercentage: number;
}

@Injectable()
export class FleetAnalyticsService implements OnModuleInit, IAnalyticsProvider {
  private readonly logger = new Logger(FleetAnalyticsService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly analyticsRegistry: AnalyticsRegistryService,
  ) {}

  onModuleInit() {
    this.analyticsRegistry.register(this);
  }

  getDomainName(): string {
    return 'fleet';
  }

  async getAnalytics(companyId: string, timeframe: string): Promise<any> {
    return this.getVehicleAnalytics(companyId, timeframe, 1);
  }

  /**
   * Generates comprehensive asset ROI and performance analytics.
   */
  async getVehicleAnalytics(
    companyId: string,
    vehicleId: string,
    periodDays = 30,
  ): Promise<FleetAnalyticsResult | null> {
    this.logger.log(
      `Calculating Fleet Analytics for Vehicle ${vehicleId} over ${periodDays} days`,
    );

    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Mock metrics generation. In a real system, these would aggregate `EventStore` streams
      // or `Trip` / `Expense` / `Maintenance` records over the requested period.

      const vehicle = await tx.vehicle.findUnique({ where: { id: vehicleId } });
      if (!vehicle) return null;

      // Mock aggregation logic to satisfy the Enterprise requirements
      const totalPossibleHours = periodDays * 24;

      // Assume 2 breakdowns per month on average
      const breakdowns = 2;
      const downtimeHours = breakdowns * 48; // 48 hrs per breakdown

      // Maintenance & Fuel Costs
      const maintenanceCost = 1500; // Mock $1500
      const totalFuelVolume = 500; // Liters/Gallons
      const totalDistance = 2500; // KM/Miles
      const fuelCost = totalFuelVolume * 1.1;
      const driverCost = totalDistance * 1.5;

      const totalCost = maintenanceCost + fuelCost + driverCost;

      // Derived Metrics
      const fuelEfficiencyKmpl = totalDistance / (totalFuelVolume || 1);
      const costPerKm = totalCost / (totalDistance || 1);
      const availabilityPercentage =
        ((totalPossibleHours - downtimeHours) / totalPossibleHours) * 100;

      // Simulated Utilization (hours driven / available hours)
      const drivingHours = totalDistance / 50; // assuming avg 50 km/h
      const fleetUtilizationPercentage =
        (drivingHours / (totalPossibleHours - downtimeHours)) * 100;

      return {
        fleetUtilizationPercentage: parseFloat(
          fleetUtilizationPercentage.toFixed(2),
        ),
        downtimeHours,
        maintenanceCost,
        fuelEfficiencyKmpl: parseFloat(fuelEfficiencyKmpl.toFixed(2)),
        costPerKm: parseFloat(costPerKm.toFixed(2)),
        breakdownFrequency: breakdowns,
        vehicleAvailabilityPercentage: parseFloat(
          availabilityPercentage.toFixed(2),
        ),
      };
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { MaintenanceEngine } from './maintenance.engine';
import { ComplianceEngine } from './compliance.engine';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

/**
 * Enterprise Fleet Management System Orchestrator.
 * Connects operational events (Dispatch) to Asset Management workflows.
 */
@Injectable()
export class FleetOrchestratorService {
  private readonly logger = new Logger(FleetOrchestratorService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly maintenanceEngine: MaintenanceEngine,
    private readonly complianceEngine: ComplianceEngine,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  @OnEvent('EventStore.*')
  async handleFleetEvents(payload: any) {
    if (!payload || !payload.eventType) return;

    try {
      switch (payload.eventType) {
        // AI Integration: Predictive Maintenance
        case 'BreakdownPredicted':
        case 'MaintenanceRecommended':
          await this.handlePredictiveMaintenance(
            payload.tenantId,
            payload.streamId,
            payload.payload,
            payload.userId,
          );
          break;

        // Trip Completion: Triggers Preventive Maintenance Odometer Checks
        case 'LifecycleStateChangedToCOMPLETED':
          if (payload.streamType === 'TRIP') {
            await this.handleTripCompleted(
              payload.tenantId,
              payload.streamId,
              payload.userId,
            );
          }
          break;

        case 'VehicleYardEntry':
          // Entry triggers automated compliance scans (FASTag, Permits, Insurance)
          // Mock data passed from Yard Management
          const docs = payload.payload.documents || [];
          await this.complianceEngine.evaluateDocumentCompliance(
            payload.tenantId,
            'VEHICLE',
            payload.streamId,
            docs,
          );
          break;
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      this.logger.error(
        `Fleet Orchestration Error: [${payload.eventType}] ${errorMessage}`,
      );
    }
  }

  private async handlePredictiveMaintenance(
    companyId: string,
    vehicleId: string,
    aiPayload: any,
    userId: string,
  ) {
    this.logger.warn(
      `AI Predicts Breakdown/Maintenance for Vehicle ${vehicleId}. Orchestrating response.`,
    );

    // 1. Log Event
    await this.eventStore.append({
      tenantId: companyId,
      streamId: vehicleId,
      streamType: 'VEHICLE',
      eventType: 'VehicleMaintenanceDue',
      payload: { reason: 'AI_PREDICTION', details: aiPayload },
      userId,
    });

    // 2. Transition Vehicle to PAUSED or UNDER_MAINTENANCE to prevent dispatch allocation
    if (aiPayload.severity === 'CRITICAL') {
      const vehicle = await (this.prisma as any).vehicle.findUnique({
        where: { id: vehicleId },
        select: { status: true },
      });
      if (vehicle && vehicle.status === 'ACTIVE') {
        await this.lifecycle.transitionState({
          companyId,
          entityType: 'Vehicle',
          entityId: vehicleId,
          fromState: vehicle.status,
          toState: 'BLOCKED',
          userId: 'SYSTEM',
          reason: 'AI Predicted Critical Breakdown',
        });
      }
    }
  }

  private async handleTripCompleted(
    companyId: string,
    tripId: string,
    userId: string,
  ) {
    // 1. Extract Trip Vehicle & Odometer
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId },
        select: { vehicleId: true, endOdometer: true },
      }),
    );

    if (trip && trip.vehicleId && trip.endOdometer) {
      // 2. Trigger Preventive Maintenance Checks
      await this.maintenanceEngine.checkPreventiveMaintenance(
        companyId,
        trip.vehicleId,
        trip.endOdometer,
      );
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

@Injectable()
export class MaintenanceEngine {
  private readonly logger = new Logger(MaintenanceEngine.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  /**
   * Tracks Preventive Maintenance intervals (Odometer/Calendar).
   */
  async checkPreventiveMaintenance(
    companyId: string,
    vehicleId: string,
    currentOdometer: number,
  ) {
    this.logger.log(
      `Evaluating maintenance schedules for vehicle ${vehicleId}`,
    );

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const vehicle = await tx.vehicle.findUnique({ where: { id: vehicleId } });
      if (!vehicle) return;

      // Dynamic rule checks (In reality, fetch from MaintenanceSchedule table)
      // E.g., Service every 10,000 km
      const lastServiceOdometer = 50000; // Mocked value
      const serviceInterval = 10000;

      if (currentOdometer >= lastServiceOdometer + serviceInterval) {
        this.logger.warn(`Maintenance due for Vehicle ${vehicleId}`);

        await this.eventStore.append({
          tenantId: companyId,
          streamId: vehicleId,
          streamType: 'VEHICLE',
          eventType: 'VehicleMaintenanceDue',
          payload: { reason: 'ODOMETER_INTERVAL', currentOdometer },
          userId: 'SYSTEM',
        });

        // Potentially shift status to 'MAINTENANCE_DUE'
      }
    });
  }

  async completeMaintenance(
    companyId: string,
    vehicleId: string,
    cost: number,
    details: any,
    userId: string,
  ) {
    this.logger.log(`Completing maintenance for ${vehicleId}`);

    // Auto-resume vehicle status via Lifecycle
    const vehicle = await (this.prisma as any).vehicle.findUnique({
      where: { id: vehicleId },
      select: { status: true },
    });
    if (vehicle && vehicle.status === 'UNDER_MAINTENANCE') {
      await this.lifecycle.transitionState({
        companyId,
        entityType: 'Vehicle',
        entityId: vehicleId,
        fromState: vehicle.status,
        toState: 'APPROVED',
        userId,
        reason: 'Maintenance Completed',
      });
    }

    await this.eventStore.append({
      tenantId: companyId,
      streamId: vehicleId,
      streamType: 'VEHICLE',
      eventType: 'MaintenanceCompleted',
      payload: { cost, details },
      userId,
    });
  }
}

