@Injectable()
export class TriggerEngineService {
  private readonly logger = new Logger(TriggerEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly conditionEngine: ConditionEngineService,
    private readonly executionEngine: ExecutionEngineService,
  ) {}

  /**
   * Listen to all events and spawn relevant workflows
   */
  @OnEvent('**')
  async handleDomainEvent(eventName: string, eventPayload: any) {
    if (!eventPayload || !eventPayload.companyId) {
      return;
    }

    const companyId = eventPayload.companyId;

    // Fetch ALL published workflows for the company
    const activeWorkflows = await this.prisma.runAsSystem(async (tx) =>
      tx.workflowDefinition.findMany({
        where: {
          companyId,
          status: 'PUBLISHED',
        },
      }),
    );

    for (const wf of activeWorkflows) {
      if (wf.triggerEvent !== eventName) {
        continue;
      }

      const graph =
        typeof wf.graphPayload === 'string'
          ? JSON.parse(wf.graphPayload)
          : wf.graphPayload;

      // Look for the TRIGGER node in the graph
      const triggerNode = graph?.nodes?.find((n: any) => n.type === 'TRIGGER');
      if (!triggerNode) continue;

      // Evaluate conditions on the trigger node (if any)
      let passesCondition = true;
      if (triggerNode.data && triggerNode.data.condition) {
        passesCondition = this.conditionEngine.evaluate(
          triggerNode.data.condition,
          eventPayload,
        );
      }

      if (passesCondition) {
        this.logger.log(
          `Spawning Workflow Execution for ${wf.name} (Trigger: ${wf.triggerEvent})`,
        );
        await this.executionEngine.startExecution(
          wf.companyId,
          wf.id,
          eventPayload,
          graph,
        );
      }
    }
  }
}

import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { Logger } from '@nestjs/common';
import { ExecutionEngineService } from './execution.service';

@Processor('workflow_execution', { concurrency: 20 })
export class WorkflowExecutionProcessor extends WorkerHost {
  private readonly logger = new Logger(WorkflowExecutionProcessor.name);

  constructor(private executionEngine: ExecutionEngineService) {
    super();
  }

  async process(job: Job<any, any, string>): Promise<any> {
    const { name, data } = job;
    this.logger.log(`Processing Job ${name} for Execution ${data.executionId}`);

    if (name === 'EXECUTE_NODE') {
      await this.executionEngine.executeNode(
        data.companyId,
        data.executionId,
        data.node,
        data.graph,
        data.context,
      );
    } else if (name === 'RESUME_EXECUTION') {
      await this.executionEngine.resumeExecution(
        data.companyId,
        data.executionId,
        data.resumeContext,
      );
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';

@Injectable()
@Processor('background_jobs')
export class WorkflowExecutorService extends WorkerHost {
  private readonly logger = new Logger(WorkflowExecutorService.name);

  async process(job: Job<any, any, string>): Promise<any> {
    this.logger.log(`Processing workflow job ${job.id} of type ${job.name}`);

    try {
      switch (job.name) {
        case 'EXECUTE_DAG':
          return await this.executeDag(job.data);
        case 'WEBHOOK_TRIGGER':
          return await this.handleWebhookTrigger(job.data);
        default:
          this.logger.warn(`Unknown workflow job name: ${job.name}`);
          return { status: 'ignored' };
      }
    } catch (error) {
      this.logger.error(
        `Workflow execution failed: ${error.message}`,
        error.stack,
      );
      throw error; // Will be sent to Dead Letter Queue (DLQ) automatically by BullMQ
    }
  }

  private async executeDag(data: any) {
    // Scaffolded: DAG traversal and node execution
    this.logger.debug('Executing Workflow DAG with nodes and edges...');
    return { status: 'success', executedNodes: 2 };
  }

  private async handleWebhookTrigger(data: any) {
    this.logger.debug('Handling Webhook Trigger...');
    return { status: 'success' };
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class WorkflowService {
  private readonly logger = new Logger(WorkflowService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Create a new Workflow Definition
   * The graphPayload represents a Directed Graph of nodes and edges
   */
  async createWorkflow(companyId: string, data: any, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.workflowDefinition.create({
        data: {
          companyId,
          name: data.name,
          description: data.description,
          triggerEvent: data.triggerEvent,
          graphPayload: data.graphPayload,
          status: 'DRAFT',
          createdBy: userId,
          updatedBy: userId,
        },
      }),
    );
  }

  /**
   * Publish a workflow
   */
  async publishWorkflow(companyId: string, workflowId: string, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.workflowDefinition.update({
        where: { id: workflowId, companyId },
        data: { status: 'PUBLISHED', updatedBy: userId },
      }),
    );
  }

  /**
   * Archive a workflow
   */
  async archiveWorkflow(companyId: string, workflowId: string, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.workflowDefinition.update({
        where: { id: workflowId, companyId },
        data: { status: 'ARCHIVED', updatedBy: userId },
      }),
    );
  }

  /**
   * Get workflow observability metrics
   */
  async getMetrics(companyId: string) {
    const totalExecutions = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.workflowExecution.count({
          where: { companyId },
        }),
    );
    const failedExecutions = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.workflowExecution.count({
          where: { companyId, status: 'FAILED' },
        }),
    );
    const completedExecutions = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.workflowExecution.count({
          where: { companyId, status: 'COMPLETED' },
        }),
    );

    return {
      total: totalExecutions,
      successRate: totalExecutions
        ? ((completedExecutions / totalExecutions) * 100).toFixed(2)
        : 0,
      failureRate: totalExecutions
        ? ((failedExecutions / totalExecutions) * 100).toFixed(2)
        : 0,
    };
  }

  /**
   * Get execution history for a specific workflow
   */
  async getExecutionHistory(companyId: string, workflowId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.workflowExecution.findMany({
        where: { companyId, workflowId },
        include: { steps: true },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }
}

